CREATE TABLE academic_goals (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                student_id TEXT,
                parent_id TEXT,
                goal_title TEXT,
                description TEXT,
                target_grade TEXT,
                target_date TEXT,
                current_progress TEXT,
                status TEXT DEFAULT 'active',
                created_date TEXT,
                FOREIGN KEY (student_id) REFERENCES students (student_id),
                FOREIGN KEY (parent_id) REFERENCES parent_accounts (parent_id)
            );
CREATE TABLE academic_misconduct_cases (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            case_id TEXT UNIQUE NOT NULL,
            student_name TEXT NOT NULL,
            student_id TEXT NOT NULL,
            student_email TEXT,
            course TEXT NOT NULL,
            violation_type TEXT NOT NULL,
            status TEXT DEFAULT 'Under Review',
            date_filed TEXT NOT NULL,
            severity TEXT NOT NULL,
            notes TEXT,
            hearing_date TEXT,
            hearing_time TEXT,
            hearing_location TEXT,
            ruling TEXT,
            ruling_rationale TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            updated_at TEXT DEFAULT CURRENT_TIMESTAMP
        , system_key TEXT NOT NULL DEFAULT 'university');
