CREATE TABLE access_cards (
                card_id INTEGER PRIMARY KEY AUTOINCREMENT,
                card_number TEXT UNIQUE NOT NULL,
                user_id TEXT,
                user_name TEXT,
                card_type TEXT DEFAULT 'staff',
                access_level TEXT,
                buildings_access TEXT,
                issue_date TEXT,
                expiry_date TEXT,
                status TEXT DEFAULT 'active',
                issued_by TEXT,
                notes TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE accessibility_audit_logs (
    log_id INTEGER PRIMARY KEY AUTOINCREMENT,
    page_url TEXT NOT NULL,
    issues_found TEXT,  -- JSON array
    severity TEXT,  -- low, medium, high, critical
    audited_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    audited_by INTEGER
);
CREATE TABLE accessibility_messages (
                    message_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    request_id INTEGER NOT NULL,
                    sender_id TEXT NOT NULL,
                    sender_type TEXT NOT NULL,
                    message TEXT NOT NULL,
                    sent_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    is_read INTEGER DEFAULT 0,
                    FOREIGN KEY (request_id) REFERENCES accommodation_requests(request_id)
                );
CREATE TABLE accessibility_profiles (
            profile_id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL UNIQUE,
            disabilities TEXT,
            accommodations TEXT,
            assistive_technologies TEXT,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (user_id) REFERENCES users(id)
        );
INSERT INTO "accessibility_profiles" VALUES(1,8,'["Visual Impairment"]','["Extended Time"]','["Screen Reader"]','2026-01-22 09:18:05','2026-01-22 09:18:05');
