CREATE TABLE accessibility_settings (
            setting_id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL UNIQUE,
            theme TEXT DEFAULT 'standard',
            font_size INTEGER DEFAULT 16,
            contrast_level TEXT DEFAULT 'normal',
            screen_reader_enabled BOOLEAN DEFAULT 0,
            keyboard_navigation BOOLEAN DEFAULT 0,
            FOREIGN KEY (user_id) REFERENCES users(id)
        );
INSERT INTO "accessibility_settings" VALUES(1,8,'high_contrast',18,'normal',1,0);
INSERT INTO "accessibility_settings" VALUES(2,9,'high_contrast',20,'normal',1,1);
CREATE TABLE accommodation_approvals (
    approval_id INTEGER PRIMARY KEY AUTOINCREMENT,
    request_id INTEGER NOT NULL,
    approved_by INTEGER NOT NULL,
    approved_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    notes TEXT,
    FOREIGN KEY (request_id) REFERENCES accommodation_requests(request_id)
);
CREATE TABLE accommodation_documentation (
                    doc_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    request_id INTEGER NOT NULL,
                    student_id TEXT NOT NULL,
                    filename TEXT NOT NULL,
                    file_path TEXT NOT NULL,
                    upload_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    document_type TEXT,
                    FOREIGN KEY (request_id) REFERENCES accommodation_requests(request_id)
                );
CREATE TABLE accommodation_documents (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    accommodation_id INTEGER NOT NULL,
                    document_name TEXT NOT NULL,
                    document_path TEXT NOT NULL,
                    uploaded_by TEXT,
                    uploaded_at TEXT,
                    FOREIGN KEY (accommodation_id) REFERENCES accommodations(id)
                );
CREATE TABLE accommodation_renewals (
                    renewal_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    accommodation_id INTEGER NOT NULL,
                    student_id TEXT NOT NULL,
                    renewal_request_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    status TEXT NOT NULL,
                    processed_date TIMESTAMP,
                    processed_by TEXT,
                    notes TEXT,
                    FOREIGN KEY (accommodation_id) REFERENCES accommodations(accommodation_id)
                );
CREATE TABLE accommodation_requests (
    request_id INTEGER PRIMARY KEY AUTOINCREMENT,
    student_id INTEGER NOT NULL,
    accommodation_type TEXT NOT NULL,  -- extended_time, alternative_format, etc.
    description TEXT,
    status TEXT DEFAULT 'pending',  -- pending, approved, denied
    requested_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    reviewed_by INTEGER,
    review_date TIMESTAMP,
    review_notes TEXT, student_name TEXT, student_email TEXT, submitted_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP, reviewer_notes TEXT,
    FOREIGN KEY (student_id) REFERENCES students(student_id)
);
CREATE TABLE accommodation_templates (
                    name TEXT PRIMARY KEY,
                    accommodation_type TEXT NOT NULL,
                    description TEXT,
                    start_offset_days INTEGER,
                    duration_days INTEGER,
                    created_by TEXT,
                    created_at TEXT,
                    updated_at TEXT
                );
