CREATE TABLE ai_chatbot_conversations (
            conversation_id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id TEXT NOT NULL,
            user_type TEXT NOT NULL,
            start_time TEXT DEFAULT CURRENT_TIMESTAMP,
            end_time TEXT,
            message_count INTEGER DEFAULT 0,
            satisfaction_rating INTEGER,
            was_helpful BOOLEAN,
            escalated_to_human BOOLEAN DEFAULT 0
        );
CREATE TABLE ai_chatbot_messages (
            message_id INTEGER PRIMARY KEY AUTOINCREMENT,
            conversation_id INTEGER NOT NULL,
            sender_type TEXT NOT NULL,
            message_text TEXT NOT NULL,
            intent_detected TEXT,
            confidence_score REAL,
            timestamp TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (conversation_id) REFERENCES ai_chatbot_conversations (conversation_id)
        );
CREATE TABLE ai_content_suggestions (
            suggestion_id INTEGER PRIMARY KEY AUTOINCREMENT,
            content_type TEXT NOT NULL,
            context TEXT NOT NULL,
            suggested_content TEXT NOT NULL,
            relevance_score REAL,
            source TEXT,
            was_used BOOLEAN DEFAULT 0,
            created_for TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE ai_detector_metadata (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                submission_id INTEGER NOT NULL,
                time_taken INTEGER,
                browser_info TEXT,
                device_fingerprint TEXT,
                ip_address TEXT,
                location_data TEXT,
                keystroke_data TEXT,
                FOREIGN KEY (submission_id) REFERENCES ai_detector_submissions (id)
            );
CREATE TABLE ai_detector_results (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                submission_id INTEGER NOT NULL,
                ai_score REAL NOT NULL,
                confidence REAL NOT NULL,
                detailed_results TEXT,
                created_at TEXT NOT NULL,
                style_deviation REAL,
                FOREIGN KEY (submission_id) REFERENCES ai_detector_submissions (id)
            );
CREATE TABLE ai_detector_submissions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                student_id TEXT NOT NULL,
                submission_text TEXT NOT NULL,
                title TEXT,
                course_code TEXT,
                assignment_id TEXT,
                submission_date TEXT NOT NULL,
                word_count INTEGER,
                character_count INTEGER,
                institution_id TEXT
            );
CREATE TABLE ai_grading_results (
            grading_id INTEGER PRIMARY KEY AUTOINCREMENT,
            submission_id INTEGER NOT NULL,
            assignment_type TEXT NOT NULL,
            auto_score REAL,
            max_score REAL,
            grading_criteria TEXT,
            feedback_generated TEXT,
            confidence_score REAL,
            requires_manual_review BOOLEAN DEFAULT 0,
            manual_override_score REAL,
            graded_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE ai_model_performance (
            performance_id INTEGER PRIMARY KEY AUTOINCREMENT,
            model_name TEXT NOT NULL,
            model_version TEXT NOT NULL,
            metric_name TEXT NOT NULL,
            metric_value REAL NOT NULL,
            test_dataset TEXT,
            measured_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE ai_plagiarism_checks (
            check_id INTEGER PRIMARY KEY AUTOINCREMENT,
            submission_id INTEGER NOT NULL,
            student_id TEXT NOT NULL,
            document_text TEXT NOT NULL,
            similarity_score REAL,
            matched_sources TEXT,
            flagged BOOLEAN DEFAULT 0,
            review_status TEXT DEFAULT 'pending',
            checked_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE ai_recommendations (
            recommendation_id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id TEXT NOT NULL,
            recommendation_type TEXT NOT NULL,
            recommendation_content TEXT NOT NULL,
            algorithm_used TEXT,
            confidence_score REAL,
            context_data TEXT,
            was_accepted BOOLEAN,
            feedback_rating INTEGER,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE ai_sentiment_analysis (
            analysis_id INTEGER PRIMARY KEY AUTOINCREMENT,
            content_id TEXT NOT NULL,
            content_type TEXT NOT NULL,
            content_text TEXT NOT NULL,
            sentiment_score REAL,
            sentiment_category TEXT,
            emotions_detected TEXT,
            key_phrases TEXT,
            analyzed_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE aid_components (
    component_id INTEGER PRIMARY KEY AUTOINCREMENT,
    package_id INTEGER NOT NULL,
    aid_type TEXT NOT NULL,  -- grant, scholarship, loan, work_study
    source TEXT,  -- federal, state, institutional, private
    name TEXT NOT NULL,
    amount REAL NOT NULL,
    disbursement_plan TEXT,  -- JSON: [{term: 'Fall', amount: 1000}, ...]
    terms_conditions TEXT,
    is_need_based BOOLEAN DEFAULT 0,
    is_renewable BOOLEAN DEFAULT 0,
    status TEXT DEFAULT 'offered',
    FOREIGN KEY (package_id) REFERENCES aid_packages(package_id) ON DELETE CASCADE
);
CREATE TABLE aid_packages (
    package_id INTEGER PRIMARY KEY AUTOINCREMENT,
    student_id INTEGER NOT NULL,
    academic_year TEXT NOT NULL,
    total_aid_amount REAL DEFAULT 0,
    total_grants REAL DEFAULT 0,
    total_scholarships REAL DEFAULT 0,
    total_loans REAL DEFAULT 0,
    total_work_study REAL DEFAULT 0,
    package_status TEXT DEFAULT 'offered',  -- offered, accepted, declined, revised
    offered_date DATE,
    response_deadline DATE,
    response_date DATE,
    created_by INTEGER,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (student_id) REFERENCES students(student_id),
    UNIQUE(student_id, academic_year)
);
CREATE TABLE alerts (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                alert_type TEXT,
                message TEXT,
                severity TEXT DEFAULT 'medium',
                triggered_at DATETIME DEFAULT CURRENT_TIMESTAMP,
                acknowledged BOOLEAN DEFAULT FALSE,
                resolved BOOLEAN DEFAULT FALSE,
                resolved_at DATETIME,
                user_id TEXT,
                metadata TEXT
            );
CREATE TABLE allergies (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT,
                    allergen TEXT,
                    severity TEXT,
                    reaction_description TEXT,
                    diagnosed_date TEXT,
                    provider TEXT,
                    verified INTEGER DEFAULT 0,
                    created_at TEXT,
                    FOREIGN KEY (student_id) REFERENCES students (student_id)
                );
CREATE TABLE alternative_materials (
    material_id INTEGER PRIMARY KEY AUTOINCREMENT,
    course_id INTEGER NOT NULL,
    original_material_id INTEGER,
    format_type TEXT NOT NULL,  -- braille, audio, large_print, digital
    file_url TEXT,
    created_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    created_by INTEGER
);
CREATE TABLE alumni (
            alumni_id TEXT PRIMARY KEY,
            student_id TEXT,
            email_address TEXT,
            title TEXT,
            first_name TEXT,
            middle_name TEXT,
            last_name TEXT,
            gender TEXT,
            dob TEXT,
            graduation_year INTEGER,
            degree_earned TEXT,
            current_employer TEXT,
            job_title TEXT,
            industry TEXT,
            address TEXT,
            city TEXT,
            country TEXT,
            phone TEXT,
            linkedin_url TEXT,
            date_registered TEXT,
            is_donor BOOLEAN,
            is_mentor BOOLEAN,
            is_board_member BOOLEAN,
            profile_photo TEXT,
            bio TEXT,
            skills TEXT,
            achievements TEXT,
            privacy_level INTEGER DEFAULT 1,
            engagement_score INTEGER DEFAULT 0,
            last_activity TEXT,
            social_media_links TEXT,
            is_ambassador BOOLEAN DEFAULT 0,
            FOREIGN KEY (student_id) REFERENCES students (student_id)
        );
CREATE TABLE alumni_achievements (
            achievement_id INTEGER PRIMARY KEY AUTOINCREMENT,
            alumni_id TEXT,
            achievement_title TEXT,
            achievement_description TEXT,
            achievement_date TEXT,
            category TEXT,
            verification_status TEXT DEFAULT 'pending',
            verified_by TEXT,
            FOREIGN KEY (alumni_id) REFERENCES alumni (alumni_id)
        );
CREATE TABLE alumni_badges (
            alumni_badge_id INTEGER PRIMARY KEY AUTOINCREMENT,
            alumni_id TEXT,
            badge_id INTEGER,
            earned_date TEXT,
            FOREIGN KEY (alumni_id) REFERENCES alumni (alumni_id),
            FOREIGN KEY (badge_id) REFERENCES achievement_badges (badge_id)
        );
CREATE TABLE alumni_chapter_memberships (
            membership_id INTEGER PRIMARY KEY AUTOINCREMENT,
            chapter_id INTEGER NOT NULL,
            alumni_id INTEGER NOT NULL,
            join_date TEXT DEFAULT CURRENT_DATE,
            membership_status TEXT DEFAULT 'active',
            FOREIGN KEY (chapter_id) REFERENCES alumni_chapters (chapter_id),
            FOREIGN KEY (alumni_id) REFERENCES alumni_profiles (alumni_id)
        );
CREATE TABLE alumni_chapters (
            chapter_id INTEGER PRIMARY KEY AUTOINCREMENT,
            chapter_name TEXT NOT NULL,
            region TEXT NOT NULL,
            chapter_leader_id INTEGER,
            contact_email TEXT,
            description TEXT,
            meeting_frequency TEXT,
            is_active BOOLEAN DEFAULT 1,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (chapter_leader_id) REFERENCES alumni_profiles (alumni_id)
        );
CREATE TABLE alumni_directory_settings (
            alumni_id TEXT PRIMARY KEY,
            show_contact_info BOOLEAN DEFAULT 1,
            show_employment BOOLEAN DEFAULT 1,
            show_education BOOLEAN DEFAULT 1,
            searchable BOOLEAN DEFAULT 1,
            networking_available BOOLEAN DEFAULT 1,
            mentor_available BOOLEAN DEFAULT 0,
            FOREIGN KEY (alumni_id) REFERENCES alumni (alumni_id)
        );
CREATE TABLE alumni_donations (
            donation_id INTEGER PRIMARY KEY AUTOINCREMENT,
            alumni_id INTEGER NOT NULL,
            donation_amount REAL NOT NULL,
            donation_date TEXT DEFAULT CURRENT_DATE,
            donation_type TEXT NOT NULL,
            fund_designation TEXT,
            campaign_id INTEGER,
            payment_method TEXT,
            is_recurring BOOLEAN DEFAULT 0,
            recurrence_frequency TEXT,
            tax_receipt_sent BOOLEAN DEFAULT 0,
            acknowledgment_sent BOOLEAN DEFAULT 0,
            FOREIGN KEY (alumni_id) REFERENCES alumni_profiles (alumni_id)
        );
CREATE TABLE alumni_event_registrations (
            registration_id INTEGER PRIMARY KEY AUTOINCREMENT,
            event_id INTEGER NOT NULL,
            alumni_id INTEGER NOT NULL,
            num_guests INTEGER DEFAULT 0,
            registration_date TEXT DEFAULT CURRENT_TIMESTAMP,
            payment_status TEXT DEFAULT 'pending',
            attended BOOLEAN DEFAULT 0,
            FOREIGN KEY (event_id) REFERENCES alumni_events (event_id),
            FOREIGN KEY (alumni_id) REFERENCES alumni_profiles (alumni_id)
        );
CREATE TABLE alumni_events (
            event_id INTEGER PRIMARY KEY AUTOINCREMENT,
            event_name TEXT,
            event_date TEXT,
            event_location TEXT,
            event_description TEXT,
            registration_required BOOLEAN,
            max_attendees INTEGER,
            event_fee REAL DEFAULT 0.0,
            payment_required BOOLEAN DEFAULT 0,
            event_type TEXT DEFAULT 'in-person',
            virtual_link TEXT,
            qr_code_path TEXT,
            created_by TEXT,
            created_date TEXT,
            registration_deadline TEXT,
            waitlist_enabled BOOLEAN DEFAULT 1
        );
CREATE TABLE alumni_forum (
            post_id INTEGER PRIMARY KEY AUTOINCREMENT,
            author_id TEXT,
            title TEXT,
            content TEXT,
            category TEXT,
            post_date TEXT,
            last_updated TEXT,
            reply_count INTEGER DEFAULT 0,
            view_count INTEGER DEFAULT 0,
            is_pinned BOOLEAN DEFAULT 0,
            FOREIGN KEY (author_id) REFERENCES alumni (alumni_id)
        );
CREATE TABLE alumni_mentors (
            mentor_id INTEGER PRIMARY KEY AUTOINCREMENT,
            alumni_student_id TEXT NOT NULL,
            job_title TEXT,
            company TEXT,
            industry TEXT,
            expertise_areas TEXT,
            max_mentees INTEGER DEFAULT 3,
            is_active BOOLEAN DEFAULT 1,
            bio TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE alumni_profiles (
            alumni_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL UNIQUE,
            graduation_year INTEGER NOT NULL,
            degree_earned TEXT NOT NULL,
            major TEXT,
            current_employer TEXT,
            current_position TEXT,
            current_industry TEXT,
            current_location TEXT,
            linkedin_url TEXT,
            personal_website TEXT,
            biography TEXT,
            willing_to_mentor BOOLEAN DEFAULT 0,
            willing_to_recruit BOOLEAN DEFAULT 0,
            privacy_level TEXT DEFAULT 'public',
