CREATE TABLE assistive_tech_requests (
    request_id INTEGER PRIMARY KEY AUTOINCREMENT,
    student_id INTEGER NOT NULL,
    technology_type TEXT NOT NULL,  -- screen_reader, magnifier, etc.
    status TEXT DEFAULT 'pending',
    requested_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    fulfilled_date TIMESTAMP,
    FOREIGN KEY (student_id) REFERENCES students(student_id)
);
CREATE TABLE attendance (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT,
            module_code TEXT,
            date TEXT,
            status TEXT,
            reason TEXT,
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (module_code) REFERENCES modules (module_code)
        );
CREATE TABLE attendance_alerts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            alert_id TEXT UNIQUE,
            student_id TEXT,
            module_code TEXT,
            alert_type TEXT,
            severity TEXT,
            message TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            sent_at TEXT,
            acknowledged_at TEXT,
            status TEXT DEFAULT 'pending',
            recipient_email TEXT,
            recipient_phone TEXT,
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (module_code) REFERENCES modules (module_code)
        );
CREATE TABLE attendance_analytics (
            analytics_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT,
            attendance_percentage REAL,
            consecutive_absences INTEGER
        );
CREATE TABLE attendance_appeals (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            appeal_id TEXT UNIQUE,
            student_id TEXT,
            module_code TEXT,
            attendance_record_id INTEGER,
            original_status TEXT,
            requested_status TEXT,
            reason TEXT,
            evidence_files TEXT,
            submitted_at TEXT DEFAULT CURRENT_TIMESTAMP,
            reviewed_by TEXT,
            reviewed_at TEXT,
            decision TEXT,
            decision_reason TEXT,
            status TEXT DEFAULT 'pending',
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (module_code) REFERENCES modules (module_code),
            FOREIGN KEY (attendance_record_id) REFERENCES attendance_records (id)
        );
CREATE TABLE attendance_audit_log (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id TEXT,
            action TEXT,
            table_name TEXT,
            record_id TEXT,
            old_values TEXT,
            new_values TEXT,
            timestamp TEXT DEFAULT CURRENT_TIMESTAMP,
            ip_address TEXT,
            user_agent TEXT
        );
CREATE TABLE attendance_calendar_links (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                attendance_record_id INTEGER,
                event_id TEXT,
                module_code TEXT,
                date TEXT,
                created_at TEXT,
                FOREIGN KEY (attendance_record_id) REFERENCES attendance_records (id),
                FOREIGN KEY (event_id) REFERENCES "academic_calendar_events" (id)
            );
CREATE TABLE attendance_gamification (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT,
            points INTEGER DEFAULT 0,
            level INTEGER DEFAULT 1,
            badges TEXT,
            achievements TEXT,
            streak_days INTEGER DEFAULT 0,
            best_streak INTEGER DEFAULT 0,
            last_attendance_date TEXT,
            total_rewards INTEGER DEFAULT 0,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (student_id) REFERENCES students (student_id)
        );
CREATE TABLE attendance_policies (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            policy_id TEXT UNIQUE,
            name TEXT,
            description TEXT,
            module_code TEXT,
            course TEXT,
            min_attendance_percentage REAL,
            max_consecutive_absences INTEGER,
            late_tolerance_minutes INTEGER DEFAULT 15,
            makeup_allowed BOOLEAN DEFAULT 1,
            auto_fail_threshold REAL,
            grace_period_days INTEGER DEFAULT 0,
            effective_from TEXT,
            effective_until TEXT,
            created_by TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            status TEXT DEFAULT 'active'
        );
CREATE TABLE attendance_predictions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT,
            module_code TEXT,
            prediction_date TEXT,
            predicted_attendance_rate REAL,
            risk_level TEXT,
            confidence_score REAL,
            factors TEXT,
            recommendations TEXT,
            model_version TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (module_code) REFERENCES modules (module_code)
        );
CREATE TABLE attendance_records (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT,
            module_code TEXT,
            date TEXT,
            status TEXT,
            notes TEXT,
            recorded_by TEXT,
            recorded_at TEXT,
            check_in_method TEXT DEFAULT 'manual',
            location_data TEXT,
            ip_address TEXT,
            session_id TEXT,
            makeup_for_date TEXT,
            verification_status TEXT DEFAULT 'verified',
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (module_code) REFERENCES modules (module_code)
        );
