CREATE TABLE badge_issuances (
    issuance_id INTEGER PRIMARY KEY AUTOINCREMENT,
    badge_id INTEGER NOT NULL,
    student_id INTEGER NOT NULL,
    issued_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    blockchain_hash TEXT,
    evidence_url TEXT,
    expires_at DATE,
    is_revoked BOOLEAN DEFAULT 0,
    FOREIGN KEY (badge_id) REFERENCES digital_badges(badge_id),
    FOREIGN KEY (student_id) REFERENCES students(student_id)
);
CREATE TABLE badges (
                    badge_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL,
                    badge_type TEXT NOT NULL CHECK(badge_type IN (
                        'deans_list', 'club_officer', 'volunteer_hours',
                        'certification', 'competition_winner', 'scholarship',
                        'research_publication', 'leadership', 'academic_excellence',
                        'community_service', 'skill_mastery', 'innovation'
                    )),
                    badge_name TEXT NOT NULL,
                    description TEXT,
                    issuer TEXT NOT NULL,
                    issue_date DATE NOT NULL,
                    expiry_date DATE,
                    verification_status TEXT DEFAULT 'verified' CHECK(verification_status IN (
                        'pending', 'verified', 'expired', 'revoked'
                    )),
                    verification_code TEXT,
                    metadata TEXT,
                    icon_url TEXT,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (student_id) REFERENCES students(student_id)
                );
CREATE TABLE bar_inventory_transactions (
                transaction_id INTEGER PRIMARY KEY AUTOINCREMENT,
                item_id INTEGER,
                quantity_change INTEGER,
                transaction_type TEXT,
                transaction_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                notes TEXT,
                FOREIGN KEY (item_id) REFERENCES bar_menu_items(item_id)
            );
