INSERT INTO "books" VALUES('B10001','Diary of a Wimpy Kid','Jeff Kinney','0141324902','Penguin Books India','Fiction',2007,'Greg Heffley finds himself in a new year and school where undersize weaklings share the corridors with kids who are taller and meaner. Desperate to prove his maturity, Greg is happy to have his sidekick, Rowley, along for the ride. But when Rowley''s star starts to rise, Greg tries to use his best friend''s popularity to his own advantage.','','available','2025-12-13 21:38:17','2025-12-13 21:38:17','','[]',NULL,NULL,0.0,'LIBFA72FABC61B6','/home/seancatchpole989/university_system/qr_codes/book_B10001.png',NULL,'English',NULL,NULL,15.0,'','',1);
CREATE TABLE breakout_rooms (
    room_id INTEGER PRIMARY KEY AUTOINCREMENT,
    session_id INTEGER NOT NULL,
    room_name TEXT NOT NULL,
    room_number INTEGER,
    participants TEXT,  -- JSON array of user_ids
    facilitator_id INTEGER,
    max_capacity INTEGER DEFAULT 10,
    topic TEXT,
    start_time TIMESTAMP,
    end_time TIMESTAMP,
    duration INTEGER,  -- minutes
    is_active BOOLEAN DEFAULT 0,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (session_id) REFERENCES virtual_sessions(session_id) ON DELETE CASCADE
);
CREATE TABLE buddy_requests (
                request_id INTEGER PRIMARY KEY AUTOINCREMENT,
                sender_id TEXT NOT NULL,
                receiver_id TEXT NOT NULL,
                request_type TEXT NOT NULL,
                destination TEXT,
                message TEXT,
                status TEXT DEFAULT 'pending',
                sent_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                responded_at TIMESTAMP,
                FOREIGN KEY (sender_id) REFERENCES users(username),
                FOREIGN KEY (receiver_id) REFERENCES users(username)
            );
CREATE TABLE budget_alerts (
                        alert_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        student_id TEXT NOT NULL,
                        budget_id INTEGER,
                        category_id INTEGER,
                        alert_type TEXT CHECK(alert_type IN ('overspending', 'low-balance', 'goal-milestone', 'recurring-expense', 'custom')),
                        threshold_type TEXT CHECK(threshold_type IN ('percentage', 'amount')),
                        threshold_value REAL NOT NULL,
                        message TEXT NOT NULL,
                        is_active BOOLEAN DEFAULT 1,
                        last_triggered TEXT,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        FOREIGN KEY (student_id) REFERENCES students(student_id),
                        FOREIGN KEY (budget_id) REFERENCES student_budgets(budget_id),
                        FOREIGN KEY (category_id) REFERENCES budget_categories(category_id)
                    );
CREATE TABLE budget_categories (
            category_id INTEGER PRIMARY KEY AUTOINCREMENT,
            category_name TEXT NOT NULL,
            category_type TEXT NOT NULL, -- 'revenue', 'expense'
            parent_category_id INTEGER,
            is_active BOOLEAN DEFAULT 1,
            created_at TEXT,
            updated_at TEXT,
            FOREIGN KEY (parent_category_id) REFERENCES budget_categories (category_id)
        );
