CREATE TABLE campus_job_applications (
                        application_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        job_id INTEGER NOT NULL,
                        student_id TEXT NOT NULL,
                        cover_letter TEXT,
                        resume_url TEXT,
                        availability TEXT,
                        expected_hours_per_week INTEGER,
                        reference_contacts TEXT,
                        application_date TEXT DEFAULT (date('now')),
                        status TEXT DEFAULT 'pending' CHECK(status IN ('pending', 'reviewed', 'interview', 'offered', 'accepted', 'rejected', 'withdrawn')),
                        reviewed_by INTEGER,
                        reviewed_date TEXT,
                        notes TEXT,
                        interview_date TEXT,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        FOREIGN KEY (job_id) REFERENCES campus_job_postings(job_id),
                        FOREIGN KEY (student_id) REFERENCES students(student_id),
                        FOREIGN KEY (reviewed_by) REFERENCES users(id)
                    );
CREATE TABLE campus_job_postings (
                        job_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        department_id INTEGER,
                        employer_name TEXT NOT NULL,
                        job_title TEXT NOT NULL,
                        job_category TEXT NOT NULL,
                        employment_type TEXT NOT NULL CHECK(employment_type IN ('work-study', 'part-time', 'internship', 'temp')),
                        hourly_rate REAL NOT NULL,
                        hours_per_week INTEGER,
                        total_positions INTEGER DEFAULT 1,
                        filled_positions INTEGER DEFAULT 0,
                        job_description TEXT NOT NULL,
                        required_skills TEXT,
                        preferred_skills TEXT,
                        minimum_gpa REAL DEFAULT 0.0,
                        work_authorization_required BOOLEAN DEFAULT 0,
                        location TEXT NOT NULL,
                        schedule_flexibility TEXT,
                        start_date TEXT,
                        end_date TEXT,
                        application_deadline TEXT,
                        contact_email TEXT,
                        contact_phone TEXT,
                        posted_by INTEGER,
                        posted_date TEXT DEFAULT (date('now')),
                        is_active BOOLEAN DEFAULT 1,
                        is_work_study BOOLEAN DEFAULT 0,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        FOREIGN KEY (posted_by) REFERENCES users(id)
                    );
CREATE TABLE campus_routes (
                    route_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    route_name TEXT NOT NULL,
                    start_location_id INTEGER NOT NULL,
                    end_location_id INTEGER NOT NULL,
                    route_type TEXT DEFAULT 'Walking',
                    is_accessible BOOLEAN DEFAULT 1,
                    distance_meters REAL NOT NULL,
                    estimated_time_minutes INTEGER NOT NULL,
                    waypoints TEXT,
                    description TEXT,
                    elevation_change REAL DEFAULT 0,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (start_location_id) REFERENCES campus_buildings(building_id),
                    FOREIGN KEY (end_location_id) REFERENCES campus_buildings(building_id)
                );
