            status TEXT DEFAULT 'scheduled',
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE care_plans (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT,
                    condition_id INTEGER,
                    plan_name TEXT,
                    description TEXT,
                    start_date TEXT,
                    end_date TEXT,
                    provider TEXT,
                    status TEXT DEFAULT 'active',
                    goals TEXT,
                    interventions TEXT,
                    created_at TEXT,
