            FOREIGN KEY (client_id) REFERENCES alumni (alumni_id)
        );
CREATE TABLE career_event_registrations (
            registration_id INTEGER PRIMARY KEY AUTOINCREMENT,
            event_id INTEGER NOT NULL,
            student_id TEXT NOT NULL,
            registered_at TEXT DEFAULT CURRENT_TIMESTAMP,
            attended BOOLEAN DEFAULT 0,
            feedback TEXT,
            FOREIGN KEY (event_id) REFERENCES career_events (event_id),
            FOREIGN KEY (student_id) REFERENCES students (student_id)
        );
CREATE TABLE career_events (
            event_id INTEGER PRIMARY KEY AUTOINCREMENT,
            event_name TEXT NOT NULL,
            event_type TEXT NOT NULL,
            event_date TEXT NOT NULL,
            event_time TEXT NOT NULL,
            location TEXT,
            description TEXT,
            max_attendees INTEGER,
            registration_deadline TEXT,
            is_published BOOLEAN DEFAULT 0,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE carrental_insurance (
                    insurance_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL,
                    description TEXT,
                    daily_rate DECIMAL(10,2) NOT NULL,
                    coverage_type TEXT,
                    max_coverage DECIMAL(10,2),
                    deductible DECIMAL(10,2) DEFAULT 0,
                    is_active INTEGER DEFAULT 1,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE carrental_maintenance (
                    maintenance_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    vehicle_id INTEGER NOT NULL,
                    maintenance_type TEXT NOT NULL,
                    description TEXT,
                    cost DECIMAL(10,2) DEFAULT 0,
                    service_date TEXT NOT NULL,
                    next_service_date TEXT,
                    mileage_at_service INTEGER,
                    performed_by TEXT,
                    notes TEXT,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (vehicle_id) REFERENCES carrental_vehicles(vehicle_id)
                );
CREATE TABLE carrental_refunds (
                        refund_id INTEGER PRIMARY KEY AUTOINCREMENT,
