                        customer_id TEXT,
                        amount DECIMAL(10,2),
                        refund_method TEXT,
                        refund_reference TEXT,
                        refunded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        processed_by TEXT,
                        FOREIGN KEY (transaction_id) REFERENCES carrental_transactions(transaction_id)
                    );
