                    user_name TEXT NOT NULL,
                    user_email TEXT,
                    user_phone TEXT,
                    date_of_birth DATE,
                    address TEXT,
                    emergency_contact TEXT,
                    emergency_phone TEXT,
                    medical_history TEXT,
                    allergies TEXT,
                    insurance_provider TEXT,
