CREATE TABLE dentist_prescriptions (
                    prescription_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    patient_id INTEGER NOT NULL,
                    dentist_id TEXT NOT NULL,
                    dentist_name TEXT NOT NULL,
                    treatment_id INTEGER,
                    medication TEXT NOT NULL,
                    dosage TEXT NOT NULL,
                    frequency TEXT NOT NULL,
                    duration TEXT NOT NULL,
                    instructions TEXT,
                    prescribed_date DATE NOT NULL,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (patient_id) REFERENCES dentist_patients(patient_id),
                    FOREIGN KEY (treatment_id) REFERENCES dentist_treatments(treatment_id)
                );
CREATE TABLE dentist_records (
                    record_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    patient_id INTEGER NOT NULL,
                    record_type TEXT NOT NULL,
                    record_date DATE NOT NULL,
                    description TEXT,
                    file_path TEXT,
                    created_by TEXT,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (patient_id) REFERENCES dentist_patients(patient_id)
                );
CREATE TABLE dentist_transactions (
                    transaction_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    reference TEXT UNIQUE NOT NULL,
                    patient_id INTEGER NOT NULL,
                    user_id TEXT NOT NULL,
                    treatment_id INTEGER,
                    transaction_type TEXT NOT NULL,
                    amount DECIMAL(10,2) NOT NULL,
                    payment_method TEXT,
                    status TEXT DEFAULT 'completed',
                    receipt_sent INTEGER DEFAULT 0,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    processed_by TEXT,
                    FOREIGN KEY (patient_id) REFERENCES dentist_patients(patient_id),
                    FOREIGN KEY (treatment_id) REFERENCES dentist_treatments(treatment_id)
                );
