CREATE TABLE department_kpis (
                kpi_id INTEGER PRIMARY KEY AUTOINCREMENT,
                department TEXT NOT NULL,
                kpi_name TEXT NOT NULL,
                kpi_description TEXT,
                kpi_category TEXT,
                target_value REAL,
                current_value REAL DEFAULT 0,
                unit TEXT,
                period TEXT DEFAULT 'annual',
                academic_year TEXT,
                quarter TEXT,
                status TEXT DEFAULT 'on_track',
                owner_id TEXT,
                owner_name TEXT,
                last_updated TEXT,
                notes TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE departments (
            dept_id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL UNIQUE,
            description TEXT,
            manager_id INTEGER,
            email TEXT,
            sla_policy_id INTEGER,
            is_active BOOLEAN DEFAULT 1,
            created_at TEXT,
            updated_at TEXT,
            FOREIGN KEY (manager_id) REFERENCES users (id),
            FOREIGN KEY (sla_policy_id) REFERENCES sla_policies (sla_id)
        );
CREATE TABLE digests (
                    digest_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT NOT NULL,
                    digest_date DATE NOT NULL,
                    sent_at TIMESTAMP,
                    notification_count INTEGER DEFAULT 0,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    UNIQUE(user_id, digest_date),
                    FOREIGN KEY (user_id) REFERENCES users(username)
                );
CREATE TABLE digital_badges (
    badge_id INTEGER PRIMARY KEY AUTOINCREMENT,
    badge_name TEXT NOT NULL,
    description TEXT,
    criteria TEXT NOT NULL,
    badge_image_url TEXT,
    issuer_name TEXT NOT NULL,
    badge_type TEXT DEFAULT 'skill',  -- skill, achievement, completion
    is_active BOOLEAN DEFAULT 1,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE digital_library (
            digital_id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            author TEXT NOT NULL,
            file_path TEXT NOT NULL,
            file_type TEXT NOT NULL,
            file_size INTEGER,
            category TEXT,
            description TEXT,
            access_level TEXT DEFAULT 'public',
            download_count INTEGER DEFAULT 0,
            added_date TEXT NOT NULL
        );
CREATE TABLE disability_documentation (
    doc_id INTEGER PRIMARY KEY AUTOINCREMENT,
    student_id INTEGER NOT NULL,
    disability_type TEXT NOT NULL,
    file_url TEXT,
    uploaded_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    expiry_date DATE,
    verified_by INTEGER,
    verified_date TIMESTAMP,
    FOREIGN KEY (student_id) REFERENCES students(student_id)
);
CREATE TABLE disbursements (
    disbursement_id INTEGER PRIMARY KEY AUTOINCREMENT,
    award_id INTEGER,
    component_id INTEGER,
    student_id INTEGER NOT NULL,
    amount REAL NOT NULL,
    disbursement_type TEXT,  -- scholarship, grant, loan, work_study
    disbursement_date DATE NOT NULL,
    scheduled_date DATE,
    academic_term TEXT,  -- Fall, Spring, Summer
    status TEXT DEFAULT 'pending',  -- pending, processed, failed, cancelled
    payment_method TEXT DEFAULT 'account_credit',
    transaction_id TEXT,
    processed_by INTEGER,
    processed_at TIMESTAMP,
    error_message TEXT,
    FOREIGN KEY (award_id) REFERENCES scholarship_awards(award_id),
    FOREIGN KEY (component_id) REFERENCES aid_components(component_id),
    FOREIGN KEY (student_id) REFERENCES students(student_id)
);
CREATE TABLE disciplinary_actions (
                    action_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    record_id INTEGER NOT NULL,
                    action_type TEXT NOT NULL,
                    action_level TEXT,
                    effective_date TEXT NOT NULL,
                    end_date TEXT,
                    duration_days INTEGER,
                    imposed_by TEXT NOT NULL,
                    reason TEXT,
                    conditions TEXT,
                    appeal_deadline TEXT,
                    appeal_submitted BOOLEAN DEFAULT 0,
                    appeal_outcome TEXT,
                    document_path TEXT,
                    acknowledged_by_employee BOOLEAN DEFAULT 0,
                    acknowledged_date TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (record_id) REFERENCES disciplinary_records(record_id)
                );
CREATE TABLE disciplinary_appeals (
                    appeal_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    action_id INTEGER NOT NULL,
                    appellant_id TEXT NOT NULL,
                    appeal_date TEXT NOT NULL,
                    grounds TEXT NOT NULL,
                    supporting_documents TEXT,
                    status TEXT DEFAULT 'submitted',
                    hearing_date TEXT,
                    panel_members TEXT,
                    outcome TEXT,
                    outcome_date TEXT,
                    outcome_details TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (action_id) REFERENCES disciplinary_actions(action_id)
                );
CREATE TABLE disciplinary_records (
                    record_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    reference_number TEXT UNIQUE,
                    user_id TEXT NOT NULL,
                    offense_type TEXT NOT NULL,
                    offense_category TEXT,
                    severity TEXT DEFAULT 'minor',
                    description TEXT NOT NULL,
                    date_occurred TEXT NOT NULL,
                    date_reported TEXT,
                    reported_by TEXT,
                    witnesses TEXT,
                    evidence_path TEXT,
                    status TEXT DEFAULT 'under_review',
                    investigation_notes TEXT,
                    is_confidential BOOLEAN DEFAULT 1,
                    previous_warnings INTEGER DEFAULT 0,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE discovery_event_attendance (
                        attendance_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        event_id INTEGER NOT NULL,
                        user_id TEXT NOT NULL,
                        check_in_time TEXT NOT NULL,
                        check_out_time TEXT,
                        FOREIGN KEY (event_id) REFERENCES discovery_events(event_id),
                        UNIQUE(event_id, user_id)
                    );
CREATE TABLE discovery_event_interests (
                        interest_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        user_id TEXT NOT NULL,
                        category TEXT NOT NULL,
                        interest_level INTEGER DEFAULT 5,
                        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                        UNIQUE(user_id, category)
                    );
