CREATE TABLE discovery_event_photos (
                        photo_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        event_id INTEGER NOT NULL,
                        user_id TEXT NOT NULL,
                        photo_url TEXT NOT NULL,
                        caption TEXT,
                        uploaded_at TEXT DEFAULT CURRENT_TIMESTAMP,
                        FOREIGN KEY (event_id) REFERENCES discovery_events(event_id)
                    );
CREATE TABLE discovery_event_ratings (
                        rating_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        event_id INTEGER NOT NULL,
                        user_id TEXT NOT NULL,
                        rating INTEGER NOT NULL CHECK(rating >= 1 AND rating <= 5),
                        review TEXT,
                        rated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                        FOREIGN KEY (event_id) REFERENCES discovery_events(event_id),
                        UNIQUE(event_id, user_id)
                    );
CREATE TABLE discovery_event_rsvps (
                        rsvp_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        event_id INTEGER NOT NULL,
                        user_id TEXT NOT NULL,
                        rsvp_status TEXT NOT NULL,
                        rsvp_date TEXT DEFAULT CURRENT_TIMESTAMP,
                        added_to_calendar INTEGER DEFAULT 0,
                        reminder_sent INTEGER DEFAULT 0,
                        FOREIGN KEY (event_id) REFERENCES discovery_events(event_id),
                        UNIQUE(event_id, user_id)
                    );
CREATE TABLE discovery_event_social_settings (
                        user_id TEXT PRIMARY KEY,
                        show_attendance_to_friends INTEGER DEFAULT 1,
                        receive_friend_notifications INTEGER DEFAULT 1,
                        created_at TEXT DEFAULT CURRENT_TIMESTAMP
                    );
CREATE TABLE discovery_events (
                        event_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        title TEXT NOT NULL,
                        description TEXT,
                        category TEXT NOT NULL,
                        start_datetime TEXT NOT NULL,
                        end_datetime TEXT NOT NULL,
                        location TEXT NOT NULL,
                        building TEXT,
                        room TEXT,
                        organizer_id TEXT,
                        organizer_name TEXT,
                        organizer_type TEXT,
                        max_capacity INTEGER,
                        registration_required INTEGER DEFAULT 0,
                        registration_deadline TEXT,
                        event_image_url TEXT,
                        tags TEXT,
                        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                        updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                        cancelled INTEGER DEFAULT 0
                    );
CREATE TABLE disease_surveillance (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    disease_name TEXT,
                    case_date TEXT,
                    student_id TEXT,
                    symptoms TEXT,
                    severity TEXT,
                    status TEXT DEFAULT 'under_investigation',
                    contact_tracing_needed INTEGER DEFAULT 0,
                    contact_tracing_completed INTEGER DEFAULT 0,
                    contacts_identified INTEGER DEFAULT 0,
                    reported_to_health_dept INTEGER DEFAULT 0,
                    isolation_required INTEGER DEFAULT 0,
                    created_at TEXT,
                    FOREIGN KEY (student_id) REFERENCES students (student_id)
                );
CREATE TABLE document_approval_history (
                history_id INTEGER PRIMARY KEY AUTOINCREMENT,
                approval_id INTEGER NOT NULL,
                approver_id TEXT NOT NULL,
                approver_name TEXT,
                action TEXT,
                step_number INTEGER,
                comments TEXT,
                action_date TEXT DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (approval_id) REFERENCES document_approvals(approval_id)
            );
CREATE TABLE document_approvals (
                approval_id INTEGER PRIMARY KEY AUTOINCREMENT,
                document_type TEXT NOT NULL,
                document_title TEXT,
                document_description TEXT,
                document_path TEXT,
                submitted_by TEXT NOT NULL,
                submitted_by_name TEXT,
                submitted_date TEXT DEFAULT CURRENT_TIMESTAMP,
                current_approver TEXT,
                approval_chain TEXT,
                current_step INTEGER DEFAULT 1,
                total_steps INTEGER DEFAULT 1,
                status TEXT DEFAULT 'pending',
                comments TEXT,
                completed_date TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE document_repository (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    title TEXT NOT NULL CHECK(length(title) > 0),
                    content TEXT NOT NULL CHECK(length(content) > 0),
                    content_hash TEXT NOT NULL,
                    author_id INTEGER NOT NULL,
                    module_code TEXT,
                    submission_date TEXT NOT NULL,
                    file_type TEXT,
                    word_count INTEGER DEFAULT 0,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (author_id) REFERENCES users (id) ON DELETE CASCADE,
                    FOREIGN KEY (module_code) REFERENCES modules (module_code) ON DELETE SET NULL
                );
CREATE TABLE document_requests (id INTEGER PRIMARY KEY AUTOINCREMENT, student_id TEXT, document_type TEXT, status TEXT DEFAULT 'pending', requested_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
