            intervention_type TEXT NOT NULL,
            priority TEXT NOT NULL,
            status TEXT DEFAULT 'pending',
            assigned_to TEXT,
            description TEXT,
            scheduled_date TEXT,
            completed_date TEXT,
            outcome TEXT,
            notes TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (student_id) REFERENCES students (student_id)
        );
INSERT INTO "early_warning_interventions" VALUES(1,'S12345','academic','coaching','high','pending','1','test','',NULL,NULL,NULL,'2026-01-27 21:59:26','2026-01-27 21:59:26');
CREATE TABLE early_warning_notifications (
            notification_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            recipient_type TEXT NOT NULL,
            recipient_email TEXT NOT NULL,
            notification_type TEXT NOT NULL,
            subject TEXT NOT NULL,
            message TEXT NOT NULL,
            sent_at TEXT DEFAULT CURRENT_TIMESTAMP,
            is_read BOOLEAN DEFAULT 0,
            read_at TEXT,
            FOREIGN KEY (student_id) REFERENCES students (student_id)
        );
CREATE TABLE early_warning_profiles (
            profile_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL UNIQUE,
            overall_risk_score INTEGER DEFAULT 0,
            risk_level TEXT DEFAULT 'low',
            academic_risk_score INTEGER DEFAULT 0,
            attendance_risk_score INTEGER DEFAULT 0,
            engagement_risk_score INTEGER DEFAULT 0,
            financial_risk_score INTEGER DEFAULT 0,
            last_assessed TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (student_id) REFERENCES students (student_id)
        );
