CREATE TABLE early_warning_progress_monitoring (
            monitoring_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            coach_id INTEGER NOT NULL,
            monitoring_date TEXT DEFAULT CURRENT_DATE,
            academic_progress TEXT,
            attendance_progress TEXT,
            engagement_progress TEXT,
            goals_achieved TEXT,
            concerns TEXT,
            next_steps TEXT,
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (coach_id) REFERENCES early_warning_coaches (coach_id)
        );
CREATE TABLE early_warning_tutoring_recommendations (
            recommendation_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            module_code TEXT NOT NULL,
            recommended_by TEXT NOT NULL,
            recommendation_type TEXT NOT NULL,
            priority TEXT DEFAULT 'medium',
            status TEXT DEFAULT 'pending',
            tutor_assigned TEXT,
            sessions_scheduled INTEGER DEFAULT 0,
            sessions_completed INTEGER DEFAULT 0,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (module_code) REFERENCES modules (module_code)
        );
INSERT INTO "early_warning_tutoring_recommendations" VALUES(2,'S12345','CIS0001','admin','one-on-one','medium','pending',NULL,0,0,'2026-01-27 21:59:55');
CREATE TABLE election_candidates (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            election_id INTEGER,
            student_id TEXT,
            manifesto TEXT,
            votes INTEGER DEFAULT 0,
            FOREIGN KEY (election_id) REFERENCES union_elections (election_id),
            FOREIGN KEY (student_id) REFERENCES students (student_id)
        );
CREATE TABLE election_votes (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            election_id INTEGER,
            voter_id TEXT,
            candidate_id INTEGER,
            vote_time TEXT,
            FOREIGN KEY (election_id) REFERENCES union_elections (election_id),
            FOREIGN KEY (voter_id) REFERENCES students (student_id),
            FOREIGN KEY (candidate_id) REFERENCES election_candidates (id)
        );
CREATE TABLE email_drafts (
                    draft_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    recipients TEXT,
                    cc TEXT,
                    subject TEXT,
                    body TEXT,
                    created_at TEXT,
                    updated_at TEXT
                );
