CREATE TABLE emails (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    recipient TEXT NOT NULL,
                    subject TEXT,
                    body TEXT,
                    cc TEXT,
                    bcc TEXT,
                    sent_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    status TEXT DEFAULT 'sent',
                    attachments TEXT
                );
CREATE TABLE emergency_alerts (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                alert_title TEXT,
                alert_message TEXT,
                alert_type TEXT,
                created_date TEXT,
                created_by INTEGER,
                active BOOLEAN DEFAULT 1,
                FOREIGN KEY (created_by) REFERENCES users (id)
            );
CREATE TABLE emergency_contacts (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT,
                    contact_name TEXT,
                    relationship TEXT,
                    phone_primary TEXT,
                    phone_secondary TEXT,
                    email TEXT,
                    address TEXT,
                    priority_order INTEGER,
                    medical_decision_maker INTEGER DEFAULT 0,
                    created_at TEXT,
                    FOREIGN KEY (student_id) REFERENCES students (student_id)
                );
CREATE TABLE emergency_pickup_requests (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL,
                    pickup_person TEXT NOT NULL,
                    reason TEXT,
                    time_needed TEXT,
                    contact_phone TEXT,
                    request_timestamp TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    status TEXT DEFAULT 'Pending'
                );
CREATE TABLE employers (
            employer_id INTEGER PRIMARY KEY AUTOINCREMENT,
            company_name TEXT NOT NULL,
            industry TEXT,
            company_size TEXT,
            website TEXT,
            contact_person TEXT,
            contact_email TEXT,
            contact_phone TEXT,
            description TEXT,
            logo_url TEXT,
            is_verified BOOLEAN DEFAULT 0,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE encrypted_fields_metadata (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                table_name TEXT NOT NULL,
                column_name TEXT NOT NULL,
                key_id TEXT,
                encrypted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                UNIQUE(table_name, column_name)
            );
CREATE TABLE encryption_keys (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                key_id TEXT UNIQUE NOT NULL,
                public_key TEXT,
                private_key_encrypted TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                rotated_at TEXT,
                is_active INTEGER DEFAULT 1
            , algorithm TEXT, status TEXT);
CREATE TABLE energy_usage (
            usage_id INTEGER PRIMARY KEY AUTOINCREMENT,
            building_id INTEGER NOT NULL,
            usage_type TEXT NOT NULL,
            reading_date TEXT NOT NULL,
            meter_reading REAL NOT NULL,
            consumption REAL,
            cost REAL,
            billing_period_start TEXT,
            billing_period_end TEXT,
            FOREIGN KEY (building_id) REFERENCES buildings (building_id)
        );
CREATE TABLE engagement_points (
            point_id INTEGER PRIMARY KEY AUTOINCREMENT,
            alumni_id TEXT,
            activity_type TEXT,
            points_earned INTEGER,
            activity_date TEXT,
            description TEXT,
            FOREIGN KEY (alumni_id) REFERENCES alumni (alumni_id)
        );
CREATE TABLE enrollment_projections (
            projection_id INTEGER PRIMARY KEY AUTOINCREMENT,
            academic_year TEXT NOT NULL,
            program_id INTEGER,
            projected_new_students INTEGER,
            projected_continuing_students INTEGER,
            projected_total_enrollment INTEGER,
            projection_date TEXT DEFAULT CURRENT_TIMESTAMP,
            model_id INTEGER,
            scenario TEXT,
            FOREIGN KEY (model_id) REFERENCES analytics_models (model_id)
        );
CREATE TABLE equipment (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            equipment_type TEXT NOT NULL,
            screen_number INTEGER,
            brand TEXT,
            model TEXT,
            serial_number TEXT,
            install_date TEXT,
            warranty_until TEXT,
            last_service_date TEXT,
            next_service_due TEXT,
            hours_used INTEGER DEFAULT 0,
            max_hours_before_service INTEGER DEFAULT 2000,
            status TEXT DEFAULT 'operational',
            notes TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE equipment_bookings (
                    booking_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    equipment_id INTEGER NOT NULL,
                    user_id TEXT NOT NULL,
                    booking_date TEXT NOT NULL,
                    start_time TEXT NOT NULL,
                    end_time TEXT NOT NULL,
                    purpose TEXT,
                    status TEXT DEFAULT 'pending',
                    approved_by TEXT,
                    approved_date TEXT,
                    checked_in_at TEXT,
                    checked_out_at TEXT,
                    notes TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (equipment_id) REFERENCES lab_equipment(equipment_id)
                );
CREATE TABLE equipment_categories (
                    category_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL UNIQUE,
                    description TEXT,
                    parent_category_id INTEGER,
                    is_active INTEGER DEFAULT 1,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (parent_category_id) REFERENCES equipment_categories(category_id)
                );
INSERT INTO "equipment_categories" VALUES(1,'Lab Instruments','Scientific laboratory instruments and tools',NULL,1,'2026-02-24 08:00:44');
INSERT INTO "equipment_categories" VALUES(2,'Computing','Computers, servers, and computing hardware',NULL,1,'2026-02-24 08:00:44');
INSERT INTO "equipment_categories" VALUES(3,'Audio Visual','Projectors, cameras, and AV equipment',NULL,1,'2026-02-24 08:00:44');
INSERT INTO "equipment_categories" VALUES(4,'Workshop','Workshop tools and machinery',NULL,1,'2026-02-24 08:00:44');
INSERT INTO "equipment_categories" VALUES(5,'Measurement','Measurement and testing equipment',NULL,1,'2026-02-24 08:00:44');
INSERT INTO "equipment_categories" VALUES(6,'Safety','Safety equipment and protective gear',NULL,1,'2026-02-24 08:00:44');
CREATE TABLE equipment_checkouts (
            checkout_id INTEGER PRIMARY KEY AUTOINCREMENT,
            equipment_id INTEGER,
            borrower_id TEXT,
            club_id INTEGER,
            checkout_date TEXT,
            expected_return TEXT,
            actual_return TEXT,
            condition_out TEXT,
            condition_in TEXT,
            notes TEXT,
            status TEXT DEFAULT 'checked_out',
            FOREIGN KEY (equipment_id) REFERENCES union_equipment (equipment_id),
            FOREIGN KEY (borrower_id) REFERENCES students (student_id),
            FOREIGN KEY (club_id) REFERENCES student_clubs (club_id)
        );
CREATE TABLE equipment_items (
                    item_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    item_code TEXT UNIQUE NOT NULL,
                    name TEXT NOT NULL,
                    description TEXT,
                    category TEXT NOT NULL,
                    brand TEXT,
                    model TEXT,
                    serial_number TEXT,
                    daily_rate DECIMAL(10,2) NOT NULL,
                    hourly_rate DECIMAL(10,2),
                    deposit_required DECIMAL(10,2) DEFAULT 0,
                    quantity_total INTEGER DEFAULT 1,
                    quantity_available INTEGER DEFAULT 1,
                    condition TEXT DEFAULT 'good',
                    location TEXT,
                    image_path TEXT,
                    notes TEXT,
                    requires_training INTEGER DEFAULT 0,
                    is_active INTEGER DEFAULT 1,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                );
INSERT INTO "equipment_items" VALUES(1,'1','test','test','cameras','test','test',NULL,1,NULL,50,100,100,'good','test',NULL,NULL,0,1,'2025-12-31 21:24:40','2026-01-24 15:49:16');
INSERT INTO "equipment_items" VALUES(2,'2','test2','test','cameras','camera','test',NULL,5,NULL,50,100,100,'good','test',NULL,NULL,0,1,'2026-01-24 15:48:33','2026-01-24 15:48:46');
CREATE TABLE equipment_maintenance (
                    maintenance_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    item_id INTEGER NOT NULL,
                    maintenance_type TEXT NOT NULL,
                    description TEXT,
                    cost DECIMAL(10,2) DEFAULT 0,
                    performed_date TEXT NOT NULL,
                    next_maintenance_date TEXT,
                    performed_by TEXT,
                    notes TEXT,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (item_id) REFERENCES equipment_items(item_id)
                );
CREATE TABLE equipment_maintenance_log (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            equipment_id INTEGER NOT NULL,
            maintenance_type TEXT NOT NULL,
            description TEXT,
            performed_by TEXT,
            cost REAL DEFAULT 0,
            parts_replaced TEXT,
            hours_at_service INTEGER,
            next_service_hours INTEGER,
            service_date TEXT NOT NULL,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (equipment_id) REFERENCES equipment(id)
        );
CREATE TABLE equipment_rentals (
                    rental_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    rental_number TEXT UNIQUE NOT NULL,
                    item_id INTEGER NOT NULL,
                    quantity INTEGER DEFAULT 1,
                    borrower_id TEXT NOT NULL,
                    borrower_name TEXT NOT NULL,
                    borrower_email TEXT,
                    borrower_phone TEXT,
                    borrower_department TEXT,
                    purpose TEXT,
                    checkout_date TEXT NOT NULL,
                    checkout_time TEXT NOT NULL,
                    due_date TEXT NOT NULL,
                    due_time TEXT NOT NULL,
                    actual_return_date TEXT,
                    actual_return_time TEXT,
                    daily_rate DECIMAL(10,2) NOT NULL,
                    total_days INTEGER NOT NULL,
                    subtotal DECIMAL(10,2) NOT NULL,
                    deposit_amount DECIMAL(10,2) DEFAULT 0,
                    late_fee DECIMAL(10,2) DEFAULT 0,
