CREATE TABLE exercise_tracking (
                    exercise_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL,
                    exercise_date TEXT NOT NULL,
                    exercise_type TEXT NOT NULL,
                    duration_minutes INTEGER,
                    intensity TEXT,
                    calories_burned INTEGER,
                    notes TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (student_id) REFERENCES students(student_id)
                );
CREATE TABLE exit_checklist (
                    checklist_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT NOT NULL,
                    template_id INTEGER,
                    task_name TEXT NOT NULL,
                    description TEXT,
                    category TEXT,
                    responsible_party TEXT,
                    due_date TEXT,
                    completed BOOLEAN DEFAULT 0,
                    completed_date TEXT,
                    completed_by TEXT,
                    notes TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (template_id) REFERENCES exit_checklist_templates(template_id)
                );
CREATE TABLE exit_checklist_template_items (
                    item_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    template_id INTEGER NOT NULL,
                    task_name TEXT NOT NULL,
                    description TEXT,
                    responsible_party TEXT,
                    category TEXT,
                    days_before_exit INTEGER DEFAULT 0,
                    is_mandatory BOOLEAN DEFAULT 1,
                    order_index INTEGER DEFAULT 0,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (template_id) REFERENCES exit_checklist_templates(template_id)
                );
