CREATE TABLE exit_checklist_templates (
                    template_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL,
                    description TEXT,
                    department TEXT,
                    role_type TEXT,
                    is_default BOOLEAN DEFAULT 0,
                    is_active BOOLEAN DEFAULT 1,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
INSERT INTO "exit_checklist_templates" VALUES(1,'Standard Exit Checklist','Default checklist for all departing employees',NULL,NULL,1,1,'2026-02-24 18:39:12');
CREATE TABLE exit_interviews (
                    interview_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT NOT NULL,
                    interviewer_id TEXT,
                    scheduled_date TEXT,
                    interview_date TEXT,
                    interview_method TEXT DEFAULT 'in_person',
                    status TEXT DEFAULT 'scheduled',
                    last_working_day TEXT,
                    tenure_months INTEGER,
                    department TEXT,
                    job_title TEXT,
                    manager_id TEXT,
                    reason_for_leaving TEXT,
                    reason_category TEXT,
                    destination TEXT,
                    new_employer TEXT,
                    new_role TEXT,
                    salary_factor BOOLEAN DEFAULT 0,
                    career_growth_factor BOOLEAN DEFAULT 0,
                    work_life_balance_factor BOOLEAN DEFAULT 0,
                    management_factor BOOLEAN DEFAULT 0,
                    culture_factor BOOLEAN DEFAULT 0,
                    job_satisfaction_rating INTEGER,
                    manager_rating INTEGER,
                    work_environment_rating INTEGER,
                    growth_opportunities_rating INTEGER,
                    compensation_rating INTEGER,
                    overall_rating INTEGER,
                    liked_most TEXT,
                    liked_least TEXT,
                    suggestions TEXT,
                    would_recommend BOOLEAN,
                    would_return BOOLEAN,
                    additional_comments TEXT,
                    confidential_notes TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE exit_reasons_summary (
                    summary_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    period TEXT NOT NULL,
                    department TEXT,
                    reason_category TEXT NOT NULL,
                    count INTEGER DEFAULT 0,
                    percentage REAL,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE expense_approvals (
                    approval_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    claim_id INTEGER NOT NULL,
                    approver_id TEXT NOT NULL,
                    approval_level INTEGER DEFAULT 1,
                    decision TEXT,
                    comments TEXT,
                    decision_date TEXT,
                    amount_approved REAL,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (claim_id) REFERENCES expense_claims(claim_id)
                );
CREATE TABLE expense_categories (
                    category_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL UNIQUE,
                    description TEXT,
                    max_amount REAL,
                    requires_receipt BOOLEAN DEFAULT 1,
                    requires_approval BOOLEAN DEFAULT 1,
                    approval_threshold REAL,
                    is_active BOOLEAN DEFAULT 1,
                    gl_code TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
