CREATE TABLE expense_claims (
                    claim_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT NOT NULL,
                    category_id INTEGER NOT NULL,
                    amount REAL NOT NULL,
                    currency TEXT DEFAULT 'GBP',
                    description TEXT NOT NULL,
                    expense_date TEXT NOT NULL,
                    receipt_path TEXT,
                    receipt_number TEXT,
                    project_code TEXT,
                    cost_center TEXT,
                    status TEXT DEFAULT 'draft',
                    submitted_date TEXT,
                    notes TEXT,
                    mileage_miles REAL,
                    mileage_rate REAL,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (category_id) REFERENCES expense_categories(category_id)
                );
CREATE TABLE expense_policies (
                    policy_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL,
                    description TEXT,
                    max_daily_amount REAL,
                    max_single_claim REAL,
                    requires_pre_approval_above REAL,
                    mileage_rate REAL DEFAULT 0.45,
                    subsistence_rate REAL,
                    applies_to_roles TEXT,
                    effective_from TEXT,
                    effective_to TEXT,
                    is_active BOOLEAN DEFAULT 1,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
INSERT INTO "expense_policies" VALUES(1,'Standard Expense Policy','Default expense policy for all staff',150.0,1000.0,500.0,0.45,NULL,NULL,NULL,NULL,1,'2026-02-24 18:39:12');
CREATE TABLE extension_requests (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            assignment_id INTEGER NOT NULL,
            student_id TEXT NOT NULL,
            requested_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            new_due_date TIMESTAMP NOT NULL,
            reason TEXT NOT NULL,
            status TEXT DEFAULT 'pending',
            reviewed_by INTEGER,
            reviewed_date TIMESTAMP,
            review_comments TEXT,
            FOREIGN KEY (assignment_id) REFERENCES assignments (id),
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (reviewed_by) REFERENCES users (id)
        );
CREATE TABLE external_examiners (
                examiner_id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                institution TEXT,
                email TEXT,
                phone TEXT,
                expertise_area TEXT,
                department TEXT,
                appointment_start TEXT,
                appointment_end TEXT,
                status TEXT DEFAULT 'active',
                contact_person_id TEXT,
                notes TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP
            );
INSERT INTO "external_examiners" VALUES(1,'test','test',NULL,NULL,'test',NULL,NULL,NULL,'active',NULL,NULL,'2026-03-16 18:33:05');
CREATE TABLE external_scholarships (
    external_id INTEGER PRIMARY KEY AUTOINCREMENT,
    student_id INTEGER NOT NULL,
    provider_name TEXT NOT NULL,
    scholarship_name TEXT,
    amount REAL NOT NULL,
    academic_year TEXT NOT NULL,
    disbursement_date DATE,
    is_recurring BOOLEAN DEFAULT 0,
    contact_email TEXT,
    contact_phone TEXT,
    documentation_url TEXT,
    reported_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (student_id) REFERENCES students(student_id)
);
CREATE TABLE extracurricular_activities (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                activity_name TEXT,
                description TEXT,
                supervisor TEXT,
                meeting_schedule TEXT,
                location TEXT,
                max_participants INTEGER,
                fee DECIMAL(10,2) DEFAULT 0.00,
                status TEXT DEFAULT 'active'
            );
CREATE TABLE facility_assets (
                asset_id INTEGER PRIMARY KEY AUTOINCREMENT,
                asset_name TEXT NOT NULL,
                asset_type TEXT NOT NULL,
                asset_tag TEXT UNIQUE,
                building_id INTEGER,
                room_id INTEGER,
                purchase_date TEXT,
                purchase_cost REAL,
                warranty_expiry TEXT,
                maintenance_schedule TEXT,
                last_maintenance_date TEXT,
                condition TEXT DEFAULT 'good',
                status TEXT DEFAULT 'active',
                FOREIGN KEY (building_id) REFERENCES buildings (building_id),
                FOREIGN KEY (room_id) REFERENCES rooms (id)
            );
INSERT INTO "facility_assets" VALUES(1,'test','equipment','1',NULL,NULL,NULL,0.0,NULL,NULL,NULL,'good','active');
CREATE TABLE facility_bookings (
                    booking_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    facility_name TEXT,
                    user_id INTEGER,
                    booking_date TEXT,
                    start_time TEXT,
                    end_time TEXT,
                    purpose TEXT,
                    status TEXT DEFAULT 'pending',
                    created_at TEXT,
                    FOREIGN KEY (user_id) REFERENCES users (id)
                );
CREATE TABLE faculty_notifications (
                    notification_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    accommodation_id INTEGER NOT NULL,
                    student_id TEXT NOT NULL,
                    faculty_id TEXT NOT NULL,
                    course_id TEXT NOT NULL,
                    accommodation_summary TEXT NOT NULL,
                    sent_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    acknowledged INTEGER DEFAULT 0,
                    FOREIGN KEY (accommodation_id) REFERENCES accommodations(accommodation_id)
                );
CREATE TABLE faculty_schedule_blocks (
                    block_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT NOT NULL,
                    day_of_week INTEGER NOT NULL,
                    start_time TEXT NOT NULL,
                    end_time TEXT NOT NULL,
                    activity_type TEXT NOT NULL DEFAULT 'teaching',
                    title TEXT,
                    description TEXT,
                    location TEXT,
                    course_code TEXT,
                    color TEXT,
                    is_locked INTEGER DEFAULT 0,
                    semester TEXT,
                    academic_year TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE faculty_schedule_templates (
                    template_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL,
                    description TEXT,
                    created_by TEXT NOT NULL,
                    blocks_json TEXT NOT NULL,
                    is_shared INTEGER DEFAULT 0,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE fafsa_data (
    fafsa_id INTEGER PRIMARY KEY AUTOINCREMENT,
    student_id INTEGER NOT NULL,
    academic_year TEXT NOT NULL,
    efc INTEGER,  -- Expected Family Contribution
    submission_date DATE,
    processed_date DATE,
    sai INTEGER,  -- Student Aid Index (new FAFSA metric)
    dependency_status TEXT,  -- dependent, independent
    pell_eligible BOOLEAN DEFAULT 0,
    pell_amount REAL,
    verification_status TEXT DEFAULT 'not_required',
    imported_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (student_id) REFERENCES students(student_id),
    UNIQUE(student_id, academic_year)
);
CREATE TABLE faqs (
            faq_id INTEGER PRIMARY KEY AUTOINCREMENT,
            question TEXT NOT NULL,
            answer TEXT NOT NULL,
            category TEXT NOT NULL,
            created_by TEXT NOT NULL,
            created_datetime TEXT NOT NULL,
            updated_datetime TEXT,
            view_count INTEGER DEFAULT 0,
            helpful_votes INTEGER DEFAULT 0,
            tags TEXT,  -- JSON array
            is_featured BOOLEAN DEFAULT 0
        );
CREATE TABLE favorites (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            member_id INTEGER,
            customer_email TEXT,
            movie_id INTEGER NOT NULL,
            added_at TEXT DEFAULT CURRENT_TIMESTAMP,
            notify_screenings INTEGER DEFAULT 1,
            FOREIGN KEY (member_id) REFERENCES members(id),
            FOREIGN KEY (movie_id) REFERENCES movies(id),
            UNIQUE(customer_email, movie_id)
        );
CREATE TABLE fee_types (
            fee_type_id INTEGER PRIMARY KEY AUTOINCREMENT,
            fee_name TEXT NOT NULL,
            description TEXT,
            is_recurring BOOLEAN DEFAULT 0,
            academic_year TEXT,
            is_late_fee BOOLEAN DEFAULT 0,
            late_fee_calculation TEXT, -- 'fixed', 'percentage', 'daily'
            late_fee_amount DECIMAL(10,2),
            grace_period_days INTEGER DEFAULT 0,
            created_at TEXT,
            updated_at TEXT
        );
