CREATE TABLE feedback_attachments (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    submission_id INTEGER NOT NULL,
                    file_name TEXT NOT NULL,
                    file_path TEXT NOT NULL,
                    file_type TEXT,
                    file_size INTEGER,
                    uploaded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (submission_id) REFERENCES feedback_submissions(id) ON DELETE CASCADE
                );
CREATE TABLE feedback_categories (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL UNIQUE,
                    description TEXT,
                    icon TEXT,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                );
INSERT INTO "feedback_categories" VALUES(1,'Academic','Course content, teaching quality, curriculum','📚','2026-01-11 15:54:35');
INSERT INTO "feedback_categories" VALUES(2,'Housing','Dormitories, apartments, maintenance','🏠','2026-01-11 15:54:35');
INSERT INTO "feedback_categories" VALUES(3,'Dining','Cafeteria, meal plans, food quality','🍽️','2026-01-11 15:54:35');
