INSERT INTO "feedback_categories" VALUES(5,'Campus Life','Events, clubs, activities, facilities','🎉','2026-01-11 15:54:35');
INSERT INTO "feedback_categories" VALUES(6,'Safety','Security, emergency services, lighting','🔒','2026-01-11 15:54:35');
