CREATE TABLE feedback_files (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                submission_id INTEGER NOT NULL,
                file_path TEXT NOT NULL,
                file_name TEXT NOT NULL,
                file_type TEXT,
                created_by INTEGER,
                created_at TEXT NOT NULL,
                FOREIGN KEY (submission_id) REFERENCES assignment_submissions (id),
                FOREIGN KEY (created_by) REFERENCES users (id)
            );
CREATE TABLE feedback_impacts (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    submission_id INTEGER NOT NULL,
                    implementation_date DATE,
                    users_affected INTEGER,
                    satisfaction_increase REAL,
                    cost_savings REAL,
                    description TEXT,
                    metrics TEXT,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (submission_id) REFERENCES feedback_submissions(id) ON DELETE CASCADE
                );
CREATE TABLE feedback_responses (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    submission_id INTEGER NOT NULL,
                    responder_id TEXT NOT NULL,
                    responder_name TEXT NOT NULL,
                    response_text TEXT NOT NULL,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (submission_id) REFERENCES feedback_submissions(id) ON DELETE CASCADE
                );
CREATE TABLE feedback_status_updates (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    submission_id INTEGER NOT NULL,
                    old_status TEXT,
                    new_status TEXT NOT NULL,
                    updated_by TEXT NOT NULL,
                    notes TEXT,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (submission_id) REFERENCES feedback_submissions(id) ON DELETE CASCADE
                );
CREATE TABLE feedback_submissions (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT,
                    category_id INTEGER NOT NULL,
                    type TEXT NOT NULL CHECK(type IN ('feedback', 'suggestion')),
                    title TEXT NOT NULL,
                    description TEXT NOT NULL,
                    is_anonymous BOOLEAN DEFAULT 0,
                    status TEXT DEFAULT 'Submitted',
                    priority TEXT DEFAULT 'Normal' CHECK(priority IN ('Low', 'Normal', 'High', 'Critical')),
                    votes INTEGER DEFAULT 0,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (category_id) REFERENCES feedback_categories(id)
                );
CREATE TABLE feedback_votes (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    submission_id INTEGER NOT NULL,
                    user_id TEXT NOT NULL,
                    vote_type TEXT DEFAULT 'upvote' CHECK(vote_type IN ('upvote', 'downvote')),
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    UNIQUE(submission_id, user_id),
                    FOREIGN KEY (submission_id) REFERENCES feedback_submissions(id) ON DELETE CASCADE
                );
CREATE TABLE file_versions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                submission_id INTEGER NOT NULL,
                version_number INTEGER NOT NULL,
                file_path TEXT NOT NULL,
                file_hash TEXT NOT NULL,
                created_at TEXT NOT NULL,
                is_current INTEGER DEFAULT 0,
                FOREIGN KEY (submission_id) REFERENCES assignment_submissions (id)
            );
CREATE TABLE finance_payments (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    payment_reference TEXT UNIQUE,
                    department TEXT,
                    transaction_id TEXT,
                    amount DECIMAL(10,2),
                    payment_method TEXT,
                    payment_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    processed_by TEXT,
                    notes TEXT
                );
CREATE TABLE finance_refunds (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        refund_reference TEXT UNIQUE,
                        department TEXT,
                        transaction_id TEXT,
                        amount DECIMAL(10,2),
                        refund_method TEXT,
                        refund_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        processed_by TEXT,
                        notes TEXT
                    , refund_time TEXT, student_id TEXT, transaction_reference TEXT);
