        message TEXT NOT NULL,
        student_id TEXT,
        amount DECIMAL(10,2),
        currency TEXT DEFAULT 'GBP',
        status TEXT DEFAULT 'active',
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        acknowledged_at TEXT,
        resolved_at TEXT,
        acknowledged_by TEXT,
        resolved_by TEXT,
        metadata TEXT,
        FOREIGN KEY (student_id) REFERENCES students (student_id)
    );
CREATE TABLE financial_kpis (
            kpi_id INTEGER PRIMARY KEY AUTOINCREMENT,
            kpi_name TEXT NOT NULL,
            kpi_value DECIMAL(15,2) NOT NULL,
            kpi_type TEXT NOT NULL, -- 'amount', 'percentage', 'count', 'ratio'
            calculation_period TEXT NOT NULL, -- 'daily', 'weekly', 'monthly', 'yearly'
            calculation_date TEXT NOT NULL,
            academic_year TEXT,
            created_at TEXT
        );
CREATE TABLE financial_records (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    category TEXT NOT NULL,
                    record_type TEXT NOT NULL,
                    amount REAL NOT NULL,
                    period TEXT NOT NULL,
                    academic_year TEXT,
                    department TEXT,
                    notes TEXT,
                    recorded_by TEXT,
                    recorded_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE fine_payments (
    payment_id INTEGER PRIMARY KEY AUTOINCREMENT,
    loan_id INTEGER NOT NULL,
    amount DECIMAL(10,2) NOT NULL,
    payment_method TEXT,
    payment_date TEXT,
    processed_by TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE flashcards (
                    flashcard_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL,
                    course_id TEXT,
                    deck_name TEXT NOT NULL,
                    question TEXT NOT NULL,
                    answer TEXT NOT NULL,
                    difficulty_rating INTEGER DEFAULT 0,
                    last_reviewed TEXT,
                    next_review TEXT,
                    review_count INTEGER DEFAULT 0,
                    correct_count INTEGER DEFAULT 0,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
