INSERT INTO "flashcards" VALUES(2,'5',NULL,'test','test','test',0,NULL,'2026-01-20',0,0,'2026-01-19 08:49:05');
CREATE TABLE forecast_models (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL,
                    description TEXT,
                    model_type TEXT DEFAULT 'linear',
                    parameters TEXT,
                    created_by TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    is_active INTEGER DEFAULT 1
                );
CREATE TABLE forecast_results (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    model_id INTEGER,
                    category TEXT,
                    forecast_period TEXT,
                    predicted_amount REAL,
                    confidence_low REAL,
                    confidence_high REAL,
                    generated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (model_id) REFERENCES forecast_models(id)
                );
CREATE TABLE forensic_analysis_results (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                evidence_id TEXT NOT NULL,
                analysis_type TEXT NOT NULL,
                results_json TEXT,
                performed_by INTEGER,
                performed_at TEXT NOT NULL,
                FOREIGN KEY (evidence_id) REFERENCES forensic_evidence(evidence_id),
                FOREIGN KEY (performed_by) REFERENCES users(id)
            );
CREATE TABLE forensic_cases (
                case_id TEXT PRIMARY KEY,
                title TEXT NOT NULL,
                description TEXT,
                priority TEXT NOT NULL DEFAULT 'MEDIUM',
                status TEXT NOT NULL DEFAULT 'OPEN',
                investigator_id INTEGER,
                notes TEXT,
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL,
                FOREIGN KEY (investigator_id) REFERENCES users(id)
            );
CREATE TABLE forensic_custody_log (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                evidence_id TEXT NOT NULL,
                event_type TEXT NOT NULL,
                user_id INTEGER,
                notes TEXT,
                timestamp TEXT NOT NULL,
                FOREIGN KEY (evidence_id) REFERENCES forensic_evidence(evidence_id),
                FOREIGN KEY (user_id) REFERENCES users(id)
            );
CREATE TABLE forensic_evidence (
                evidence_id TEXT PRIMARY KEY,
                case_id TEXT NOT NULL,
                evidence_type TEXT NOT NULL,
                description TEXT,
                file_path TEXT,
                hash_md5 TEXT,
                hash_sha1 TEXT,
                hash_sha256 TEXT,
                hash_sha512 TEXT,
                state TEXT NOT NULL DEFAULT 'ACQUIRED',
                collected_by INTEGER,
                collected_at TEXT,
                created_at TEXT NOT NULL,
                updated_at TEXT,
                FOREIGN KEY (case_id) REFERENCES forensic_cases(case_id),
                FOREIGN KEY (collected_by) REFERENCES users(id)
            );
CREATE TABLE forum_replies (
            reply_id INTEGER PRIMARY KEY AUTOINCREMENT,
            post_id INTEGER,
            author_id TEXT,
            content TEXT,
            reply_date TEXT,
            parent_reply_id INTEGER,
            FOREIGN KEY (post_id) REFERENCES alumni_forum (post_id),
            FOREIGN KEY (author_id) REFERENCES alumni (alumni_id)
        );
CREATE TABLE found_items (
                    item_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    finder_id TEXT NOT NULL,
                    item_name TEXT NOT NULL,
                    category TEXT NOT NULL,
                    description TEXT NOT NULL,
                    found_date TEXT NOT NULL,
                    found_location TEXT NOT NULL,
                    found_time TEXT,
                    distinctive_features TEXT,
                    color TEXT,
                    brand TEXT,
                    current_location TEXT,
                    storage_info TEXT,
                    contact_email TEXT,
                    contact_phone TEXT,
                    status TEXT DEFAULT 'Available',
                    reported_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (finder_id) REFERENCES students(student_id)
                );
CREATE TABLE free_stuff (
                    item_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    giver_id TEXT NOT NULL,
                    item_name TEXT NOT NULL,
                    description TEXT NOT NULL,
                    category TEXT NOT NULL,
                    condition_status TEXT DEFAULT 'Used',
                    location TEXT NOT NULL,
                    pickup_instructions TEXT,
                    available_until TEXT,
                    contact_info TEXT,
                    status TEXT DEFAULT 'Available',
                    claimed_by TEXT,
                    claimed_at TEXT,
                    view_count INTEGER DEFAULT 0,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (giver_id) REFERENCES students(student_id)
                );
CREATE TABLE fundraising_campaigns (
            campaign_id INTEGER PRIMARY KEY AUTOINCREMENT,
            campaign_name TEXT,
            description TEXT,
            goal_amount REAL,
            current_amount REAL DEFAULT 0.0,
            start_date TEXT,
            end_date TEXT,
            created_by TEXT,
            created_date TEXT,
            status TEXT DEFAULT 'active',
            category TEXT,
            is_featured BOOLEAN DEFAULT 0
        );
