CREATE TABLE fundraising_donations (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                campaign_id INTEGER,
                parent_id TEXT,
                student_id TEXT,
                amount DECIMAL(10,2),
                donation_date TEXT,
                anonymous BOOLEAN DEFAULT 0,
                FOREIGN KEY (campaign_id) REFERENCES fundraising_campaigns (id),
                FOREIGN KEY (parent_id) REFERENCES parent_accounts (parent_id),
                FOREIGN KEY (student_id) REFERENCES students (student_id)
            );
CREATE TABLE gateway_transactions (
            transaction_id INTEGER PRIMARY KEY AUTOINCREMENT,
            payment_id INTEGER,
            gateway_id INTEGER NOT NULL,
            gateway_transaction_id TEXT NOT NULL,
            amount DECIMAL(10,2) NOT NULL,
            currency TEXT NOT NULL,
            status TEXT NOT NULL,
            gateway_fee DECIMAL(10,2),
            raw_response TEXT, -- JSON response from gateway
            webhook_verified BOOLEAN DEFAULT 0,
            created_at TEXT,
            updated_at TEXT,
            FOREIGN KEY (payment_id) REFERENCES payments (payment_id),
            FOREIGN KEY (gateway_id) REFERENCES payment_gateways (gateway_id)
        );
CREATE TABLE gift_cards (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            code TEXT UNIQUE NOT NULL,
            initial_value REAL NOT NULL,
            current_balance REAL NOT NULL,
            purchaser_name TEXT,
            purchaser_email TEXT,
            recipient_name TEXT,
            recipient_email TEXT,
            message TEXT,
            purchase_date TEXT DEFAULT CURRENT_TIMESTAMP,
            expiry_date TEXT,
            status TEXT DEFAULT 'active'
        );
CREATE TABLE giving_campaigns (
            campaign_id INTEGER PRIMARY KEY AUTOINCREMENT,
            campaign_name TEXT NOT NULL,
            campaign_description TEXT,
            goal_amount REAL NOT NULL,
            current_amount REAL DEFAULT 0,
            donor_count INTEGER DEFAULT 0,
            start_date TEXT NOT NULL,
            end_date TEXT NOT NULL,
            campaign_type TEXT NOT NULL,
            is_active BOOLEAN DEFAULT 1,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE gpa_simulations (
                    simulation_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL,
                    simulation_name TEXT NOT NULL,
                    current_gpa REAL NOT NULL,
                    simulated_courses_json TEXT NOT NULL,
                    projected_gpa REAL NOT NULL,
                    projection_type TEXT DEFAULT 'What-If',
                    credits_simulated INTEGER DEFAULT 0,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
INSERT INTO "gpa_simulations" VALUES(1,'admin','Test Simulation',0.0,'[{"course_id": "CS101", "credits": 3, "expected_grade": "A"}, {"course_id": "CS102", "credits": 3, "expected_grade": "B+"}]',3.65,'What-If',6,'2026-01-18 22:03:31');
CREATE TABLE grade_analytics (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                student_id TEXT,
                module_code TEXT,
                assessment_date TEXT,
                grade_value DECIMAL(5,2),
                class_average DECIMAL(5,2),
                percentile_rank INTEGER,
                trend_direction TEXT,
                FOREIGN KEY (student_id) REFERENCES students (student_id),
                FOREIGN KEY (module_code) REFERENCES modules (module_code)
            );
CREATE TABLE grade_predictions (
                    prediction_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL,
                    course_id TEXT NOT NULL,
                    current_grade REAL,
                    predicted_final_grade TEXT,
                    confidence_level REAL DEFAULT 0.0,
                    prediction_factors_json TEXT,
                    improvement_suggestions_json TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE grade_statistics (
            stat_id INTEGER PRIMARY KEY AUTOINCREMENT,
            assessment_id INTEGER,
            mean REAL,
            median REAL,
            std_dev REAL,
            min_score REAL,
            max_score REAL,
            q1 REAL,
            q3 REAL,
            skewness REAL,
            kurtosis REAL,
            date_calculated TEXT,
            FOREIGN KEY (assessment_id) REFERENCES assessments (assessment_id)
        );
CREATE TABLE grades (
            grade_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT,
            assessment_id INTEGER,
            score REAL,
            letter_grade TEXT,
            submission_date TEXT,
            comments TEXT,
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (assessment_id) REFERENCES assessments (assessment_id)
        );
CREATE TABLE graduation_checklist (
                checklist_id INTEGER PRIMARY KEY AUTOINCREMENT,
                student_id TEXT NOT NULL,
                program_id INTEGER NOT NULL,
                all_requirements_met INTEGER DEFAULT 0,
                gpa_requirement_met INTEGER DEFAULT 0,
                credit_requirement_met INTEGER DEFAULT 0,
                residency_requirement_met INTEGER DEFAULT 0,
                financial_clearance INTEGER DEFAULT 0,
                conferral_status TEXT DEFAULT 'pending',
                graduation_date TEXT,
                last_checked TEXT NOT NULL DEFAULT (datetime('now')),
                FOREIGN KEY (program_id) REFERENCES degree_programs(program_id),
                UNIQUE(student_id, program_id)
            );
CREATE TABLE graduation_forecasts (
            forecast_id INTEGER PRIMARY KEY AUTOINCREMENT,
            cohort_year INTEGER NOT NULL,
            program_id INTEGER,
            predicted_graduation_rate REAL,
            predicted_4year_rate REAL,
            predicted_5year_rate REAL,
            predicted_6year_rate REAL,
            forecast_date TEXT DEFAULT CURRENT_TIMESTAMP,
            model_id INTEGER,
            confidence_interval TEXT,
            FOREIGN KEY (model_id) REFERENCES analytics_models (model_id)
        );
CREATE TABLE graduation_requirements (
                    id TEXT PRIMARY KEY,
                    requirement_name TEXT NOT NULL,
                    requirement_type TEXT NOT NULL,
                    credits_required INTEGER,
                    course_category TEXT,
                    deadline_date TEXT,
                    is_mandatory BOOLEAN DEFAULT TRUE,
                    created_at TEXT NOT NULL
                );
CREATE TABLE grant_applications (
            application_id INTEGER PRIMARY KEY AUTOINCREMENT,
            grant_name TEXT NOT NULL,
            funding_agency TEXT NOT NULL,
            project_id INTEGER,
            principal_investigator_id TEXT NOT NULL,
            co_investigators TEXT,
            requested_amount REAL NOT NULL,
            application_deadline TEXT NOT NULL,
            submission_date TEXT,
            decision_date TEXT,
            decision_status TEXT DEFAULT 'pending',
            awarded_amount REAL,
            grant_period_start TEXT,
            grant_period_end TEXT,
            application_documents TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (project_id) REFERENCES research_projects (project_id)
        );
CREATE TABLE grant_budget_allocations (
                    allocation_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    grant_application_id INTEGER NOT NULL,
                    category_id INTEGER NOT NULL,
                    allocated_amount REAL DEFAULT 0,
                    spent_amount REAL DEFAULT 0,
                    committed_amount REAL DEFAULT 0,
                    remaining_amount REAL DEFAULT 0,
                    alert_threshold_pct REAL DEFAULT 80,
                    notes TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (grant_application_id) REFERENCES grant_applications(grant_application_id),
                    FOREIGN KEY (category_id) REFERENCES grant_budget_categories(category_id)
                );
CREATE TABLE grant_budget_categories (
                    category_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL UNIQUE,
                    description TEXT,
                    is_active INTEGER DEFAULT 1,
                    sort_order INTEGER,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
