CREATE TABLE grievance_meetings (
                    meeting_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    grievance_id INTEGER NOT NULL,
                    meeting_date TEXT NOT NULL,
                    meeting_time TEXT,
                    location TEXT,
                    attendees TEXT,
                    purpose TEXT,
                    minutes TEXT,
                    outcomes TEXT,
                    follow_up_actions TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (grievance_id) REFERENCES grievances(grievance_id)
                );
CREATE TABLE grievances (
                    grievance_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    reference_number TEXT UNIQUE,
                    complainant_id TEXT NOT NULL,
                    respondent_id TEXT,
                    category_id INTEGER,
                    category_other TEXT,
                    subject TEXT NOT NULL,
                    description TEXT NOT NULL,
                    is_anonymous BOOLEAN DEFAULT 0,
                    is_confidential BOOLEAN DEFAULT 1,
                    status TEXT DEFAULT 'submitted',
                    priority TEXT DEFAULT 'normal',
                    assigned_to TEXT,
                    filed_date TEXT NOT NULL,
                    acknowledged_date TEXT,
                    investigation_start_date TEXT,
                    resolution_date TEXT,
                    resolution_type TEXT,
                    resolution_summary TEXT,
                    outcome TEXT,
                    appeal_deadline TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (category_id) REFERENCES grievance_categories(category_id)
                );
CREATE TABLE grocery_cart (
            cart_id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            product_id TEXT NOT NULL,
            quantity INTEGER NOT NULL DEFAULT 1,
            added_at TEXT NOT NULL,
            FOREIGN KEY (user_id) REFERENCES users (id),
            FOREIGN KEY (product_id) REFERENCES grocery_products (product_id),
            UNIQUE(user_id, product_id)
        );
CREATE TABLE grocery_categories (
            category_id TEXT PRIMARY KEY,
            name TEXT NOT NULL,
            description TEXT,
            display_order INTEGER DEFAULT 0,
            is_active BOOLEAN DEFAULT 1,
            created_at TEXT NOT NULL
        );
