CREATE TABLE incident_response_actions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                incident_id INTEGER NOT NULL,
                action_type TEXT NOT NULL,
                action_details TEXT,
                performed_by INTEGER,
                performed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (incident_id) REFERENCES security_incidents(id),
                FOREIGN KEY (performed_by) REFERENCES users(id)
            );
CREATE TABLE incidents (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            incident_type TEXT NOT NULL,
            severity TEXT DEFAULT 'low',
            description TEXT NOT NULL,
            location TEXT,
            screen_number INTEGER,
            incident_datetime TEXT NOT NULL,
            reported_by_staff_id INTEGER,
            witnesses TEXT,
            immediate_action_taken TEXT,
            resolution TEXT,
            resolved_by_staff_id INTEGER,
            resolved_datetime TEXT,
            customer_involved INTEGER DEFAULT 0,
            customer_name TEXT,
            customer_contact TEXT,
            follow_up_required INTEGER DEFAULT 0,
            follow_up_notes TEXT,
            follow_up_completed INTEGER DEFAULT 0,
            status TEXT DEFAULT 'open',
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (reported_by_staff_id) REFERENCES staff(id),
            FOREIGN KEY (resolved_by_staff_id) REFERENCES staff(id)
        );
CREATE TABLE installed_integrations (
            install_id INTEGER PRIMARY KEY AUTOINCREMENT,
            integration_id INTEGER NOT NULL,
            installed_by TEXT NOT NULL,
            installation_date TEXT DEFAULT CURRENT_TIMESTAMP,
            version_installed TEXT,
            configuration TEXT,
            status TEXT DEFAULT 'active',
            last_sync_date TEXT,
            sync_frequency TEXT,
            is_enabled BOOLEAN DEFAULT 1,
            FOREIGN KEY (integration_id) REFERENCES integration_catalog (integration_id)
        );
CREATE TABLE institutions (
                id TEXT PRIMARY KEY,
                name TEXT NOT NULL,
                type TEXT,
                country TEXT,
                created_at TEXT NOT NULL
            );
CREATE TABLE instructor_modules (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            instructor_id INTEGER NOT NULL,
            module_code TEXT NOT NULL,
            academic_year TEXT,
            semester TEXT,
            FOREIGN KEY (instructor_id) REFERENCES instructors(id),
            FOREIGN KEY (module_code) REFERENCES modules(module_code),
            UNIQUE(instructor_id, module_code)
        );
CREATE TABLE instructor_schedules (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            instructor_id INTEGER NOT NULL,
            module_code TEXT NOT NULL,
            day_of_week TEXT NOT NULL,
            time_slot TEXT NOT NULL,
            room TEXT,
            academic_year TEXT,
            semester TEXT,
            FOREIGN KEY (instructor_id) REFERENCES instructors(id),
            FOREIGN KEY (module_code) REFERENCES modules(module_code)
        );
CREATE TABLE instructors (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                first_name TEXT NOT NULL,
                last_name TEXT NOT NULL,
                email TEXT UNIQUE NOT NULL,
                department TEXT DEFAULT '',
                specialization TEXT DEFAULT '',
                max_courses_per_semester INTEGER DEFAULT 4,
                max_hours_per_week INTEGER DEFAULT 40,
                preferred_days TEXT,
                preferred_times TEXT,
                status TEXT DEFAULT 'Active',
                is_active BOOLEAN DEFAULT 1,
                created_at TEXT DEFAULT (datetime('now')),
                updated_at TEXT DEFAULT (datetime('now'))
            );
