CREATE TABLE insurance_information (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT,
            insurance_provider TEXT,
            policy_number TEXT,
            group_number TEXT,
            subscriber_name TEXT,
            relationship_to_subscriber TEXT,
            effective_date TEXT,
            expiry_date TEXT,
            created_at TEXT,
            FOREIGN KEY (student_id) REFERENCES students (student_id)
        );
CREATE TABLE insurance_integration_events (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                claim_id TEXT,
                patient_id TEXT,
                event_type TEXT,        -- submitted/approved/denied/cancelled
                status TEXT,
                external_id TEXT,
                correlation_id TEXT,
                payload TEXT,
                response TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT
            );
CREATE TABLE integration_catalog (
            integration_id INTEGER PRIMARY KEY AUTOINCREMENT,
            integration_name TEXT NOT NULL,
            provider_name TEXT NOT NULL,
            integration_type TEXT NOT NULL,
            category TEXT NOT NULL,
            description TEXT,
            version TEXT,
            logo_url TEXT,
            documentation_url TEXT,
            pricing_model TEXT,
            is_official BOOLEAN DEFAULT 0,
            is_active BOOLEAN DEFAULT 1,
            rating REAL DEFAULT 0,
            install_count INTEGER DEFAULT 0,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE integration_credentials (
            credential_id INTEGER PRIMARY KEY AUTOINCREMENT,
            install_id INTEGER NOT NULL,
            credential_type TEXT NOT NULL,
            api_key TEXT,
            api_secret TEXT,
            oauth_token TEXT,
            refresh_token TEXT,
            token_expiry TEXT,
            endpoint_url TEXT,
            additional_config TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            updated_at TEXT,
            FOREIGN KEY (install_id) REFERENCES installed_integrations (install_id)
        );
CREATE TABLE integration_data_mappings (
            mapping_id INTEGER PRIMARY KEY AUTOINCREMENT,
            install_id INTEGER NOT NULL,
            source_field TEXT NOT NULL,
            target_field TEXT NOT NULL,
            transformation_rule TEXT,
            is_active BOOLEAN DEFAULT 1,
            FOREIGN KEY (install_id) REFERENCES installed_integrations (install_id)
        );
CREATE TABLE integration_logs (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                provider TEXT,          -- e.g., 'insurance','lab','hl7','fhir'
                system   TEXT,          -- optional: vendor/system name
                event_type TEXT,
                status TEXT,            -- success, error, pending
                message TEXT,
                correlation_id TEXT,
                http_status INTEGER,
                duration_ms INTEGER,
                endpoint TEXT,
                payload TEXT,
                response TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE integration_sync_logs (
            log_id INTEGER PRIMARY KEY AUTOINCREMENT,
            install_id INTEGER NOT NULL,
            sync_start_time TEXT DEFAULT CURRENT_TIMESTAMP,
            sync_end_time TEXT,
            sync_status TEXT NOT NULL,
            records_synced INTEGER DEFAULT 0,
            errors_encountered INTEGER DEFAULT 0,
            error_details TEXT,
            FOREIGN KEY (install_id) REFERENCES installed_integrations (install_id)
        );
CREATE TABLE integration_usage_analytics (
            analytics_id INTEGER PRIMARY KEY AUTOINCREMENT,
            install_id INTEGER NOT NULL,
            metric_name TEXT NOT NULL,
            metric_value REAL NOT NULL,
            measurement_date TEXT DEFAULT CURRENT_DATE,
            FOREIGN KEY (install_id) REFERENCES installed_integrations (install_id)
        );
CREATE TABLE integration_webhooks (
            webhook_id INTEGER PRIMARY KEY AUTOINCREMENT,
            install_id INTEGER NOT NULL,
            webhook_url TEXT NOT NULL,
            event_type TEXT NOT NULL,
            secret_key TEXT,
            is_active BOOLEAN DEFAULT 1,
            last_triggered_at TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (install_id) REFERENCES installed_integrations (install_id)
        );
CREATE TABLE interdepartmental_requests (
                request_id INTEGER PRIMARY KEY AUTOINCREMENT,
                request_type TEXT NOT NULL,
                from_department TEXT,
                to_department TEXT,
                requested_by TEXT NOT NULL,
                requested_by_name TEXT,
                request_title TEXT NOT NULL,
                request_description TEXT,
                priority TEXT DEFAULT 'normal',
                status TEXT DEFAULT 'pending',
                assigned_to TEXT,
                assigned_to_name TEXT,
                due_date TEXT,
                completed_date TEXT,
                response TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE interest_matches (
                match_id INTEGER PRIMARY KEY AUTOINCREMENT,
                user1_id TEXT NOT NULL,
                user2_id TEXT NOT NULL,
                compatibility_score REAL NOT NULL,
                shared_interests TEXT,
                match_reason TEXT,
                match_status TEXT DEFAULT 'suggested',
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (user1_id) REFERENCES users(username),
                FOREIGN KEY (user2_id) REFERENCES users(username),
                UNIQUE(user1_id, user2_id)
            );
CREATE TABLE interlibrary_loans (
            ill_id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id TEXT NOT NULL,
            title TEXT NOT NULL,
            author TEXT,
            isbn TEXT,
            source_library TEXT,
            request_date TEXT NOT NULL,
            expected_arrival TEXT,
            actual_arrival TEXT,
            due_date TEXT,
            return_date TEXT,
            status TEXT DEFAULT 'requested',
            cost REAL DEFAULT 0.0
        );
CREATE TABLE internship_applications (
            application_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT,
            internship_id INTEGER,
            application_date TEXT,
            status TEXT DEFAULT 'pending',
            cv_filename TEXT,
            cover_letter TEXT,
            feedback TEXT,
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (internship_id) REFERENCES internships (internship_id)
        );
CREATE TABLE internship_placements (
            placement_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT,
            internship_id INTEGER,
            start_date TEXT,
            end_date TEXT,
            supervisor_name TEXT,
            supervisor_email TEXT,
            status TEXT DEFAULT 'active',
            feedback_student TEXT,
            feedback_employer TEXT,
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (internship_id) REFERENCES internships (internship_id)
        );
CREATE TABLE internships (
            internship_id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            company TEXT NOT NULL,
            location TEXT,
            description TEXT,
            requirements TEXT,
            start_date TEXT,
            end_date TEXT,
            is_paid BOOLEAN,
            salary TEXT,
            hours_per_week INTEGER,
            posted_date TEXT,
            deadline_date TEXT,
            status TEXT DEFAULT 'active',
            contact_email TEXT,
            course_relevance TEXT,
            created_by TEXT,
            created_date TEXT
        );
