CREATE TABLE intervention_types (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT,
            description TEXT
        );
CREATE TABLE interview_schedules (
            interview_id INTEGER PRIMARY KEY AUTOINCREMENT,
            application_id INTEGER NOT NULL,
            interview_type TEXT NOT NULL,
            interview_date TEXT NOT NULL,
            interview_time TEXT NOT NULL,
            duration_minutes INTEGER DEFAULT 60,
            location TEXT,
            interviewer_name TEXT,
            meeting_link TEXT,
            status TEXT DEFAULT 'scheduled',
            notes TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (application_id) REFERENCES job_applications (application_id)
        );
CREATE TABLE inventory (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                item_name TEXT NOT NULL,
                quantity INTEGER NOT NULL,
                unit TEXT NOT NULL,
                minimum_threshold INTEGER DEFAULT 10,
                supplier TEXT,
                cost_per_unit REAL,
                last_updated TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE ip_disclosures (
                    disclosure_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    title TEXT NOT NULL,
                    description TEXT,
                    ip_type TEXT DEFAULT 'invention',
                    development_stage TEXT DEFAULT 'concept',
                    funding_source TEXT,
                    department TEXT,
                    status TEXT DEFAULT 'draft',
                    submitted_date TEXT,
                    reviewed_by TEXT,
                    review_date TEXT,
                    review_comments TEXT,
                    created_by TEXT NOT NULL,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE ip_inventors (
                    inventor_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    disclosure_id INTEGER,
                    patent_id INTEGER,
                    user_id TEXT NOT NULL,
                    contribution_percentage REAL DEFAULT 0,
                    is_primary INTEGER DEFAULT 0,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (disclosure_id) REFERENCES ip_disclosures(disclosure_id),
                    FOREIGN KEY (patent_id) REFERENCES patents(patent_id)
                );
CREATE TABLE ip_licenses (
                    license_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    patent_id INTEGER,
                    disclosure_id INTEGER,
                    licensee_name TEXT NOT NULL,
                    license_type TEXT DEFAULT 'non_exclusive',
                    royalty_rate REAL DEFAULT 0,
                    territory TEXT DEFAULT 'worldwide',
                    start_date TEXT NOT NULL,
                    end_date TEXT,
                    annual_fee REAL DEFAULT 0,
                    status TEXT DEFAULT 'active',
                    notes TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (patent_id) REFERENCES patents(patent_id),
                    FOREIGN KEY (disclosure_id) REFERENCES ip_disclosures(disclosure_id)
                );
CREATE TABLE ip_revenue_shares (
                    revenue_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    license_id INTEGER NOT NULL,
                    period TEXT NOT NULL,
                    total_revenue REAL DEFAULT 0,
                    university_share REAL DEFAULT 0,
                    inventor_share REAL DEFAULT 0,
                    department_share REAL DEFAULT 0,
                    payment_date TEXT,
                    status TEXT DEFAULT 'pending',
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (license_id) REFERENCES ip_licenses(license_id)
                );
CREATE TABLE item_claims (
                    claim_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    found_item_id INTEGER NOT NULL,
                    claimant_id TEXT NOT NULL,
                    claim_description TEXT NOT NULL,
                    verification_questions TEXT,
                    verification_answers TEXT,
                    supporting_evidence TEXT,
                    status TEXT DEFAULT 'Pending',
                    submitted_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    reviewed_at TEXT,
                    reviewed_by TEXT,
                    resolution_notes TEXT,
                    FOREIGN KEY (found_item_id) REFERENCES found_items(item_id) ON DELETE CASCADE,
                    FOREIGN KEY (claimant_id) REFERENCES students(student_id)
                );
CREATE TABLE item_matches (
                    match_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    lost_item_id INTEGER NOT NULL,
                    found_item_id INTEGER NOT NULL,
                    match_score REAL NOT NULL,
                    match_reasons TEXT,
                    status TEXT DEFAULT 'Suggested',
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (lost_item_id) REFERENCES lost_items(item_id) ON DELETE CASCADE,
                    FOREIGN KEY (found_item_id) REFERENCES found_items(item_id) ON DELETE CASCADE
                );
CREATE TABLE item_photos (
                    photo_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    item_type TEXT NOT NULL,
                    item_id INTEGER NOT NULL,
                    photo_path TEXT NOT NULL,
                    photo_hash TEXT,
                    caption TEXT,
                    uploaded_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE job_applications (
            application_id INTEGER PRIMARY KEY AUTOINCREMENT,
            job_id INTEGER,
            applicant_id TEXT,
            application_date TEXT,
            status TEXT DEFAULT 'submitted',
            cover_letter TEXT,
            resume_path TEXT,
            FOREIGN KEY (job_id) REFERENCES job_postings (job_id),
            FOREIGN KEY (applicant_id) REFERENCES alumni (alumni_id)
        );
CREATE TABLE job_postings (
            job_id INTEGER PRIMARY KEY AUTOINCREMENT,
            posted_by TEXT,
            company_name TEXT,
            job_title TEXT,
            job_description TEXT,
            location TEXT,
            job_type TEXT,
            salary_range TEXT,
            requirements TEXT,
            application_method TEXT,
            contact_email TEXT,
            post_date TEXT,
            expiry_date TEXT,
            is_active BOOLEAN DEFAULT 1,
            category TEXT,
            experience_level TEXT,
            FOREIGN KEY (posted_by) REFERENCES alumni (alumni_id)
        );
CREATE TABLE job_skill_requirements (
                        requirement_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        job_id INTEGER NOT NULL,
                        skill_name TEXT NOT NULL,
                        is_required BOOLEAN DEFAULT 1,
                        minimum_proficiency TEXT CHECK(minimum_proficiency IN ('beginner', 'intermediate', 'advanced', 'expert')),
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        FOREIGN KEY (job_id) REFERENCES campus_job_postings(job_id),
                        UNIQUE(job_id, skill_name)
                    );
CREATE TABLE kb_articles (
            article_id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            content TEXT NOT NULL,
            summary TEXT,
            category TEXT NOT NULL,
            tags TEXT,  -- JSON array
            author_id TEXT NOT NULL,
            created_datetime TEXT NOT NULL,
            updated_datetime TEXT,
            published_datetime TEXT,
            is_published BOOLEAN DEFAULT 0,
            view_count INTEGER DEFAULT 0,
            helpful_votes INTEGER DEFAULT 0,
            not_helpful_votes INTEGER DEFAULT 0,
            search_keywords TEXT,  -- Space-separated keywords for search
            related_articles TEXT  -- JSON array of related article IDs
        );
CREATE TABLE key_assignments (
                assignment_id INTEGER PRIMARY KEY AUTOINCREMENT,
                key_number TEXT NOT NULL,
                key_type TEXT,
                room_location TEXT,
                building TEXT,
                assigned_to TEXT,
                assigned_to_name TEXT,
                assigned_date TEXT,
                return_date TEXT,
                status TEXT DEFAULT 'assigned',
                issued_by TEXT,
                notes TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE knowledge_base (
            article_id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            content TEXT NOT NULL,
            category TEXT,
            tags TEXT,
            author_id INTEGER,
            status TEXT DEFAULT 'draft',
            views INTEGER DEFAULT 0,
            helpful_votes INTEGER DEFAULT 0,
            unhelpful_votes INTEGER DEFAULT 0,
            search_keywords TEXT,
            created_at TEXT,
            updated_at TEXT,
            FOREIGN KEY (author_id) REFERENCES users (id)
        );
