CREATE TABLE lms_discussion_forums (
                forum_id INTEGER PRIMARY KEY AUTOINCREMENT,
                lms_course_id INTEGER NOT NULL,
                topic TEXT NOT NULL,
                description TEXT,
                created_by TEXT NOT NULL,
                is_pinned INTEGER DEFAULT 0,
                is_locked INTEGER DEFAULT 0,
                created_at TEXT NOT NULL DEFAULT (datetime('now')),
                FOREIGN KEY (lms_course_id) REFERENCES lms_courses(lms_course_id) ON DELETE CASCADE
            );
CREATE TABLE lms_discussion_posts (
                post_id INTEGER PRIMARY KEY AUTOINCREMENT,
                forum_id INTEGER NOT NULL,
                user_id TEXT NOT NULL,
                content TEXT NOT NULL,
                parent_post_id INTEGER,
                attachments TEXT,
                likes_count INTEGER DEFAULT 0,
                is_instructor_post INTEGER DEFAULT 0,
                created_at TEXT NOT NULL DEFAULT (datetime('now')),
                FOREIGN KEY (forum_id) REFERENCES lms_discussion_forums(forum_id) ON DELETE CASCADE,
                FOREIGN KEY (parent_post_id) REFERENCES lms_discussion_posts(post_id) ON DELETE CASCADE
            );
CREATE TABLE lms_gradebook (
                entry_id INTEGER PRIMARY KEY AUTOINCREMENT,
                lms_course_id INTEGER NOT NULL,
                student_id TEXT NOT NULL,
                assignment_type TEXT NOT NULL,
                assignment_id INTEGER NOT NULL,
                score REAL NOT NULL,
                max_score REAL NOT NULL,
                weight REAL DEFAULT 1.0,
                feedback TEXT,
                graded_by TEXT,
                graded_at TEXT NOT NULL DEFAULT (datetime('now')),
                FOREIGN KEY (lms_course_id) REFERENCES lms_courses(lms_course_id) ON DELETE CASCADE
            );
CREATE TABLE lms_lessons (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            module_id INTEGER NOT NULL,
            title TEXT NOT NULL,
            content_type TEXT NOT NULL DEFAULT 'text',
            content TEXT,
            order_index INTEGER NOT NULL DEFAULT 0,
            duration_mins INTEGER,
            created_at TEXT NOT NULL DEFAULT (datetime('now')),
            FOREIGN KEY (module_id) REFERENCES lms_modules(id)
        );
CREATE TABLE lms_modules (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            course_id INTEGER NOT NULL,
            title TEXT NOT NULL,
            description TEXT,
            order_index INTEGER NOT NULL DEFAULT 0,
            published INTEGER NOT NULL DEFAULT 0,
            created_by TEXT,
            created_at TEXT NOT NULL DEFAULT (datetime('now'))
        );
CREATE TABLE lms_progress (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            lesson_id INTEGER NOT NULL,
            completed INTEGER NOT NULL DEFAULT 0,
            completed_at TEXT,
            FOREIGN KEY (lesson_id) REFERENCES lms_lessons(id),
            UNIQUE (student_id, lesson_id)
        );
CREATE TABLE lms_questions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            quiz_id INTEGER NOT NULL,
            question_text TEXT NOT NULL,
            question_type TEXT NOT NULL DEFAULT 'multiple_choice',
            options_json TEXT,
            correct_answer TEXT NOT NULL,
            marks REAL NOT NULL DEFAULT 1.0,
            order_index INTEGER NOT NULL DEFAULT 0,
            FOREIGN KEY (quiz_id) REFERENCES lms_quizzes(id)
        );
CREATE TABLE lms_quiz_attempts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            quiz_id INTEGER NOT NULL,
            student_id TEXT NOT NULL,
            answers_json TEXT,
            score REAL,
            passed INTEGER NOT NULL DEFAULT 0,
            attempted_at TEXT NOT NULL DEFAULT (datetime('now')),
            FOREIGN KEY (quiz_id) REFERENCES lms_quizzes(id)
        );
CREATE TABLE lms_quiz_questions (
                question_id INTEGER PRIMARY KEY AUTOINCREMENT,
                quiz_id INTEGER NOT NULL,
                question_text TEXT NOT NULL,
                question_type TEXT NOT NULL,
                correct_answer TEXT NOT NULL,
                points INTEGER DEFAULT 1,
                options TEXT,
                explanation TEXT,
                display_order INTEGER DEFAULT 0,
                FOREIGN KEY (quiz_id) REFERENCES lms_quizzes(quiz_id) ON DELETE CASCADE
            );
CREATE TABLE lms_quiz_submissions (
                submission_id INTEGER PRIMARY KEY AUTOINCREMENT,
                quiz_id INTEGER NOT NULL,
                student_id TEXT NOT NULL,
                attempt_number INTEGER NOT NULL,
                score REAL NOT NULL,
                total_points INTEGER NOT NULL,
                time_taken_minutes INTEGER,
                submitted_at TEXT NOT NULL DEFAULT (datetime('now')),
                FOREIGN KEY (quiz_id) REFERENCES lms_quizzes(quiz_id) ON DELETE CASCADE
            );
CREATE TABLE lms_quizzes (
                quiz_id INTEGER PRIMARY KEY AUTOINCREMENT,
                lms_course_id INTEGER NOT NULL,
                title TEXT NOT NULL,
                description TEXT,
                duration_minutes INTEGER DEFAULT 60,
                passing_score REAL DEFAULT 70.0,
                max_attempts INTEGER DEFAULT 1,
                available_from TEXT,
                available_until TEXT,
                is_published INTEGER DEFAULT 0,
                created_at TEXT NOT NULL DEFAULT (datetime('now')),
                FOREIGN KEY (lms_course_id) REFERENCES lms_courses(lms_course_id) ON DELETE CASCADE
            );
CREATE TABLE lms_resources (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            description TEXT,
            file_path TEXT,
            resource_type TEXT NOT NULL DEFAULT 'document',
            course_id INTEGER,
            uploaded_by TEXT,
            download_count INTEGER NOT NULL DEFAULT 0,
            created_at TEXT NOT NULL DEFAULT (datetime('now'))
        );
CREATE TABLE lms_settings (
                        id INTEGER PRIMARY KEY,
                        platform TEXT,
                        api_url TEXT,
                        api_key TEXT,
                        username TEXT,
                        auto_sync INTEGER,
                        sync_grades INTEGER,
                        bidirectional INTEGER,
                        sync_frequency TEXT
                    );
CREATE TABLE lms_student_enrollment (
                enrollment_id INTEGER PRIMARY KEY AUTOINCREMENT,
