CREATE TABLE logs (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
                user_id TEXT,
                username TEXT,
                action TEXT,
                status TEXT,
                module TEXT,
                message TEXT,
                ip_address TEXT,
                user_agent TEXT
            );
CREATE TABLE lost_found (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            item_description TEXT NOT NULL,
            category TEXT DEFAULT 'other',
            location_found TEXT,
            screen_number INTEGER,
            found_date TEXT NOT NULL,
            found_time TEXT,
            found_by_staff_id INTEGER,
            storage_location TEXT,
            claimed INTEGER DEFAULT 0,
            claimed_by_name TEXT,
            claimed_by_email TEXT,
            claimed_by_phone TEXT,
            claim_date TEXT,
            verified_by_staff_id INTEGER,
            identification_method TEXT,
            status TEXT DEFAULT 'unclaimed',
            notes TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (found_by_staff_id) REFERENCES staff(id),
            FOREIGN KEY (verified_by_staff_id) REFERENCES staff(id)
        );
CREATE TABLE lost_items (
                    item_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    reporter_id TEXT NOT NULL,
                    item_name TEXT NOT NULL,
                    category TEXT NOT NULL,
                    description TEXT NOT NULL,
                    lost_date TEXT NOT NULL,
                    lost_location TEXT NOT NULL,
                    lost_time TEXT,
                    distinctive_features TEXT,
                    color TEXT,
                    brand TEXT,
                    estimated_value REAL,
                    contact_email TEXT,
                    contact_phone TEXT,
                    status TEXT DEFAULT 'Active',
                    reported_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (reporter_id) REFERENCES students(student_id)
                );
CREATE TABLE mail_forwarding (
                    forwarding_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT NOT NULL,
                    user_name TEXT NOT NULL,
                    forward_address TEXT NOT NULL,
                    forward_type TEXT DEFAULT 'domestic',
                    start_date DATE NOT NULL,
                    end_date DATE,
                    status TEXT DEFAULT 'active',
                    fee DECIMAL(10,2) DEFAULT 0.00,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE mail_notifications (
                    notification_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    package_id INTEGER NOT NULL,
                    recipient_email TEXT NOT NULL,
                    notification_type TEXT NOT NULL,
                    sent_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    status TEXT DEFAULT 'sent',
                    FOREIGN KEY (package_id) REFERENCES mail_packages(package_id)
                );
CREATE TABLE mail_packages (
                    package_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    tracking_number TEXT UNIQUE NOT NULL,
                    recipient_id TEXT NOT NULL,
                    recipient_name TEXT NOT NULL,
                    recipient_email TEXT,
                    recipient_phone TEXT,
                    sender_name TEXT,
                    sender_address TEXT,
                    package_type TEXT NOT NULL,
                    description TEXT,
                    weight_kg DECIMAL(10,2),
                    dimensions TEXT,
                    status TEXT DEFAULT 'received',
                    storage_location TEXT,
                    received_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    notification_sent INTEGER DEFAULT 0,
                    notification_date TIMESTAMP,
                    collected_date TIMESTAMP,
                    collected_by TEXT,
                    storage_fee DECIMAL(10,2) DEFAULT 0.00,
                    total_charges DECIMAL(10,2) DEFAULT 0.00,
                    payment_status TEXT DEFAULT 'pending',
                    notes TEXT,
                    created_by TEXT
                );
CREATE TABLE mail_po_boxes (
                    box_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    box_number TEXT UNIQUE NOT NULL,
                    holder_id TEXT,
                    holder_name TEXT,
                    holder_email TEXT,
                    size TEXT DEFAULT 'standard',
                    monthly_fee DECIMAL(10,2) DEFAULT 10.00,
                    status TEXT DEFAULT 'available',
                    rental_start DATE,
                    rental_end DATE,
                    auto_renew INTEGER DEFAULT 1,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                );
