CREATE TABLE mail_transactions (
                    transaction_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    reference TEXT UNIQUE NOT NULL,
                    user_id TEXT NOT NULL,
                    transaction_type TEXT NOT NULL,
                    package_id INTEGER,
                    amount DECIMAL(10,2) NOT NULL,
                    payment_method TEXT,
                    status TEXT DEFAULT 'completed',
                    receipt_sent INTEGER DEFAULT 0,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    processed_by TEXT,
                    FOREIGN KEY (package_id) REFERENCES mail_packages(package_id)
                );
CREATE TABLE maintenance_requests (
                request_id INTEGER PRIMARY KEY AUTOINCREMENT,
                location_type TEXT NOT NULL,
                building_id INTEGER,
                room_id INTEGER,
                request_type TEXT NOT NULL,
                priority TEXT NOT NULL,
                description TEXT NOT NULL,
                reported_by TEXT NOT NULL,
                reported_date TEXT DEFAULT CURRENT_TIMESTAMP,
                assigned_to TEXT,
                assigned_date TEXT,
                scheduled_date TEXT,
                completion_date TEXT,
                status TEXT DEFAULT 'open',
                cost REAL,
                notes TEXT,
                FOREIGN KEY (building_id) REFERENCES buildings (building_id),
                FOREIGN KEY (room_id) REFERENCES rooms (id)
            );
INSERT INTO "maintenance_requests" VALUES(1,'building',1,NULL,'plumbing','medium','test','admin','2026-01-24 15:39:51',NULL,NULL,NULL,NULL,'open',NULL,NULL);
CREATE TABLE managed_api_keys (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    key_id TEXT UNIQUE NOT NULL,
                    key_hash TEXT NOT NULL,
                    name TEXT NOT NULL,
                    user_id INTEGER,
                    created_at TEXT NOT NULL,
                    expires_at TEXT,
                    last_used_at TEXT,
                    is_active INTEGER DEFAULT 1,
                    permissions TEXT,
                    metadata TEXT,
                    previous_key_hash TEXT,
                    previous_key_valid_until TEXT
                );
CREATE TABLE marketplace_listings (
                    listing_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    seller_id TEXT NOT NULL,
                    listing_type TEXT NOT NULL,
                    title TEXT NOT NULL,
                    description TEXT NOT NULL,
                    category TEXT NOT NULL,
                    price REAL,
                    condition_status TEXT,
                    location TEXT,
                    contact_method TEXT DEFAULT 'Message',
                    contact_info TEXT,
                    is_negotiable BOOLEAN DEFAULT 1,
                    status TEXT DEFAULT 'Active',
                    view_count INTEGER DEFAULT 0,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    expires_at TEXT,
                    FOREIGN KEY (seller_id) REFERENCES students(student_id)
                );
CREATE TABLE marketplace_messages (
                    message_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    listing_type TEXT NOT NULL,
                    listing_id INTEGER NOT NULL,
                    sender_id TEXT NOT NULL,
                    receiver_id TEXT NOT NULL,
                    message_text TEXT NOT NULL,
                    is_read BOOLEAN DEFAULT 0,
                    sent_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (sender_id) REFERENCES students(student_id),
                    FOREIGN KEY (receiver_id) REFERENCES students(student_id)
                );
CREATE TABLE marketplace_reports (
                    report_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    listing_type TEXT NOT NULL,
                    listing_id INTEGER NOT NULL,
                    reporter_id TEXT NOT NULL,
                    reason TEXT NOT NULL,
                    description TEXT,
                    status TEXT DEFAULT 'Pending',
                    reviewed_at TEXT,
                    reviewed_by TEXT,
                    resolution TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (reporter_id) REFERENCES students(student_id)
                );
CREATE TABLE marketplace_reviews (
                    review_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    listing_type TEXT NOT NULL,
                    listing_id INTEGER NOT NULL,
                    reviewer_id TEXT NOT NULL,
                    seller_id TEXT NOT NULL,
                    rating INTEGER NOT NULL,
                    review_text TEXT,
                    transaction_completed BOOLEAN DEFAULT 1,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (reviewer_id) REFERENCES students(student_id),
                    FOREIGN KEY (seller_id) REFERENCES students(student_id)
                );
CREATE TABLE meal_accounts (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                student_id TEXT UNIQUE,
                balance DECIMAL(10,2) DEFAULT 0.00,
                low_balance_threshold DECIMAL(10,2) DEFAULT 10.00,
                auto_topup_enabled BOOLEAN DEFAULT 0,
                auto_topup_amount DECIMAL(10,2) DEFAULT 20.00,
                last_updated TEXT,
                FOREIGN KEY (student_id) REFERENCES students (student_id)
            );
CREATE TABLE meal_plan_tracking (
                        tracking_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        student_id TEXT NOT NULL,
                        meal_plan_id INTEGER,
                        academic_term TEXT NOT NULL,
                        plan_name TEXT NOT NULL,
                        plan_type TEXT CHECK(plan_type IN ('unlimited', 'block', 'declining-balance', 'hybrid')),
                        total_meals INTEGER DEFAULT 0,
                        used_meals INTEGER DEFAULT 0,
                        total_dollars REAL DEFAULT 0.0,
                        used_dollars REAL DEFAULT 0.0,
                        start_date TEXT NOT NULL,
                        end_date TEXT NOT NULL,
                        weekly_average_meals REAL,
                        daily_average_dollars REAL,
                        is_active BOOLEAN DEFAULT 1,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        FOREIGN KEY (student_id) REFERENCES students(student_id)
                    );
CREATE TABLE meal_plan_transactions (
                        transaction_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        tracking_id INTEGER NOT NULL,
                        student_id TEXT NOT NULL,
                        transaction_date TEXT NOT NULL,
                        transaction_time TEXT NOT NULL,
                        location TEXT NOT NULL,
                        meal_type TEXT CHECK(meal_type IN ('breakfast', 'lunch', 'dinner', 'snack', 'guest-meal')),
                        meals_used INTEGER DEFAULT 0,
                        dollars_used REAL DEFAULT 0.0,
                        description TEXT,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        FOREIGN KEY (tracking_id) REFERENCES meal_plan_tracking(tracking_id),
                        FOREIGN KEY (student_id) REFERENCES students(student_id)
                    );
CREATE TABLE meal_transactions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                student_id TEXT,
                transaction_type TEXT,
                amount DECIMAL(10,2),
                description TEXT,
                transaction_date TEXT,
                balance_after DECIMAL(10,2),
                FOREIGN KEY (student_id) REFERENCES students (student_id)
            );
CREATE TABLE medical_conditions (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT,
                    condition_name TEXT,
                    icd_code TEXT,
                    severity TEXT,
                    diagnosed_date TEXT,
                    status TEXT DEFAULT 'active',
                    provider TEXT,
                    notes TEXT,
                    created_at TEXT,
                    FOREIGN KEY (student_id) REFERENCES students (student_id)
                );
CREATE TABLE medical_info (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL,
                    blood_type TEXT,
                    allergies TEXT,
                    medications TEXT,
                    conditions TEXT,
                    doctor_name TEXT,
                    doctor_phone TEXT,
                    insurance_provider TEXT,
                    insurance_policy TEXT,
                    last_updated TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE meeting_agenda_items (
                    item_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    meeting_id INTEGER NOT NULL,
                    item_order INTEGER NOT NULL DEFAULT 1,
                    title TEXT NOT NULL,
                    description TEXT,
                    item_type TEXT DEFAULT 'discussion',
                    presenter_id TEXT,
                    duration_minutes INTEGER DEFAULT 15,
                    resolution TEXT,
                    status TEXT DEFAULT 'pending',
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (meeting_id) REFERENCES committee_meetings(meeting_id)
                );
CREATE TABLE meeting_minutes (
                minutes_id INTEGER PRIMARY KEY AUTOINCREMENT,
                committee_id INTEGER,
                committee_name TEXT,
                meeting_title TEXT NOT NULL,
                meeting_date TEXT NOT NULL,
                meeting_time TEXT,
                location TEXT,
                attendees TEXT,
                apologies TEXT,
                agenda TEXT,
                minutes_content TEXT,
                action_items TEXT,
                decisions TEXT,
                next_meeting_date TEXT,
                recorded_by TEXT,
                recorded_by_name TEXT,
                approved_by TEXT,
                approved_date TEXT,
                status TEXT DEFAULT 'draft',
                document_path TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP, [meeting_id] INTEGER,
                FOREIGN KEY (committee_id) REFERENCES committees(committee_id)
            );
CREATE TABLE members (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            email TEXT UNIQUE NOT NULL,
            name TEXT NOT NULL,
            phone TEXT,
            points INTEGER DEFAULT 0,
            tier TEXT DEFAULT 'Bronze',
            total_spent REAL DEFAULT 0,
            bookings_count INTEGER DEFAULT 0,
            join_date TEXT DEFAULT CURRENT_TIMESTAMP,
            birthday TEXT,
            preferences TEXT,
            status TEXT DEFAULT 'active'
        , referral_code TEXT, credit_balance REAL DEFAULT 0, favorite_seats TEXT, avatar TEXT);
CREATE TABLE mental_health_appointments (
            appointment_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            counselor_id INTEGER,
            appointment_type TEXT NOT NULL,
            appointment_date TEXT NOT NULL,
            appointment_time TEXT NOT NULL,
            duration_minutes INTEGER DEFAULT 50,
            is_anonymous INTEGER DEFAULT 0,
            anonymous_code TEXT,
            mode TEXT DEFAULT 'in-person',
            location TEXT,
            notes TEXT,
            status TEXT DEFAULT 'scheduled',
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (counselor_id) REFERENCES mental_health_counselors (counselor_id)
        );
CREATE TABLE mental_health_checkins (
            checkin_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            mood_rating INTEGER NOT NULL,
            stress_level INTEGER NOT NULL,
            sleep_quality INTEGER,
            notes TEXT,
            follow_up_required INTEGER DEFAULT 0,
            checkin_date TEXT DEFAULT (DATE('now')),
            checkin_time TEXT DEFAULT (TIME('now'))
        );
CREATE TABLE mental_health_counselors (
            counselor_id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id TEXT NOT NULL,
            name TEXT NOT NULL,
            specialization TEXT,
            qualifications TEXT,
            availability_schedule TEXT,
            max_daily_appointments INTEGER DEFAULT 8,
            is_active INTEGER DEFAULT 1,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE mental_health_meditation_sessions (
            session_id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            description TEXT,
            audio_url TEXT NOT NULL,
            duration_minutes INTEGER NOT NULL,
            category TEXT NOT NULL,
            difficulty_level TEXT DEFAULT 'beginner',
            play_count INTEGER DEFAULT 0,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE mental_health_meditation_tracking (
            tracking_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            session_id INTEGER NOT NULL,
            completion_percentage INTEGER DEFAULT 0,
            completed_at TEXT,
            started_at TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (session_id) REFERENCES mental_health_meditation_sessions (session_id)
        );
CREATE TABLE mental_health_peer_support (
            support_id INTEGER PRIMARY KEY AUTOINCREMENT,
            supporter_student_id TEXT NOT NULL,
            supported_student_id TEXT NOT NULL,
            support_type TEXT NOT NULL,
            notes TEXT,
            session_count INTEGER DEFAULT 0,
            last_session_date TEXT,
            status TEXT DEFAULT 'active',
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE mental_health_resources (
            resource_id INTEGER PRIMARY KEY AUTOINCREMENT,
            category TEXT NOT NULL,
            title TEXT NOT NULL,
            description TEXT,
            content_type TEXT NOT NULL,
            content_url TEXT,
            tags TEXT,
            view_count INTEGER DEFAULT 0,
            is_published INTEGER DEFAULT 1,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE mentoring_connections (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    mentor_id TEXT NOT NULL,
                    mentee_student_id TEXT NOT NULL,
                    area TEXT,
                    status TEXT DEFAULT 'pending',
                    started_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    ended_at TEXT,
                    notes TEXT
                );
CREATE TABLE mentorship_matches (
            match_id INTEGER PRIMARY KEY AUTOINCREMENT,
            mentor_id INTEGER NOT NULL,
            mentee_student_id TEXT NOT NULL,
            match_date TEXT DEFAULT CURRENT_DATE,
            status TEXT DEFAULT 'active',
            meeting_frequency TEXT DEFAULT 'monthly',
            last_meeting_date TEXT,
            notes TEXT,
            FOREIGN KEY (mentor_id) REFERENCES alumni_mentors (mentor_id),
            FOREIGN KEY (mentee_student_id) REFERENCES students (student_id)
        );
CREATE TABLE mentorship_relationships (
            relationship_id INTEGER PRIMARY KEY AUTOINCREMENT,
            mentor_id TEXT,
            mentee_id TEXT,
            skill_area TEXT,
            start_date TEXT,
            end_date TEXT,
            status TEXT DEFAULT 'active',
            mentor_rating REAL,
            mentee_rating REAL,
            notes TEXT,
            FOREIGN KEY (mentor_id) REFERENCES students (student_id),
            FOREIGN KEY (mentee_id) REFERENCES students (student_id)
        );
CREATE TABLE mentorship_sessions (
            session_id INTEGER PRIMARY KEY AUTOINCREMENT,
            relationship_id INTEGER,
            session_date TEXT,
            duration_minutes INTEGER,
            notes TEXT,
            mentor_feedback TEXT,
            mentee_feedback TEXT,
            progress_rating INTEGER,
            FOREIGN KEY (relationship_id) REFERENCES mentorship_relationships (relationship_id)
        );
CREATE TABLE mentorships (
            mentorship_id INTEGER PRIMARY KEY AUTOINCREMENT,
            mentor_id TEXT,
            mentee_id TEXT,
            start_date TEXT,
            end_date TEXT,
            status TEXT,
            focus_area TEXT,
            notes TEXT,
            match_score REAL DEFAULT 0.0,
            meeting_frequency TEXT,
            communication_preference TEXT,
            goals TEXT,
            FOREIGN KEY (mentor_id) REFERENCES alumni (alumni_id)
        );
CREATE TABLE menu_items (
                item_id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                description TEXT,
                price REAL NOT NULL,
                category TEXT,
                allergens TEXT,
                vegetarian BOOLEAN DEFAULT 0,
                vegan BOOLEAN DEFAULT 0,
                available BOOLEAN DEFAULT 1
            );
