CREATE TABLE mfa_recovery_codes (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                code_hash TEXT NOT NULL,  -- Hashed recovery code
                is_used BOOLEAN DEFAULT 0,
                used_at TIMESTAMP,
                generated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                expires_at TIMESTAMP,  -- Optional expiration
                FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
            );
CREATE TABLE mfa_trusted_devices (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                device_id TEXT NOT NULL,  -- Unique device identifier
                device_name TEXT,
                device_fingerprint TEXT,  -- Browser/OS fingerprint
                ip_address TEXT,
                trust_token TEXT NOT NULL UNIQUE,  -- Secure token for verification
                is_trusted BOOLEAN DEFAULT 1,
                trusted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                expires_at TIMESTAMP NOT NULL,  -- Trust expiration (default 30 days)
                last_used_at TIMESTAMP,
                revoked_at TIMESTAMP,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
                UNIQUE(user_id, device_id)
            );
CREATE TABLE mfa_user_settings (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER NOT NULL UNIQUE,
        mfa_enabled INTEGER DEFAULT 0,
        backup_codes_generated INTEGER DEFAULT 0,
        enforcement_deadline TIMESTAMP,
        bypass_until TIMESTAMP,
        failed_attempts INTEGER DEFAULT 0,
        locked_until TIMESTAMP,
        last_successful_verification TIMESTAMP,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, verification_disabled BOOLEAN DEFAULT 0, mfa_status TEXT DEFAULT 'disabled' CHECK(mfa_status IN ('active', 'disabled')), disabled_at TIMESTAMP,
        FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
    );
