CREATE TABLE micro_credentials (
    micro_id INTEGER PRIMARY KEY AUTOINCREMENT,
    skill_name TEXT NOT NULL,
    description TEXT,
    criteria TEXT NOT NULL,
    points INTEGER DEFAULT 1,
    category TEXT,  -- technical, soft_skills, academic
    is_stackable BOOLEAN DEFAULT 1,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE mobile_analytics (
                analytics_id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER,
                event_type TEXT NOT NULL,
                event_data TEXT,
                timestamp TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (user_id) REFERENCES users(id)
            );
CREATE TABLE mobile_devices (
                device_id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                device_name TEXT,
                device_type TEXT,
                os_version TEXT,
                app_version TEXT,
                push_token TEXT,
                registered_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                last_active TIMESTAMP,
                FOREIGN KEY (user_id) REFERENCES users(id)
            );
CREATE TABLE mobile_preferences (
                pref_id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL UNIQUE,
                notifications_enabled BOOLEAN DEFAULT 1,
                dark_mode BOOLEAN DEFAULT 0,
                language TEXT DEFAULT 'en',
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (user_id) REFERENCES users(id)
            );
CREATE TABLE mobile_sessions (
                session_id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                device_id INTEGER,
                login_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                logout_time TIMESTAMP,
                session_token TEXT,
                FOREIGN KEY (user_id) REFERENCES users(id),
                FOREIGN KEY (device_id) REFERENCES mobile_devices(device_id)
            );
CREATE TABLE module_grades (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT,
            module_code TEXT,
            final_score REAL,
            final_grade TEXT,
            completion_date TEXT,
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (module_code) REFERENCES modules (module_code)
        );
CREATE TABLE module_schedule (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                module_code TEXT,
                day_of_week TEXT,
                start_time TEXT,
                end_time TEXT,
                room_id INTEGER,
                instructor_id INTEGER,
                session_type TEXT,
                created_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                modified_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (module_code) REFERENCES modules (module_code),
                FOREIGN KEY (room_id) REFERENCES rooms (id),
                FOREIGN KEY (instructor_id) REFERENCES instructors (id)
            );
