            send_method TEXT DEFAULT 'email', -- 'email', 'sms', 'push'
            is_active BOOLEAN DEFAULT 1,
            created_at TEXT,
            updated_at TEXT
        );
INSERT INTO "notification_templates" VALUES(5,'Payment Due Reminder','payment_reminder','Payment Reminder: {{amount}} due on {{due_date}}','Dear {{student_name}},

This is a friendly reminder that your payment of {{currency}}{{amount}} is due on {{due_date}}.

Fee Type: {{fee_type}}
Invoice Number: {{invoice_number}}

Please log in to the student portal to make your payment or contact the finance office if you have any questions.

Best regards,
University Finance Office','email',1,'2025-12-12T11:32:53.462595','2025-12-12T11:32:53.462595');
INSERT INTO "notification_templates" VALUES(6,'Overdue Payment Notice','overdue_notice','URGENT: Overdue Payment - {{amount}} past due','Dear {{student_name}},

Your payment of {{currency}}{{amount}} was due on {{due_date}} and is now {{days_overdue}} days overdue.

Original Amount: {{currency}}{{original_amount}}
Late Fee Applied: {{currency}}{{late_fee}}
Total Due: {{currency}}{{total_due}}

Please make payment immediately to avoid further penalties and potential holds on your student account.

If you are experiencing financial difficulties, please contact our finance office to discuss payment options.

Best regards,
University Finance Office','email',1,'2025-12-12T11:32:53.462595','2025-12-12T11:32:53.462595');
INSERT INTO "notification_templates" VALUES(7,'Payment Confirmation','payment_confirmation','Payment Received - Receipt #{{receipt_number}}','Dear {{student_name}},

Thank you for your payment. This email confirms receipt of your payment.

Payment Details:
Amount: {{currency}}{{amount}}
Payment Method: {{payment_method}}
Transaction ID: {{transaction_id}}
Receipt Number: {{receipt_number}}
Payment Date: {{payment_date}}

Your updated account balance is: {{currency}}{{account_balance}}

Please keep this email for your records.

Best regards,
University Finance Office','email',1,'2025-12-12T11:32:53.462595','2025-12-12T11:32:53.462595');
INSERT INTO "notification_templates" VALUES(8,'Payment Plan Created','payment_plan_created','Payment Plan Confirmation - Plan #{{plan_id}}','Dear {{student_name}},

Your payment plan has been successfully created.

Plan Details:
Plan Type: {{plan_name}}
Total Amount: {{currency}}{{total_amount}}
Number of Installments: {{installments}}
First Payment Due: {{first_due_date}}
Installment Amount: {{currency}}{{installment_amount}}

Payment Schedule:
{{payment_schedule}}

Please ensure timely payments to avoid late fees.

Best regards,
University Finance Office','email',1,'2025-12-12T11:32:53.462595','2025-12-12T11:32:53.462595');
INSERT INTO "notification_templates" VALUES(9,'Installment Due Reminder','installment_reminder','Payment Plan Installment Due - {{amount}} due {{due_date}}','Dear {{student_name}},

This is a reminder that your payment plan installment is due soon.

Installment Details:
Plan: {{plan_name}}
Installment #: {{installment_number}} of {{total_installments}}
Amount Due: {{currency}}{{amount}}
Due Date: {{due_date}}

Remaining Balance: {{currency}}{{remaining_balance}}

Please ensure your payment is submitted on time.

Best regards,
University Finance Office','email',1,'2025-12-12T11:32:53.462595','2025-12-12T11:32:53.462595');
INSERT INTO "notification_templates" VALUES(10,'Scholarship Award Notification','scholarship_award','Congratulations! Scholarship Award - {{scholarship_name}}','Dear {{student_name}},

Congratulations! We are pleased to inform you that you have been awarded the {{scholarship_name}}.

Award Details:
Scholarship: {{scholarship_name}}
Amount: {{currency}}{{amount}}
Academic Year: {{academic_year}}

This award will be applied to your student account.

If you have any questions, please contact the Financial Aid Office.

Best regards,
University Financial Aid Office','email',1,'2025-12-12T11:32:53.462595','2025-12-12T11:32:53.462595');
INSERT INTO "notification_templates" VALUES(11,'Financial Aid Disbursement','aid_disbursement','Financial Aid Disbursement Notification','Dear {{student_name}},

Your financial aid has been disbursed to your student account.

Disbursement Details:
Aid Type: {{aid_type}}
Amount Disbursed: {{currency}}{{amount}}
Disbursement Date: {{disbursement_date}}

Your updated account balance is: {{currency}}{{account_balance}}

If you have any questions about your financial aid, please contact the Financial Aid Office.

Best regards,
University Financial Aid Office','email',1,'2025-12-12T11:32:53.462595','2025-12-12T11:32:53.462595');
INSERT INTO "notification_templates" VALUES(12,'Refund Processed','refund_processed','Refund Processed - {{currency}}{{amount}}','Dear {{student_name}},

Your refund request has been processed.

Refund Details:
Refund Amount: {{currency}}{{amount}}
Refund Method: {{refund_method}}
Reference Number: {{reference_number}}
Processed Date: {{processed_date}}

Please allow 5-7 business days for the refund to appear in your account.

If you have any questions, please contact the Finance Office.

Best regards,
University Finance Office','email',1,'2025-12-12T11:32:53.462595','2025-12-12T11:32:53.462595');
INSERT INTO "notification_templates" VALUES(13,'Account Hold Notice','account_hold','IMPORTANT: Financial Hold Placed on Your Account','Dear {{student_name}},

A financial hold has been placed on your student account due to an outstanding balance.

Outstanding Balance: {{currency}}{{amount}}
Hold Effective Date: {{hold_date}}

This hold may affect your ability to:
- Register for classes
- Access transcripts
- Receive your diploma

Please contact the Finance Office immediately to resolve this matter.

Best regards,
University Finance Office','email',1,'2025-12-12T11:32:53.462595','2025-12-12T11:32:53.462595');
INSERT INTO "notification_templates" VALUES(14,'SMS Payment Reminder','payment_reminder','Payment Reminder','University Finance: Payment of {{currency}}{{amount}} due {{due_date}}. Log in to portal to pay. Questions? Contact finance@university.edu','sms',1,'2025-12-12T11:32:53.462595','2025-12-12T11:32:53.462595');
CREATE TABLE notifications (
