CREATE TABLE organizations (
            org_id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            domain TEXT,
            contact_email TEXT,
            phone TEXT,
            address TEXT,
            is_active BOOLEAN DEFAULT 1,
            created_at TEXT,
            updated_at TEXT
        );
CREATE TABLE outcome_alignments (
                    alignment_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    programme_outcome_id INTEGER NOT NULL,
                    module_outcome_id INTEGER NOT NULL,
                    alignment_strength TEXT DEFAULT 'moderate',
                    notes TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (programme_outcome_id) REFERENCES learning_outcomes(outcome_id),
                    FOREIGN KEY (module_outcome_id) REFERENCES learning_outcomes(outcome_id)
                );
CREATE TABLE outcome_results (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            outcome_id INTEGER NOT NULL,
            achievement_level REAL,
            assessment_date TEXT,
            evidence TEXT,
            FOREIGN KEY (student_id) REFERENCES students(student_id),
            FOREIGN KEY (outcome_id) REFERENCES learning_outcomes(outcome_id)
        );
CREATE TABLE parent_accounts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            parent_id TEXT UNIQUE,
            first_name TEXT,
            last_name TEXT,
            email TEXT UNIQUE,
            phone TEXT,
            address TEXT,
            emergency_contact BOOLEAN DEFAULT 0,
            registration_date TEXT,
            two_factor_enabled BOOLEAN DEFAULT 0,
            two_factor_secret TEXT,
            profile_photo TEXT
        );
CREATE TABLE parent_activity_log (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                parent_id TEXT,
                action TEXT,
                details TEXT,
                ip_address TEXT,
                user_agent TEXT,
                timestamp TEXT,
                FOREIGN KEY (parent_id) REFERENCES parent_accounts (parent_id)
            );
CREATE TABLE parent_communications (
    comm_id INTEGER PRIMARY KEY AUTOINCREMENT,
    parent_id INTEGER NOT NULL,
    staff_id INTEGER,
    student_id INTEGER,
    subject TEXT,
    message TEXT NOT NULL,
    timestamp TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    is_read BOOLEAN DEFAULT 0,
    FOREIGN KEY (parent_id) REFERENCES parent_accounts(parent_id)
);
CREATE TABLE parent_conference_requests (
    request_id INTEGER PRIMARY KEY AUTOINCREMENT,
    parent_id INTEGER NOT NULL,
    teacher_id INTEGER NOT NULL,
    student_id INTEGER NOT NULL,
    preferred_times TEXT,  -- JSON array
    reason TEXT,
    status TEXT DEFAULT 'pending',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (parent_id) REFERENCES parent_accounts(parent_id)
);
CREATE TABLE parent_conferences (
    conference_id INTEGER PRIMARY KEY AUTOINCREMENT,
    parent_id INTEGER NOT NULL,
    teacher_id INTEGER NOT NULL,
    student_id INTEGER,
    datetime TIMESTAMP NOT NULL,
    location TEXT,
    meeting_type TEXT DEFAULT 'in_person',  -- in_person, virtual, phone
    meeting_link TEXT,
    status TEXT DEFAULT 'scheduled',
    notes TEXT,
    FOREIGN KEY (parent_id) REFERENCES parent_accounts(parent_id)
);
CREATE TABLE parent_contacts (
                            id INTEGER PRIMARY KEY AUTOINCREMENT,
                            student_id TEXT NOT NULL,
                            parent_name TEXT NOT NULL,
                            relationship TEXT,
                            email TEXT,
                            phone TEXT,
                            preferred_contact TEXT DEFAULT 'email',
                            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                            FOREIGN KEY (student_id) REFERENCES students (student_id)
                        );
CREATE TABLE parent_document_access (
    access_id INTEGER PRIMARY KEY AUTOINCREMENT,
    parent_id INTEGER NOT NULL,
    student_id INTEGER NOT NULL,
    document_id INTEGER,
    document_type TEXT,
    accessed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (parent_id) REFERENCES parent_accounts(parent_id),
    FOREIGN KEY (student_id) REFERENCES students(student_id)
);
CREATE TABLE parent_documents (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                parent_id TEXT,
                student_id TEXT,
                document_type TEXT,
                document_name TEXT,
                file_path TEXT,
                upload_date TEXT,
                status TEXT DEFAULT 'pending',
                expiry_date TEXT,
                FOREIGN KEY (parent_id) REFERENCES parent_accounts (parent_id),
                FOREIGN KEY (student_id) REFERENCES students (student_id)
            );
CREATE TABLE parent_messages (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                parent_id TEXT,
                teacher_id INTEGER,
                student_id TEXT,
                message_content TEXT,
                created_date TEXT,
                is_read BOOLEAN DEFAULT 0,
                is_from_parent BOOLEAN DEFAULT 1,
                message_type TEXT DEFAULT 'individual',
                group_id TEXT,
                FOREIGN KEY (parent_id) REFERENCES parent_accounts (parent_id),
                FOREIGN KEY (teacher_id) REFERENCES users (id),
                FOREIGN KEY (student_id) REFERENCES students (student_id)
            );
CREATE TABLE parent_notifications (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                parent_id TEXT,
                student_id TEXT,
                notification_type TEXT,
                notification_content TEXT,
                created_date TEXT,
                read_status BOOLEAN DEFAULT 0,
                FOREIGN KEY (parent_id) REFERENCES parent_accounts (parent_id),
                FOREIGN KEY (student_id) REFERENCES students (student_id)
            );
CREATE TABLE parent_permissions (
    permission_id INTEGER PRIMARY KEY AUTOINCREMENT,
    link_id INTEGER NOT NULL,
    permission_type TEXT NOT NULL,  -- view_grades, view_attendance, view_financial
    granted BOOLEAN DEFAULT 1,
    FOREIGN KEY (link_id) REFERENCES parent_student_links(link_id),
    UNIQUE(link_id, permission_type)
);
CREATE TABLE parent_portal_activity (
    activity_id INTEGER PRIMARY KEY AUTOINCREMENT,
    parent_id INTEGER NOT NULL,
    action_type TEXT NOT NULL,
    details TEXT,
    timestamp TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    ip_address TEXT,
    FOREIGN KEY (parent_id) REFERENCES parent_accounts(parent_id)
);
CREATE TABLE parent_preferences (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            parent_id TEXT UNIQUE,
            email_notifications BOOLEAN DEFAULT 1,
            sms_notifications BOOLEAN DEFAULT 0,
            grade_alerts BOOLEAN DEFAULT 1,
            attendance_alerts BOOLEAN DEFAULT 1,
            behavior_alerts BOOLEAN DEFAULT 1,
            assignment_alerts BOOLEAN DEFAULT 0,
            weekly_summary BOOLEAN DEFAULT 1,
            notification_timing TEXT DEFAULT '08:00',
            quiet_hours_start TEXT DEFAULT '20:00',
            quiet_hours_end TEXT DEFAULT '07:00',
            FOREIGN KEY (parent_id) REFERENCES parent_accounts (parent_id)
        );
CREATE TABLE parent_student_links (
    link_id INTEGER PRIMARY KEY AUTOINCREMENT,
    parent_id INTEGER NOT NULL,
    student_id INTEGER NOT NULL,
    relationship TEXT NOT NULL,  -- parent, guardian, other
    permissions TEXT,  -- JSON
    is_primary BOOLEAN DEFAULT 0,
    verified BOOLEAN DEFAULT 0,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (parent_id) REFERENCES parent_accounts(parent_id),
    FOREIGN KEY (student_id) REFERENCES students(student_id),
    UNIQUE(parent_id, student_id)
);
CREATE TABLE parent_student_relationships (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            parent_id TEXT,
            student_id TEXT,
            relationship_type TEXT,
            access_level TEXT DEFAULT 'full',
            date_added TEXT,
            FOREIGN KEY (parent_id) REFERENCES parent_accounts (parent_id),
            FOREIGN KEY (student_id) REFERENCES students (student_id)
        );
CREATE TABLE parent_teacher_meetings (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                parent_id TEXT,
                teacher_id INTEGER,
                student_id TEXT,
                meeting_date TEXT,
                start_time TEXT,
                end_time TEXT,
                location TEXT,
                meeting_type TEXT,
                status TEXT DEFAULT 'scheduled',
                agenda TEXT,
                notes TEXT,
                FOREIGN KEY (parent_id) REFERENCES parent_accounts (parent_id),
                FOREIGN KEY (teacher_id) REFERENCES users (id),
                FOREIGN KEY (student_id) REFERENCES students (student_id)
            );
CREATE TABLE parent_user_mapping (
