CREATE TABLE payment_plan_templates (
            template_id INTEGER PRIMARY KEY AUTOINCREMENT,
            template_name TEXT NOT NULL,
            description TEXT,
            number_of_installments INTEGER NOT NULL,
            installment_frequency TEXT NOT NULL, -- 'weekly', 'monthly', 'quarterly'
            setup_fee DECIMAL(10,2) DEFAULT 0,
            interest_rate DECIMAL(5,2) DEFAULT 0,
            early_payment_discount DECIMAL(5,2) DEFAULT 0,
            late_payment_penalty DECIMAL(5,2) DEFAULT 0,
            is_active BOOLEAN DEFAULT 1,
            created_at TEXT,
            updated_at TEXT
        );
INSERT INTO "payment_plan_templates" VALUES(5,'Standard Monthly Plan','Standard monthly payment plan with 10 installments over the academic year',10,'monthly',25,0,2,5,1,'2025-12-12T11:32:53.456346','2025-12-12T11:32:53.456346');
INSERT INTO "payment_plan_templates" VALUES(6,'Quarterly Payment Plan','Quarterly payment plan with 4 installments per academic year',4,'quarterly',0,0,3,5,1,'2025-12-12T11:32:53.456346','2025-12-12T11:32:53.456346');
INSERT INTO "payment_plan_templates" VALUES(7,'Semester Plan','Two equal payments at the start of each semester',2,'quarterly',0,0,5,10,1,'2025-12-12T11:32:53.456346','2025-12-12T11:32:53.456346');
INSERT INTO "payment_plan_templates" VALUES(8,'Weekly Instalment Plan','Weekly payment plan for students requiring smaller, frequent payments',40,'weekly',50,1.5,0,2.5,1,'2025-12-12T11:32:53.456346','2025-12-12T11:32:53.456346');
INSERT INTO "payment_plan_templates" VALUES(9,'Emergency Extended Plan','Extended 12-month plan for students facing financial hardship',12,'monthly',0,0,0,0,1,'2025-12-12T11:32:53.456346','2025-12-12T11:32:53.456346');
CREATE TABLE payment_risk_scores (
            score_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            risk_score DECIMAL(5,2) NOT NULL, -- 0-100
            risk_level TEXT NOT NULL, -- 'low', 'medium', 'high'
            factors TEXT, -- JSON with risk factors
            last_calculated TEXT,
            created_at TEXT,
            FOREIGN KEY (student_id) REFERENCES students (student_id)
        );
CREATE TABLE payment_schedules (
    schedule_id INTEGER PRIMARY KEY AUTOINCREMENT,
    award_id INTEGER,
    component_id INTEGER,
    student_id INTEGER NOT NULL,
    total_amount REAL NOT NULL,
    payment_date DATE NOT NULL,
    amount REAL NOT NULL,
    academic_term TEXT,
    status TEXT DEFAULT 'scheduled',  -- scheduled, paid, cancelled
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (award_id) REFERENCES scholarship_awards(award_id),
    FOREIGN KEY (component_id) REFERENCES aid_components(component_id),
    FOREIGN KEY (student_id) REFERENCES students(student_id)
);
CREATE TABLE payments (
    payment_id INTEGER PRIMARY KEY AUTOINCREMENT,
    student_id TEXT NOT NULL,
    amount DECIMAL(10,2) NOT NULL,
    currency TEXT DEFAULT 'GBP',
    payment_method TEXT,
    gateway_transaction_id TEXT,
    gateway_name TEXT,
    transaction_id TEXT,
    payment_date TEXT,
    status TEXT DEFAULT 'completed',
    notes TEXT,
    created_by TEXT,
    created_at TEXT,
    fraud_score DECIMAL(3,2),
    is_suspicious BOOLEAN DEFAULT 0
);
