CREATE TABLE payroll_allowances (
                    allowance_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT NOT NULL,
                    allowance_type TEXT NOT NULL,
                    amount REAL NOT NULL,
                    frequency TEXT DEFAULT 'monthly',
                    start_date TEXT NOT NULL,
                    end_date TEXT,
                    is_active INTEGER DEFAULT 1,
                    approved_by TEXT,
                    notes TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE payroll_overtime (
                    overtime_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT NOT NULL,
                    date TEXT NOT NULL,
                    hours REAL NOT NULL,
                    rate_multiplier REAL DEFAULT 1.5,
                    reason TEXT,
                    status TEXT DEFAULT 'pending',
                    approved_by TEXT,
                    approved_date TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE payroll_periods (
                    period_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL,
                    period_type TEXT NOT NULL DEFAULT 'monthly',
                    start_date TEXT NOT NULL,
                    end_date TEXT NOT NULL,
                    payment_date TEXT,
                    status TEXT DEFAULT 'draft',
                    created_by TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE payroll_records (
                    record_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    period_id INTEGER NOT NULL,
                    user_id TEXT NOT NULL,
                    contract_id INTEGER,
                    basic_salary REAL DEFAULT 0,
                    overtime_pay REAL DEFAULT 0,
                    allowances_total REAL DEFAULT 0,
                    gross_pay REAL DEFAULT 0,
                    tax_deduction REAL DEFAULT 0,
                    ni_deduction REAL DEFAULT 0,
                    pension_deduction REAL DEFAULT 0,
                    student_loan_deduction REAL DEFAULT 0,
                    other_deductions REAL DEFAULT 0,
                    net_pay REAL DEFAULT 0,
                    payment_status TEXT DEFAULT 'pending',
                    payment_reference TEXT,
                    notes TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (period_id) REFERENCES payroll_periods(period_id)
                );
CREATE TABLE peer_observations (
                observation_id INTEGER PRIMARY KEY AUTOINCREMENT,
                observer_id TEXT NOT NULL,
                observer_name TEXT,
                observee_id TEXT NOT NULL,
                observee_name TEXT,
                course_code TEXT,
                course_name TEXT,
                observation_date TEXT,
                observation_type TEXT DEFAULT 'peer',
                class_size INTEGER,
                duration_minutes INTEGER,
                strengths TEXT,
                areas_for_development TEXT,
                action_points TEXT,
                overall_rating INTEGER,
                status TEXT DEFAULT 'draft',
                acknowledged_date TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE peer_review_assignments (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            assignment_id TEXT UNIQUE NOT NULL,
            session_id TEXT NOT NULL,
            reviewer_id TEXT NOT NULL,
            reviewee_id TEXT NOT NULL,
            submission_id INTEGER,
            due_date TIMESTAMP,
            status TEXT DEFAULT 'pending',
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (reviewer_id) REFERENCES students (student_id),
            FOREIGN KEY (reviewee_id) REFERENCES students (student_id),
            FOREIGN KEY (submission_id) REFERENCES assignment_submissions (id)
        );
CREATE TABLE peer_review_criteria (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            review_id INTEGER NOT NULL,
            criteria_name TEXT NOT NULL,
            score INTEGER NOT NULL,
            comment TEXT,
            FOREIGN KEY (review_id) REFERENCES peer_reviews (id)
        );
CREATE TABLE peer_review_cycles (
                    cycle_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL,
                    description TEXT,
                    cycle_type TEXT DEFAULT 'teaching_materials',
                    department TEXT,
                    start_date TEXT,
                    end_date TEXT,
                    status TEXT DEFAULT 'draft',
                    created_by TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE peer_review_feedback (
                    feedback_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    assignment_id INTEGER NOT NULL,
                    submission_id INTEGER NOT NULL,
                    reviewer_id TEXT NOT NULL,
                    overall_rating INTEGER,
                    content_quality INTEGER,
                    clarity INTEGER,
                    alignment_with_outcomes INTEGER,
                    engagement_potential INTEGER,
                    strengths TEXT,
                    improvements TEXT,
                    detailed_comments TEXT,
                    recommendation TEXT DEFAULT 'approve',
                    is_confidential INTEGER DEFAULT 0,
                    submitted_date TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (assignment_id) REFERENCES peer_review_assignments(assignment_id),
                    FOREIGN KEY (submission_id) REFERENCES peer_review_submissions(submission_id)
                );
CREATE TABLE peer_review_resource_ratings (
                    rating_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    resource_id INTEGER NOT NULL,
                    user_id TEXT NOT NULL,
                    rating INTEGER NOT NULL,
                    comment TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (resource_id) REFERENCES peer_review_shared_resources(resource_id),
                    UNIQUE(resource_id, user_id)
                );
CREATE TABLE peer_review_shared_resources (
                    resource_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    title TEXT NOT NULL,
                    description TEXT,
                    resource_type TEXT DEFAULT 'template',
                    subject_area TEXT,
                    course_code TEXT,
                    file_path TEXT,
                    file_name TEXT,
                    shared_by TEXT NOT NULL,
                    download_count INTEGER DEFAULT 0,
                    rating_sum INTEGER DEFAULT 0,
                    rating_count INTEGER DEFAULT 0,
                    is_approved INTEGER DEFAULT 0,
                    status TEXT DEFAULT 'active',
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE peer_review_submissions (
                    submission_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    cycle_id INTEGER NOT NULL,
                    submitter_id TEXT NOT NULL,
                    title TEXT NOT NULL,
                    description TEXT,
                    material_type TEXT DEFAULT 'other',
                    course_code TEXT,
                    file_path TEXT,
                    file_name TEXT,
                    version INTEGER DEFAULT 1,
                    parent_submission_id INTEGER,
                    status TEXT DEFAULT 'draft',
                    submitted_date TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (cycle_id) REFERENCES peer_review_cycles(cycle_id),
                    FOREIGN KEY (parent_submission_id) REFERENCES peer_review_submissions(submission_id)
                );
CREATE TABLE peer_reviews (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    assignment_id INTEGER NOT NULL,
    reviewer_id INTEGER NOT NULL,
    reviewee_submission_id INTEGER NOT NULL,
    score REAL,
    feedback TEXT,
    rubric_scores TEXT,
    status TEXT DEFAULT 'pending',
    submitted_at TIMESTAMP,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, reviewee_id TEXT,
    FOREIGN KEY (assignment_id) REFERENCES assignments (id),
    FOREIGN KEY (reviewer_id) REFERENCES users (id),
    FOREIGN KEY (reviewee_submission_id) REFERENCES assignment_submissions (id)
);
CREATE TABLE peer_support_groups (
            group_id INTEGER PRIMARY KEY AUTOINCREMENT,
            group_name TEXT,
            description TEXT,
            support_type TEXT,
            facilitator_id TEXT,
            max_members INTEGER,
            current_members INTEGER DEFAULT 0,
            meeting_schedule TEXT,
            status TEXT DEFAULT 'active',
            created_date TEXT,
            FOREIGN KEY (facilitator_id) REFERENCES students (student_id)
        );
CREATE TABLE performance_trends (
            trend_id INTEGER PRIMARY KEY AUTOINCREMENT,
            metric_name TEXT NOT NULL,
            metric_category TEXT NOT NULL,
            time_period TEXT NOT NULL,
            value REAL NOT NULL,
            change_from_previous REAL,
            trend_direction TEXT,
            recorded_date TEXT DEFAULT CURRENT_DATE
        );
CREATE TABLE permission_changes_log (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                changed_by INTEGER NOT NULL,
                target_user_id INTEGER NOT NULL,
                permission_name TEXT NOT NULL,
                action TEXT NOT NULL,
                reason TEXT,
                changed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (changed_by) REFERENCES users(id),
                FOREIGN KEY (target_user_id) REFERENCES users(id)
            );
CREATE TABLE permissions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            permission_name TEXT UNIQUE NOT NULL,
            description TEXT NOT NULL,
            created_at TEXT NOT NULL
        );
