CREATE TABLE phoneshop_warranties (
        warranty_id INTEGER PRIMARY KEY AUTOINCREMENT,
        order_item_id INTEGER NOT NULL,
        product_id INTEGER NOT NULL,
        serial_number TEXT,
        start_date TEXT NOT NULL,
        end_date TEXT NOT NULL,
        warranty_type TEXT DEFAULT 'standard',
        status TEXT DEFAULT 'active',
        customer_id TEXT NOT NULL,
        FOREIGN KEY (order_item_id) REFERENCES phoneshop_order_items(item_id),
        FOREIGN KEY (product_id) REFERENCES phoneshop_products(product_id)
    );
CREATE TABLE photo_gallery (
            photo_id INTEGER PRIMARY KEY AUTOINCREMENT,
            event_id INTEGER,
            uploaded_by TEXT,
            photo_path TEXT,
            caption TEXT,
            upload_date TEXT,
            is_featured BOOLEAN DEFAULT 0,
            FOREIGN KEY (event_id) REFERENCES alumni_events (event_id),
            FOREIGN KEY (uploaded_by) REFERENCES alumni (alumni_id)
        );
CREATE TABLE photo_permissions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                student_id TEXT,
                permission_type TEXT,
                consent_given BOOLEAN DEFAULT 0,
                conditions TEXT,
                valid_from TEXT,
                valid_until TEXT,
                parent_signature TEXT,
                date_signed TEXT,
                FOREIGN KEY (student_id) REFERENCES students (student_id)
            );
CREATE TABLE pickup_authorizations (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                student_id TEXT,
                authorized_person_name TEXT,
                relationship TEXT,
                phone_number TEXT,
                id_number TEXT,
                photo_path TEXT,
                valid_from TEXT,
                valid_until TEXT,
                active BOOLEAN DEFAULT 1,
                created_by TEXT,
                FOREIGN KEY (student_id) REFERENCES students (student_id)
            );
CREATE TABLE plagiarism_results (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    document_id INTEGER NOT NULL,
                    matched_document_id INTEGER,
                    similarity_score REAL NOT NULL CHECK(similarity_score >= 0 AND similarity_score <= 1),
                    check_date TEXT NOT NULL,
                    checked_by INTEGER,
                    status TEXT NOT NULL,
                    report TEXT,
                    threshold_used REAL DEFAULT 0.3,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (document_id) REFERENCES document_repository (id) ON DELETE CASCADE,
                    FOREIGN KEY (matched_document_id) REFERENCES document_repository (id) ON DELETE SET NULL,
                    FOREIGN KEY (checked_by) REFERENCES users (id) ON DELETE SET NULL
                );
CREATE TABLE plan_schedule_conflicts (
                    conflict_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    plan_id INTEGER NOT NULL,
                    conflict_type TEXT NOT NULL,
                    severity TEXT NOT NULL,
                    description TEXT NOT NULL,
                    affected_courses_json TEXT,
                    affected_semester INTEGER,
                    resolution_suggestions_json TEXT,
                    is_resolved BOOLEAN DEFAULT 0,
                    detected_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (plan_id) REFERENCES semester_plans(plan_id) ON DELETE CASCADE
                );
CREATE TABLE planned_courses (
                    planned_course_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    plan_id INTEGER NOT NULL,
                    course_id TEXT NOT NULL,
                    semester_number INTEGER NOT NULL,
                    semester_name TEXT NOT NULL,
                    is_locked BOOLEAN DEFAULT 0,
                    priority INTEGER DEFAULT 0,
                    notes TEXT,
                    added_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (plan_id) REFERENCES semester_plans(plan_id) ON DELETE CASCADE,
                    FOREIGN KEY (course_id) REFERENCES courses(code),
                    UNIQUE(plan_id, course_id)
                );
