CREATE TABLE police_cases (
    id TEXT PRIMARY KEY,
    title TEXT,
    type TEXT,
    status TEXT DEFAULT 'Open',
    priority TEXT DEFAULT 'Medium',
    officer TEXT,
    location TEXT,
    description TEXT,
    notes TEXT,
    witnesses TEXT,
    date TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE police_complaints (
    id TEXT PRIMARY KEY,
    complainant TEXT,
    email TEXT,
    phone TEXT,
    type TEXT,
    priority TEXT DEFAULT 'Medium',
    status TEXT DEFAULT 'Pending',
    incident_date TEXT,
    incident_time TEXT,
    location TEXT,
    description TEXT,
    suspect_description TEXT,
    date TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE police_criminals (
    id TEXT PRIMARY KEY,
    name TEXT,
    crime TEXT,
    status TEXT,
    arrest_date TEXT,
    case_number TEXT,
    description TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE police_emergency_alerts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    type TEXT,
    location TEXT,
    details TEXT,
    reporter TEXT,
    timestamp TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE police_evidence (
    id TEXT PRIMARY KEY,
    description TEXT,
    case_number TEXT,
    type TEXT,
    location TEXT,
    custody TEXT,
    date_added TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
