CREATE TABLE police_officers (
    badge TEXT PRIMARY KEY,
    name TEXT,
    rank TEXT,
    department TEXT,
    status TEXT DEFAULT 'Active',
    phone TEXT,
    email TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE police_patrol_logs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    officer TEXT,
    area TEXT,
    start_time TEXT,
    end_time TEXT,
    status TEXT,
    notes TEXT,
    date TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE poll_options (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            poll_id INTEGER NOT NULL,
            option_text TEXT NOT NULL,
            movie_id INTEGER,
            votes INTEGER DEFAULT 0,
            FOREIGN KEY (poll_id) REFERENCES polls(id),
            FOREIGN KEY (movie_id) REFERENCES movies(id)
        );
CREATE TABLE poll_responses (
    response_id INTEGER PRIMARY KEY AUTOINCREMENT,
    poll_id INTEGER NOT NULL,
    user_id INTEGER NOT NULL,
    answer TEXT NOT NULL,
    is_correct BOOLEAN,
    response_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    time_taken INTEGER,  -- seconds
    FOREIGN KEY (poll_id) REFERENCES virtual_polls(poll_id) ON DELETE CASCADE,
    UNIQUE(poll_id, user_id)
);
CREATE TABLE poll_votes (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            poll_id INTEGER NOT NULL,
            option_id INTEGER NOT NULL,
            member_id INTEGER,
            customer_email TEXT,
            voted_at TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (poll_id) REFERENCES polls(id),
            FOREIGN KEY (option_id) REFERENCES poll_options(id),
            FOREIGN KEY (member_id) REFERENCES members(id)
        );
CREATE TABLE polls (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            description TEXT,
            poll_type TEXT DEFAULT 'movie_choice',
            start_date TEXT NOT NULL,
            end_date TEXT NOT NULL,
            max_votes_per_user INTEGER DEFAULT 1,
            status TEXT DEFAULT 'active',
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE pomodoro_sessions (
                    session_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    room_id INTEGER NOT NULL,
                    student_id TEXT NOT NULL,
                    session_type TEXT NOT NULL,
                    start_time TEXT NOT NULL,
                    end_time TEXT,
                    duration_minutes INTEGER,
                    completed BOOLEAN DEFAULT 0,
                    FOREIGN KEY (room_id) REFERENCES virtual_study_rooms(room_id) ON DELETE CASCADE
                );
