CREATE TABLE portfolio_items (
                    item_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    portfolio_id INTEGER NOT NULL,
                    category TEXT NOT NULL CHECK(category IN (
                        'project', 'research', 'leadership', 'work_experience',
                        'award', 'certification', 'publication', 'presentation'
                    )),
                    title TEXT NOT NULL,
                    description TEXT,
                    organization TEXT,
                    role TEXT,
                    start_date DATE,
                    end_date DATE,
                    is_current BOOLEAN DEFAULT 0,
                    technologies TEXT,
                    achievements TEXT,
                    url TEXT,
                    attachments TEXT,
                    display_order INTEGER DEFAULT 0,
                    is_featured BOOLEAN DEFAULT 0,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (portfolio_id) REFERENCES portfolios(portfolio_id) ON DELETE CASCADE
                );
CREATE TABLE portfolios (
                    portfolio_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL,
                    title TEXT NOT NULL,
                    bio TEXT,
                    headline TEXT,
                    profile_image_url TEXT,
                    is_public BOOLEAN DEFAULT 0,
                    public_url TEXT UNIQUE,
                    linkedin_url TEXT,
                    github_url TEXT,
                    personal_website TEXT,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (student_id) REFERENCES students(student_id)
                );
CREATE TABLE prediction_bets (
                    bet_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT NOT NULL,
                    market_id INTEGER NOT NULL,
                    selection TEXT NOT NULL,
                    stake DECIMAL(10,2) NOT NULL,
                    odds_at_placement DECIMAL(6,2) NOT NULL,
                    potential_return DECIMAL(10,2) NOT NULL,
                    actual_return DECIMAL(10,2) DEFAULT 0.00,
                    status TEXT DEFAULT 'pending',
                    placed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    settled_at TIMESTAMP,
                    FOREIGN KEY (market_id) REFERENCES prediction_markets(market_id)
                );
CREATE TABLE prediction_markets (
                    market_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    title TEXT NOT NULL,
                    description TEXT,
                    category TEXT NOT NULL,
                    outcome_a TEXT NOT NULL,
                    outcome_b TEXT NOT NULL,
                    probability_a DECIMAL(5,2) DEFAULT 50.00,
                    probability_b DECIMAL(5,2) DEFAULT 50.00,
                    total_pool DECIMAL(10,2) DEFAULT 0.00,
                    pool_a DECIMAL(10,2) DEFAULT 0.00,
                    pool_b DECIMAL(10,2) DEFAULT 0.00,
                    resolution_date TEXT NOT NULL,
                    status TEXT DEFAULT 'open',
                    result TEXT,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    created_by TEXT
                );
CREATE TABLE prerequisite_graph_cache (
                    cache_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    course_id TEXT NOT NULL UNIQUE,
                    all_prerequisites_json TEXT NOT NULL,
                    depth_level INTEGER DEFAULT 0,
                    last_updated TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (course_id) REFERENCES courses(code)
                );
