INSERT INTO "restaurant_orders" VALUES(1,NULL,'2026-01-24 18:28:35',7.14000000000000056843e+00,1.19000000000000016875e+00,'Refunded','Student Account');
CREATE TABLE restaurant_staff (
                staff_id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                role TEXT NOT NULL,
                hourly_rate REAL,
                status TEXT DEFAULT 'Active',
                performance_score REAL
            );
CREATE TABLE restaurant_tables (
                table_id INTEGER PRIMARY KEY AUTOINCREMENT,
                capacity INTEGER NOT NULL,
                status TEXT DEFAULT 'Available',
                location TEXT,
                table_type TEXT DEFAULT 'Standard'
            );
CREATE TABLE restaurant_waste (
                waste_id INTEGER PRIMARY KEY AUTOINCREMENT,
                waste_date DATE NOT NULL,
                item_name TEXT NOT NULL,
                quantity REAL NOT NULL,
                unit_of_measure TEXT,
                cost_value REAL NOT NULL,
                waste_type TEXT,
                reason TEXT NOT NULL,
                responsible_staff TEXT,
                notes TEXT,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE restaurant_waste_categories (
                category_id INTEGER PRIMARY KEY AUTOINCREMENT,
                category_name TEXT UNIQUE NOT NULL,
                description TEXT,
                target_percentage REAL,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP
            );
INSERT INTO "restaurant_waste_categories" VALUES(1,'Spoilage','Food spoiled before use',5.0,'2026-01-25 14:37:33');
INSERT INTO "restaurant_waste_categories" VALUES(2,'Preparation Waste','Trimmings and preparation waste',10.0,'2026-01-25 14:37:33');
INSERT INTO "restaurant_waste_categories" VALUES(3,'Over-production','Food prepared but not sold',3.0,'2026-01-25 14:37:33');
INSERT INTO "restaurant_waste_categories" VALUES(4,'Plate Waste','Food returned by customers',2.0,'2026-01-25 14:37:33');
INSERT INTO "restaurant_waste_categories" VALUES(5,'Storage Issues','Improper storage leading to waste',1.0,'2026-01-25 14:37:33');
INSERT INTO "restaurant_waste_categories" VALUES(6,'Other','Miscellaneous waste',2.0,'2026-01-25 14:37:33');
CREATE TABLE resume_templates (
                    template_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    template_name TEXT NOT NULL,
                    template_type TEXT CHECK(template_type IN (
                        'traditional', 'modern', 'creative', 'technical', 'academic'
                    )),
                    template_data TEXT NOT NULL,
                    is_default BOOLEAN DEFAULT 0,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE retention_predictions (
            prediction_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            model_id INTEGER NOT NULL,
            retention_probability REAL NOT NULL,
            risk_level TEXT NOT NULL,
            prediction_date TEXT DEFAULT CURRENT_TIMESTAMP,
            prediction_year INTEGER,
            factors TEXT,
            recommendations TEXT,
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (model_id) REFERENCES analytics_models (model_id)
        );
CREATE TABLE reviews (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            movie_id INTEGER NOT NULL,
            member_id INTEGER,
            customer_name TEXT,
            rating INTEGER NOT NULL CHECK(rating >= 1 AND rating <= 5),
            review_text TEXT,
            helpful_count INTEGER DEFAULT 0,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            status TEXT DEFAULT 'active',
            FOREIGN KEY (movie_id) REFERENCES movies(id),
            FOREIGN KEY (member_id) REFERENCES members(id)
        );
CREATE TABLE revoked_credentials (
    revocation_id INTEGER PRIMARY KEY AUTOINCREMENT,
    credential_id INTEGER,
    badge_issuance_id INTEGER,
    revoked_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    reason TEXT NOT NULL,
    revoked_by INTEGER,
    blockchain_revocation_hash TEXT,
    FOREIGN KEY (credential_id) REFERENCES blockchain_credentials(credential_id),
    FOREIGN KEY (badge_issuance_id) REFERENCES badge_issuances(issuance_id)
);
CREATE TABLE rideshare_posts (
                post_id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                post_type TEXT NOT NULL,
                departure_location TEXT NOT NULL,
                destination TEXT NOT NULL,
                departure_time TIMESTAMP NOT NULL,
                seats_available INTEGER,
                price_per_seat REAL,
                notes TEXT,
                status TEXT DEFAULT 'active',
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (user_id) REFERENCES users(id)
            );
CREATE TABLE risk_assessments (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT,
                    assessment_type TEXT,
                    risk_score INTEGER,
                    risk_factors TEXT,
                    recommendations TEXT,
                    assessed_date TEXT,
                    assessed_by TEXT,
                    follow_up_date TEXT,
                    created_at TEXT,
                    FOREIGN KEY (student_id) REFERENCES students (student_id)
                );
CREATE TABLE risk_details (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            risk_factor_id INTEGER,
            detail TEXT,
            weight REAL,
            created_at TEXT,
            FOREIGN KEY (risk_factor_id) REFERENCES risk_factors (id)
        );
CREATE TABLE risk_factors (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT,
            factor_name TEXT,
            factor_value REAL,
            assessment_id INTEGER,
            date_calculated TEXT,
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (assessment_id) REFERENCES assessments (assessment_id)
        );
CREATE TABLE role_permissions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            role_id INTEGER NOT NULL,
            permission_id INTEGER NOT NULL,
            FOREIGN KEY (role_id) REFERENCES roles (id),
            FOREIGN KEY (permission_id) REFERENCES permissions (id),
            UNIQUE(role_id, permission_id)
        );
