CREATE TABLE school_announcements (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                title TEXT,
                content TEXT,
                priority TEXT DEFAULT 'normal',
                category TEXT,
                audience TEXT,
                created_by INTEGER,
                created_date TEXT,
                expiry_date TEXT,
                requires_acknowledgment BOOLEAN DEFAULT 0,
                FOREIGN KEY (created_by) REFERENCES users (id)
            );
CREATE TABLE school_calendar (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                event_name TEXT,
                event_description TEXT,
                event_date TEXT,
                start_time TEXT,
                end_time TEXT,
                location TEXT,
                event_type TEXT,
                audience TEXT
            );
CREATE TABLE screen_layouts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            screen_number INTEGER UNIQUE NOT NULL,
            name TEXT,
            rows INTEGER NOT NULL DEFAULT 8,
            seats_per_row INTEGER NOT NULL DEFAULT 12,
            vip_rows TEXT,
            wheelchair_positions TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            updated_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE screen_maintenance (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            screen_number INTEGER NOT NULL,
            maintenance_type TEXT NOT NULL,
            description TEXT,
            start_datetime TEXT NOT NULL,
            end_datetime TEXT,
            technician TEXT,
            cost REAL,
            status TEXT DEFAULT 'scheduled',
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
