CREATE TABLE search_presets (
                    id TEXT PRIMARY KEY,
                    name TEXT NOT NULL,
                    user_id TEXT NOT NULL,
                    filters TEXT NOT NULL,
                    date_added TEXT NOT NULL,
                    is_active BOOLEAN DEFAULT TRUE
                );
CREATE TABLE search_profiles (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                description TEXT,
                criteria TEXT,
                created_date DATETIME DEFAULT CURRENT_TIMESTAMP,
                created_by TEXT,
                is_shared BOOLEAN DEFAULT FALSE
            );
CREATE TABLE search_result_archives (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id TEXT,
                saved_at DATETIME DEFAULT CURRENT_TIMESTAMP,
                search_name TEXT,
                search_criteria TEXT,
                results_json TEXT
            );
CREATE TABLE season_passes (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            pass_code TEXT UNIQUE NOT NULL,
            member_id INTEGER,
            customer_name TEXT NOT NULL,
            customer_email TEXT NOT NULL,
            pass_type TEXT NOT NULL,
            purchase_date TEXT DEFAULT CURRENT_TIMESTAMP,
            start_date TEXT NOT NULL,
            end_date TEXT NOT NULL,
            movies_used INTEGER DEFAULT 0,
            status TEXT DEFAULT 'active',
            FOREIGN KEY (member_id) REFERENCES members(id)
        );
CREATE TABLE seat_holds (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            seat_id INTEGER NOT NULL,
            session_id TEXT NOT NULL,
            held_at TEXT DEFAULT CURRENT_TIMESTAMP,
            expires_at TEXT NOT NULL,
            FOREIGN KEY (seat_id) REFERENCES seats(id)
        );
CREATE TABLE seats (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            screening_id INTEGER NOT NULL,
            row TEXT NOT NULL,
            seat_number INTEGER NOT NULL,
            seat_type TEXT DEFAULT 'standard',
            status TEXT DEFAULT 'available', is_wheelchair INTEGER DEFAULT 0, is_companion INTEGER DEFAULT 0, is_couple INTEGER DEFAULT 0,
            FOREIGN KEY (screening_id) REFERENCES screenings(id),
            UNIQUE(screening_id, row, seat_number)
        );
