CREATE TABLE security_desk_counter (
    id INTEGER PRIMARY KEY CHECK (id = 1),
    counter INTEGER DEFAULT 1000
);
INSERT INTO "security_desk_counter" VALUES(1,1001);
CREATE TABLE security_desk_tickets (
    id TEXT PRIMARY KEY,
    type TEXT,
    category TEXT,
    priority TEXT DEFAULT 'Normal',
    status TEXT DEFAULT 'Open',
    subject TEXT,
    description TEXT,
    location TEXT,
    user_id TEXT,
    user_name TEXT,
    user_email TEXT,
    admin_notes TEXT,
    created_at TEXT,
    updated_at TEXT
);
INSERT INTO "security_desk_tickets" VALUES('EMG-1000','EMERGENCY ALERT','Emergency','Critical','In Progress','EMERGENCY ALERT','Emergency alert triggered by user',NULL,'3','admin','',NULL,'2026-01-01 18:23:04','2026-01-01 18:23:04');
CREATE TABLE security_events (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER,
                event_type TEXT NOT NULL,
                severity TEXT DEFAULT 'medium',
                details TEXT,
                ip_address TEXT,
                event_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (user_id) REFERENCES users(id)
            );
