CREATE TABLE shared_resources (
            resource_id INTEGER PRIMARY KEY AUTOINCREMENT,
            uploader_id TEXT,
            resource_title TEXT,
            resource_type TEXT,
            subject TEXT,
            file_path TEXT,
            description TEXT,
            upload_date TEXT,
            downloads INTEGER DEFAULT 0,
            rating REAL DEFAULT 0.0,
            FOREIGN KEY (uploader_id) REFERENCES students (student_id)
        );
CREATE TABLE shift_swap_requests (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            requester_id INTEGER NOT NULL,
            original_shift_id INTEGER NOT NULL,
            requested_with_id INTEGER,
            target_shift_id INTEGER,
            reason TEXT,
            status TEXT DEFAULT 'pending',
            reviewed_by INTEGER,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            resolved_at TEXT,
            FOREIGN KEY (requester_id) REFERENCES staff(id),
            FOREIGN KEY (original_shift_id) REFERENCES shifts(id),
            FOREIGN KEY (requested_with_id) REFERENCES staff(id),
            FOREIGN KEY (target_shift_id) REFERENCES shifts(id),
            FOREIGN KEY (reviewed_by) REFERENCES staff(id)
        );
CREATE TABLE shifts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            staff_id INTEGER NOT NULL,
            shift_date TEXT NOT NULL,
            start_time TEXT NOT NULL,
            end_time TEXT NOT NULL,
            position TEXT DEFAULT 'general',
            screen_assigned INTEGER,
            break_start TEXT,
            break_end TEXT,
            status TEXT DEFAULT 'scheduled',
            notes TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (staff_id) REFERENCES staff(id)
        );
CREATE TABLE shop_cart (
            cart_id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            product_id TEXT NOT NULL,
            quantity INTEGER NOT NULL DEFAULT 1,
            added_at TEXT NOT NULL,
            FOREIGN KEY (user_id) REFERENCES users (id),
            FOREIGN KEY (product_id) REFERENCES shop_products (product_id),
            UNIQUE(user_id, product_id)
        );
CREATE TABLE shop_discounts (
            discount_id TEXT PRIMARY KEY,
            name TEXT NOT NULL,
            description TEXT,
            discount_type TEXT NOT NULL,
            discount_value REAL NOT NULL,
            start_date TEXT,
            end_date TEXT,
            is_active BOOLEAN DEFAULT 1,
            applicable_products TEXT,
            min_purchase_amount REAL DEFAULT 0,
            created_at TEXT NOT NULL
        );
