CREATE TABLE shuttle_buses (
    bus_id INTEGER PRIMARY KEY AUTOINCREMENT,
    route_id INTEGER,
    bus_number TEXT UNIQUE,
    capacity INTEGER DEFAULT 40,
    current_location TEXT,  -- lat,lon
    current_stop_id INTEGER,
    in_service BOOLEAN DEFAULT 1,
    last_updated TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (route_id) REFERENCES shuttle_routes(route_id)
);
CREATE TABLE shuttle_routes (
    route_id INTEGER PRIMARY KEY AUTOINCREMENT,
    route_name TEXT NOT NULL,
    description TEXT,
    schedule TEXT,  -- JSON
    stops TEXT,  -- JSON array
    is_active BOOLEAN DEFAULT 1
);
CREATE TABLE shuttle_stops (
    stop_id INTEGER PRIMARY KEY AUTOINCREMENT,
    stop_name TEXT NOT NULL,
    latitude REAL,
    longitude REAL,
    arrival_time TIME,
    amenities TEXT  -- JSON
);
CREATE TABLE skill_endorsements (
                    endorsement_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    skill_id INTEGER NOT NULL,
                    endorser_id TEXT NOT NULL,
                    endorser_role TEXT CHECK(endorser_role IN (
                        'faculty', 'peer', 'employer', 'mentor'
                    )),
                    comment TEXT,
                    relationship TEXT,
                    endorsed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (skill_id) REFERENCES student_skills(skill_id) ON DELETE CASCADE,
                    UNIQUE(skill_id, endorser_id)
                );
CREATE TABLE sla_policies (
            sla_id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            description TEXT,
            priority TEXT,
            impact TEXT,
            urgency TEXT,
            first_response_hours INTEGER,
            resolution_hours INTEGER,
            escalation_hours INTEGER,
            business_hours_only BOOLEAN DEFAULT 0,
            is_active BOOLEAN DEFAULT 1,
            created_at TEXT,
            updated_at TEXT
        );
CREATE TABLE sleep_tracking (
                    sleep_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL,
                    sleep_date TEXT NOT NULL,
                    bedtime TEXT,
                    wake_time TEXT,
                    hours_slept REAL,
                    sleep_quality INTEGER CHECK(sleep_quality BETWEEN 1 AND 5),
                    interruptions INTEGER DEFAULT 0,
                    notes TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (student_id) REFERENCES students(student_id)
                );
CREATE TABLE sms_messages (
                            id INTEGER PRIMARY KEY AUTOINCREMENT,
                            sender_username TEXT,
                            recipient_name TEXT,
                            phone_number TEXT,
                            message TEXT,
                            status TEXT,
                            sent_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                        );
CREATE TABLE snack_orders (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            order_ref TEXT UNIQUE NOT NULL,
            customer_name TEXT,
            customer_email TEXT,
            items TEXT NOT NULL,
            pickup_time TEXT,
            subtotal REAL NOT NULL,
            discount_amount REAL DEFAULT 0,
            total_amount REAL NOT NULL,
            payment_status TEXT DEFAULT 'pending',
            payment_method TEXT,
            order_status TEXT DEFAULT 'pending',
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        );
INSERT INTO "snack_orders" VALUES(1,'SNKOF8EQ23R','be',NULL,'Popcorn (Small)',NULL,4.99,0.0,4.99,'pending',NULL,'pending','2026-01-16 08:18:58');
CREATE TABLE social_activities (
                activity_id INTEGER PRIMARY KEY AUTOINCREMENT,
                activity_name TEXT NOT NULL,
                activity_type TEXT NOT NULL,
                description TEXT,
                location TEXT,
                activity_date DATE,
                activity_time TIME,
                max_participants INTEGER,
                current_participants INTEGER DEFAULT 0,
                interests_matched TEXT,
                created_by TEXT NOT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (created_by) REFERENCES users(username)
            );
CREATE TABLE space_utilization (
                utilization_id INTEGER PRIMARY KEY AUTOINCREMENT,
                room_id INTEGER NOT NULL,
                measurement_date TEXT NOT NULL,
                occupancy_rate REAL,
                booking_rate REAL,
                peak_usage_time TEXT,
                average_attendees REAL,
                total_booking_hours REAL,
                FOREIGN KEY (room_id) REFERENCES rooms (id)
            );
CREATE TABLE special_events (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            event_type TEXT NOT NULL,
            description TEXT,
            event_date TEXT NOT NULL,
            start_time TEXT NOT NULL,
            end_time TEXT,
            screen_number INTEGER,
            movie_id INTEGER,
            ticket_price REAL,
            max_capacity INTEGER,
            tickets_sold INTEGER DEFAULT 0,
            special_guests TEXT,
            status TEXT DEFAULT 'upcoming',
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (movie_id) REFERENCES movies(id)
        );
CREATE TABLE sports_bets (
                    bet_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT NOT NULL,
                    event_id INTEGER NOT NULL,
                    bet_type TEXT NOT NULL,
                    selection TEXT NOT NULL,
                    odds DECIMAL(6,2) NOT NULL,
                    stake DECIMAL(10,2) NOT NULL,
                    potential_return DECIMAL(10,2) NOT NULL,
                    actual_return DECIMAL(10,2) DEFAULT 0.00,
                    status TEXT DEFAULT 'pending',
                    placed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    settled_at TIMESTAMP,
                    FOREIGN KEY (event_id) REFERENCES betting_events(event_id)
                );
ANALYZE "sqlite_master";
