INSERT INTO "sqlite_stat1" VALUES('user_preferences','sqlite_autoindex_user_preferences_1','1 1');
CREATE TABLE staff (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT UNIQUE NOT NULL,
            password_hash TEXT NOT NULL,
            name TEXT NOT NULL,
            email TEXT,
            phone TEXT,
            role TEXT NOT NULL,
            hire_date TEXT,
            last_login TEXT,
            status TEXT DEFAULT 'active',
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        , salt TEXT);
CREATE TABLE staff_announcements (
                announcement_id INTEGER PRIMARY KEY AUTOINCREMENT,
                title TEXT NOT NULL,
                content TEXT NOT NULL,
                category TEXT DEFAULT 'general',
                target_audience TEXT DEFAULT 'all',
                target_departments TEXT,
                target_roles TEXT,
                posted_by TEXT NOT NULL,
                posted_by_name TEXT,
                post_date TEXT DEFAULT CURRENT_TIMESTAMP,
                expiry_date TEXT,
                is_pinned INTEGER DEFAULT 0,
                is_active INTEGER DEFAULT 1,
                view_count INTEGER DEFAULT 0,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE staff_assignments (
            assignment_id INTEGER PRIMARY KEY AUTOINCREMENT,
            staff_id TEXT NOT NULL,
            category TEXT NOT NULL,
            is_primary BOOLEAN DEFAULT 0,
            max_concurrent_tickets INTEGER DEFAULT 10,
            current_ticket_count INTEGER DEFAULT 0,
            expertise_level INTEGER DEFAULT 1,  -- 1-5 scale
            auto_assign_enabled BOOLEAN DEFAULT 1
        );
CREATE TABLE staff_availability (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            staff_id INTEGER NOT NULL,
            day_of_week INTEGER NOT NULL,
            available_from TEXT,
            available_until TEXT,
            is_available INTEGER DEFAULT 1,
            notes TEXT,
            FOREIGN KEY (staff_id) REFERENCES staff(id),
            UNIQUE(staff_id, day_of_week)
        );
CREATE TABLE staff_contracts (
                    contract_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT NOT NULL,
                    contract_type TEXT NOT NULL DEFAULT 'permanent',
                    start_date TEXT NOT NULL,
                    end_date TEXT,
                    salary REAL,
                    salary_currency TEXT DEFAULT 'GBP',
                    pay_frequency TEXT DEFAULT 'monthly',
                    terms TEXT,
                    status TEXT DEFAULT 'active',
                    renewal_date TEXT,
                    probation_end_date TEXT,
                    notice_period_days INTEGER DEFAULT 30,
                    working_hours_per_week REAL DEFAULT 37.5,
                    department TEXT,
                    job_title TEXT,
                    manager_id TEXT,
                    document_path TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    created_by TEXT
                );
CREATE TABLE staff_documents (
                document_id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id TEXT NOT NULL,
                document_type TEXT,
                document_name TEXT NOT NULL,
                file_path TEXT,
                issue_date TEXT,
                expiry_date TEXT,
                status TEXT DEFAULT 'active',
                uploaded_by TEXT,
                notes TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE staff_expertise (
                    expertise_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT NOT NULL,
                    expertise_area TEXT NOT NULL,
                    category TEXT DEFAULT 'academic',
                    proficiency TEXT DEFAULT 'intermediate',
                    keywords TEXT,
                    is_public INTEGER DEFAULT 1,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE staff_mentoring_goals (
                    goal_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    match_id INTEGER NOT NULL,
                    title TEXT NOT NULL,
                    description TEXT,
                    target_date TEXT,
                    completion_date TEXT,
                    status TEXT DEFAULT 'in_progress',
                    progress_pct INTEGER DEFAULT 0,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (match_id) REFERENCES staff_mentoring_matches(match_id)
                );
CREATE TABLE staff_mentoring_matches (
                    match_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    programme_id INTEGER NOT NULL,
                    mentor_id INTEGER NOT NULL,
                    mentee_user_id TEXT NOT NULL,
                    match_reason TEXT,
                    status TEXT DEFAULT 'proposed',
                    start_date TEXT,
                    expected_end_date TEXT,
                    actual_end_date TEXT,
                    mentor_rating INTEGER,
                    mentee_rating INTEGER,
                    notes TEXT,
                    matched_by TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (programme_id) REFERENCES staff_mentoring_programmes(programme_id),
                    FOREIGN KEY (mentor_id) REFERENCES staff_mentors(mentor_id)
                );
CREATE TABLE staff_mentoring_programmes (
                    programme_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL,
                    description TEXT,
                    programme_type TEXT DEFAULT 'general',
                    department TEXT,
                    max_mentees_per_mentor INTEGER DEFAULT 3,
                    duration_months INTEGER DEFAULT 12,
                    status TEXT DEFAULT 'active',
                    created_by TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
