CREATE TABLE staff_mentoring_sessions (
                    session_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    match_id INTEGER NOT NULL,
                    session_date TEXT NOT NULL,
                    duration_minutes INTEGER DEFAULT 60,
                    session_type TEXT DEFAULT 'one_on_one',
                    location TEXT,
                    virtual_link TEXT,
                    topics_discussed TEXT,
                    action_items TEXT,
                    mentor_notes TEXT,
                    mentee_notes TEXT,
                    status TEXT DEFAULT 'scheduled',
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (match_id) REFERENCES staff_mentoring_matches(match_id)
                );
CREATE TABLE staff_mentors (
                    mentor_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT NOT NULL,
                    programme_id INTEGER NOT NULL,
                    expertise_areas TEXT,
                    max_mentees INTEGER DEFAULT 3,
                    current_mentees INTEGER DEFAULT 0,
                    availability TEXT DEFAULT 'available',
                    bio TEXT,
                    status TEXT DEFAULT 'active',
                    joined_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (programme_id) REFERENCES staff_mentoring_programmes(programme_id)
                );
CREATE TABLE staff_noticeboard (
                notice_id INTEGER PRIMARY KEY AUTOINCREMENT,
                title TEXT NOT NULL,
                content TEXT,
                category TEXT DEFAULT 'general',
                posted_by TEXT NOT NULL,
                posted_by_name TEXT,
                contact_info TEXT,
                post_date TEXT DEFAULT CURRENT_TIMESTAMP,
                expiry_date TEXT,
                is_active INTEGER DEFAULT 1,
                view_count INTEGER DEFAULT 0
            );
CREATE TABLE staff_office_hours_directory (
                    hours_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT NOT NULL,
                    day_of_week INTEGER NOT NULL,
                    start_time TEXT NOT NULL,
                    end_time TEXT NOT NULL,
                    location TEXT,
                    virtual_link TEXT,
                    is_by_appointment INTEGER DEFAULT 0,
                    semester TEXT,
                    is_active INTEGER DEFAULT 1,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE staff_profiles (
                profile_id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id TEXT UNIQUE NOT NULL,
                employee_id TEXT UNIQUE,
                department TEXT,
                job_title TEXT,
                employment_type TEXT DEFAULT 'full-time',
                hire_date TEXT,
                contract_end_date TEXT,
                manager_id TEXT,
                office_location TEXT,
                phone_extension TEXT,
                emergency_contact_name TEXT,
                emergency_contact_phone TEXT,
                emergency_contact_relationship TEXT,
                bio TEXT,
                expertise_areas TEXT,
                qualifications TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE staff_recruitment_applications (
                application_id INTEGER PRIMARY KEY AUTOINCREMENT,
                posting_id INTEGER NOT NULL,
                job_title TEXT,
                applicant_name TEXT NOT NULL,
                applicant_email TEXT NOT NULL,
                applicant_phone TEXT,
                applicant_address TEXT,
                cv_path TEXT,
                cover_letter_path TEXT,
                portfolio_url TEXT,
                application_date TEXT DEFAULT CURRENT_TIMESTAMP,
                status TEXT DEFAULT 'received',
                shortlisted INTEGER DEFAULT 0,
                shortlisted_by TEXT,
                shortlisted_date TEXT,
                rejection_reason TEXT,
                notes TEXT,
                FOREIGN KEY (posting_id) REFERENCES staff_recruitment_postings(posting_id)
            );
CREATE TABLE staff_recruitment_postings (
                posting_id INTEGER PRIMARY KEY AUTOINCREMENT,
                job_title TEXT NOT NULL,
                department TEXT NOT NULL,
                job_type TEXT DEFAULT 'permanent',
                location TEXT,
                description TEXT,
                requirements TEXT,
                responsibilities TEXT,
                salary_range TEXT,
                benefits TEXT,
                posted_by TEXT NOT NULL,
                posted_by_name TEXT,
                post_date TEXT,
                closing_date TEXT,
                status TEXT DEFAULT 'draft',
                hiring_manager_id TEXT,
                hiring_manager_name TEXT,
                applications_count INTEGER DEFAULT 0,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE staff_schedules (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                staff_id TEXT NOT NULL,
                shift_date DATE NOT NULL,
                start_time TIME NOT NULL,
                end_time TIME NOT NULL,
                position TEXT NOT NULL,
                status TEXT DEFAULT 'scheduled',
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE staff_workload (
                workload_id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id TEXT NOT NULL,
                academic_year TEXT NOT NULL,
                semester TEXT,
                teaching_hours REAL DEFAULT 0,
                research_hours REAL DEFAULT 0,
                admin_hours REAL DEFAULT 0,
                service_hours REAL DEFAULT 0,
                total_fte REAL DEFAULT 1.0,
                notes TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                UNIQUE(user_id, academic_year, semester)
            );
CREATE TABLE stored_emails (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            recipient_email TEXT NOT NULL,
            subject TEXT NOT NULL,
            body TEXT NOT NULL,
            sender_email TEXT NOT NULL,
            sender_name TEXT NOT NULL,
            cc_recipients TEXT,
            bcc_recipients TEXT,
            attachment_paths TEXT,
            created_date TEXT NOT NULL,
            template_name TEXT,
            template_vars TEXT,
            related_to TEXT,
            student_id TEXT
        );
