CREATE TABLE student_absences (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                student_id TEXT,
                absence_date TEXT,
                return_date TEXT,
                reason TEXT,
                reported_by TEXT,
                reported_date TEXT,
                notes TEXT,
                FOREIGN KEY (student_id) REFERENCES students (student_id)
            );
CREATE TABLE student_activities (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                student_id TEXT,
                activity_id INTEGER,
                enrollment_date TEXT,
                status TEXT DEFAULT 'active',
                FOREIGN KEY (student_id) REFERENCES students (student_id),
                FOREIGN KEY (activity_id) REFERENCES extracurricular_activities (id)
            );
CREATE TABLE student_attendance(
  student_id TEXT,
  module_code TEXT,
  date TEXT,
  status TEXT,
  notes TEXT,
  recorded_at TEXT
);
CREATE TABLE student_badges (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT,
            badge_id INTEGER,
            earned_date TEXT,
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (badge_id) REFERENCES achievement_badges (badge_id)
        );
CREATE TABLE student_behavior (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                student_id TEXT,
                incident_date TEXT,
                behavior_type TEXT,
                severity TEXT,
                description TEXT,
                action_taken TEXT,
                reported_by TEXT,
                follow_up_required BOOLEAN DEFAULT 0,
                resolved BOOLEAN DEFAULT 0,
                FOREIGN KEY (student_id) REFERENCES students (student_id)
            );
CREATE TABLE student_biometrics (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT,
            face_encoding BLOB,
            face_photo_path TEXT,
            enrolled_date TEXT DEFAULT CURRENT_TIMESTAMP,
            last_updated TEXT DEFAULT CURRENT_TIMESTAMP,
            status TEXT DEFAULT 'active',
            FOREIGN KEY (student_id) REFERENCES students (student_id)
        );
CREATE TABLE student_budget_categories (
                        category_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        budget_id INTEGER NOT NULL,
                        category_name TEXT NOT NULL,
                        category_type TEXT CHECK(category_type IN ('essential', 'discretionary', 'savings', 'debt')),
                        allocated_amount REAL NOT NULL,
                        spent_amount REAL DEFAULT 0.0,
                        color_code TEXT,
                        icon TEXT,
                        notes TEXT,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        UNIQUE(budget_id, category_name)
                    );
CREATE TABLE student_budgets (
                        budget_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        student_id TEXT NOT NULL,
                        budget_name TEXT NOT NULL,
                        budget_type TEXT CHECK(budget_type IN ('monthly', 'weekly', 'semester', 'annual', 'custom')),
                        start_date TEXT NOT NULL,
                        end_date TEXT NOT NULL,
                        total_income REAL DEFAULT 0.0,
                        total_budget REAL NOT NULL,
                        allocated_amount REAL DEFAULT 0.0,
                        spent_amount REAL DEFAULT 0.0,
                        is_active BOOLEAN DEFAULT 1,
                        notes TEXT,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        FOREIGN KEY (student_id) REFERENCES students(student_id)
                    );
INSERT INTO "student_budgets" VALUES(1,'admin','test','monthly','2026-03-16','2026-04-15',0.0,5000.0,0.0,0.0,1,NULL,'2026-03-16 22:14:11','2026-03-16 22:14:11');
CREATE TABLE student_clubs (
                    club_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    club_name TEXT UNIQUE NOT NULL,
                    description TEXT,
                    category TEXT,
                    member_count INTEGER DEFAULT 0,
                    president_id TEXT,
                    treasurer_id TEXT,
                    secretary_id TEXT,
                    status TEXT DEFAULT 'active',
                    created_date TEXT,
                    FOREIGN KEY (president_id) REFERENCES students (student_id),
                    FOREIGN KEY (treasurer_id) REFERENCES students (student_id),
                    FOREIGN KEY (secretary_id) REFERENCES students (student_id)
                );
CREATE TABLE student_competencies (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            competency_id INTEGER NOT NULL,
            level_id INTEGER NOT NULL,
            assessment_date TEXT,
            evidence TEXT,
            FOREIGN KEY (student_id) REFERENCES students(student_id),
            FOREIGN KEY (competency_id) REFERENCES competencies(competency_id),
            FOREIGN KEY (level_id) REFERENCES competency_levels(level_id)
        );
CREATE TABLE student_credits (
            credit_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            credit_amount DECIMAL(10,2) NOT NULL,
            currency TEXT DEFAULT 'GBP',
            credit_source TEXT, -- 'overpayment', 'refund', 'scholarship', 'adjustment'
            description TEXT,
            expiry_date TEXT,
            remaining_amount DECIMAL(10,2) NOT NULL,
            status TEXT DEFAULT 'active', -- active, used, expired
            created_by TEXT,
            created_at TEXT,
            updated_at TEXT,
            FOREIGN KEY (student_id) REFERENCES students (student_id)
        );
