CREATE TABLE student_demographics (
                student_id TEXT PRIMARY KEY,
                age_group TEXT,
                gender TEXT,
                ethnicity TEXT,
                native_language TEXT,
                academic_level TEXT,
                accommodations TEXT
            );
CREATE TABLE student_documents (
                document_id INTEGER PRIMARY KEY AUTOINCREMENT,
                student_id TEXT,
                type_id INTEGER,
                file_path TEXT,
                original_filename TEXT,
                upload_date TEXT,
                expiry_date TEXT,
                verification_status TEXT,
                verification_date TEXT,
                verification_notes TEXT,
                version_number INTEGER DEFAULT 1,
                parent_document_id INTEGER,
                uploaded_by TEXT,
                file_size INTEGER,
                file_hash TEXT,
                tags TEXT,
                is_current_version BOOLEAN DEFAULT 1,
                workflow_status TEXT DEFAULT 'pending',
                priority INTEGER DEFAULT 0,
                FOREIGN KEY (student_id) REFERENCES students (student_id),
                FOREIGN KEY (type_id) REFERENCES document_types (type_id),
                FOREIGN KEY (parent_document_id) REFERENCES student_documents (document_id),
                FOREIGN KEY (uploaded_by) REFERENCES users (username)
            );
INSERT INTO "student_documents" VALUES(1,'9310648',6,'/home/seancatchpole989/education_system/university_system/data/uploads/student_documents/9310648/20260311_221535_2.pdf','2.pdf','2026-03-11 22:15:35',NULL,'Pending',NULL,'',1,NULL,'admin',2396,'d8b43daaffa8f22e9e98825b29a204f03237e934c3a71f07a56df41fbdef2c24','',1,'submitted',0);
CREATE TABLE student_employment (
                        employment_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        student_id TEXT NOT NULL,
                        job_id INTEGER NOT NULL,
                        application_id INTEGER,
                        start_date TEXT NOT NULL,
                        end_date TEXT,
                        employment_status TEXT DEFAULT 'active' CHECK(employment_status IN ('active', 'on-leave', 'completed', 'terminated')),
                        hourly_rate REAL NOT NULL,
                        max_hours_per_week INTEGER,
                        supervisor_id INTEGER,
                        department TEXT,
                        position_title TEXT NOT NULL,
                        is_work_study BOOLEAN DEFAULT 0,
                        work_study_allocation REAL DEFAULT 0.0,
                        work_study_used REAL DEFAULT 0.0,
                        performance_rating REAL,
                        notes TEXT,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        FOREIGN KEY (student_id) REFERENCES students(student_id),
                        FOREIGN KEY (job_id) REFERENCES campus_job_postings(job_id),
                        FOREIGN KEY (application_id) REFERENCES campus_job_applications(application_id)
                    );
CREATE TABLE student_events (
                        event_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        event_name TEXT NOT NULL,
                        event_date TEXT NOT NULL,
                        event_description TEXT,
                        event_location TEXT,
                        club_id INTEGER,
                        created_by INTEGER,
                        created_date TEXT DEFAULT CURRENT_TIMESTAMP,
                        FOREIGN KEY (club_id) REFERENCES student_clubs(club_id)
                    );
CREATE TABLE student_expenses (
                        expense_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        student_id TEXT NOT NULL,
                        budget_id INTEGER,
                        category_id INTEGER,
                        expense_date TEXT NOT NULL,
                        amount REAL NOT NULL,
                        merchant_name TEXT,
                        description TEXT,
                        payment_method TEXT CHECK(payment_method IN ('cash', 'debit', 'credit', 'meal-plan', 'financial-aid', 'other')),
                        receipt_url TEXT,
                        is_recurring BOOLEAN DEFAULT 0,
                        recurrence_pattern TEXT,
                        tags TEXT,
                        location TEXT,
                        notes TEXT,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        FOREIGN KEY (student_id) REFERENCES students(student_id),
                        FOREIGN KEY (budget_id) REFERENCES student_budgets(budget_id),
                        FOREIGN KEY (category_id) REFERENCES budget_categories(category_id)
                    );
