CREATE TABLE student_job_performance (
                        review_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        employment_id INTEGER NOT NULL,
                        student_id TEXT NOT NULL,
                        reviewer_id INTEGER NOT NULL,
                        review_date TEXT NOT NULL,
                        review_period_start TEXT,
                        review_period_end TEXT,
                        attendance_rating INTEGER CHECK(attendance_rating BETWEEN 1 AND 5),
                        quality_rating INTEGER CHECK(quality_rating BETWEEN 1 AND 5),
                        initiative_rating INTEGER CHECK(initiative_rating BETWEEN 1 AND 5),
                        teamwork_rating INTEGER CHECK(teamwork_rating BETWEEN 1 AND 5),
                        overall_rating REAL,
                        strengths TEXT,
                        areas_for_improvement TEXT,
                        supervisor_comments TEXT,
                        student_comments TEXT,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        FOREIGN KEY (employment_id) REFERENCES student_employment(employment_id),
                        FOREIGN KEY (student_id) REFERENCES students(student_id),
                        FOREIGN KEY (reviewer_id) REFERENCES users(id)
                    );
CREATE TABLE student_medical_info (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                student_id TEXT,
                condition_type TEXT,
                description TEXT,
                medication_name TEXT,
                dosage TEXT,
                administration_time TEXT,
                emergency_contact TEXT,
                doctor_contact TEXT,
                expiry_date TEXT,
                notes TEXT,
                FOREIGN KEY (student_id) REFERENCES students (student_id)
            );
CREATE TABLE student_milestone_progress (
                    progress_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL,
                    milestone_id INTEGER NOT NULL,
                    achieved BOOLEAN DEFAULT 0,
                    achieved_date TEXT,
                    achieved_semester INTEGER,
                    notes TEXT,
                    FOREIGN KEY (milestone_id) REFERENCES degree_milestones(milestone_id),
                    UNIQUE(student_id, milestone_id)
                );
CREATE TABLE student_modules (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT,
            module_code TEXT,
            enrollment_date TEXT DEFAULT (date('now')),
            status TEXT DEFAULT 'Enrolled', module_type TEXT DEFAULT 'Standard', module_name TEXT, grade TEXT, completion_date TEXT,
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (module_code) REFERENCES modules (module_code),
            UNIQUE(student_id, module_code)
        );
