CREATE TABLE student_payment_plans (
            payment_plan_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            template_id INTEGER,
            total_amount DECIMAL(10,2) NOT NULL,
            remaining_amount DECIMAL(10,2) NOT NULL,
            currency TEXT DEFAULT 'GBP',
            status TEXT DEFAULT 'active', -- active, completed, defaulted, cancelled
            start_date TEXT NOT NULL,
            next_due_date TEXT,
            setup_fee_paid BOOLEAN DEFAULT 0,
            auto_payment_enabled BOOLEAN DEFAULT 0,
            payment_method_id INTEGER,
            notes TEXT,
            created_at TEXT,
            updated_at TEXT,
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (template_id) REFERENCES payment_plan_templates (template_id)
        );
CREATE TABLE student_points (
            points_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT,
            points_earned INTEGER,
            points_spent INTEGER DEFAULT 0,
            current_balance INTEGER,
            activity_type TEXT,
            activity_description TEXT,
            earned_date TEXT,
            FOREIGN KEY (student_id) REFERENCES students (student_id)
        );
CREATE TABLE student_requirement_progress (
                    id TEXT PRIMARY KEY,
                    student_id TEXT NOT NULL,
                    requirement_id TEXT NOT NULL,
                    credits_completed REAL DEFAULT 0.0,
                    completion_percentage REAL DEFAULT 0.0,
                    status TEXT DEFAULT 'in_progress',
                    completion_date TEXT,
                    notes TEXT,
                    FOREIGN KEY (student_id) REFERENCES students (student_id),
                    FOREIGN KEY (requirement_id) REFERENCES graduation_requirements (id),
                    UNIQUE(student_id, requirement_id)
                );
CREATE TABLE student_resumes (
            resume_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            resume_name TEXT NOT NULL,
            file_url TEXT NOT NULL,
            template_used TEXT,
            is_primary BOOLEAN DEFAULT 0,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (student_id) REFERENCES students (student_id)
        );
CREATE TABLE student_risk_assessment (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            risk_score REAL NOT NULL,
            risk_level TEXT NOT NULL,
            assessment_date TEXT,
            prediction_model TEXT,
            confidence REAL,
            FOREIGN KEY (student_id) REFERENCES students(student_id)
        );
CREATE TABLE student_scholarship_applications (
                        application_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        scholarship_id INTEGER NOT NULL,
                        student_id TEXT NOT NULL,
                        application_date TEXT DEFAULT (date('now')),
                        deadline_date TEXT NOT NULL,
                        status TEXT DEFAULT 'draft' CHECK(status IN ('draft', 'in-progress', 'submitted', 'under-review', 'finalist', 'awarded', 'denied', 'withdrawn')),
                        match_score REAL,
                        estimated_competition TEXT,
                        essay_completed BOOLEAN DEFAULT 0,
                        recommendations_obtained INTEGER DEFAULT 0,
                        recommendations_required INTEGER DEFAULT 0,
                        transcript_uploaded BOOLEAN DEFAULT 0,
                        documents_completed BOOLEAN DEFAULT 0,
                        application_progress REAL DEFAULT 0.0,
                        submission_date TEXT,
                        notification_received BOOLEAN DEFAULT 0,
                        notification_date TEXT,
                        award_amount REAL,
                        award_accepted BOOLEAN DEFAULT 0,
                        acceptance_date TEXT,
                        decline_reason TEXT,
                        notes TEXT,
                        reminder_sent BOOLEAN DEFAULT 0,
                        last_reminder_date TEXT,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        FOREIGN KEY (scholarship_id) REFERENCES scholarship_opportunities(scholarship_id),
                        FOREIGN KEY (student_id) REFERENCES students(student_id),
                        UNIQUE(scholarship_id, student_id)
                    );
CREATE TABLE student_scholarship_profiles (
                        profile_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        student_id TEXT NOT NULL UNIQUE,
                        citizenship_status TEXT,
                        state_residency TEXT,
                        ethnicity TEXT,
                        gender TEXT,
                        first_generation BOOLEAN DEFAULT 0,
                        military_affiliation TEXT,
                        disability_status TEXT,
                        financial_need_level TEXT CHECK(financial_need_level IN ('none', 'low', 'moderate', 'high', 'exceptional')),
                        intended_career_field TEXT,
                        community_service_hours INTEGER DEFAULT 0,
                        leadership_positions TEXT,
                        academic_honors TEXT,
                        extracurricular_activities TEXT,
                        special_talents TEXT,
                        languages_spoken TEXT,
                        study_abroad_interest BOOLEAN DEFAULT 0,
                        research_interest BOOLEAN DEFAULT 0,
                        preferred_scholarship_types TEXT,
                        minimum_award_amount REAL,
                        willing_to_write_essays BOOLEAN DEFAULT 1,
                        max_recommendation_letters INTEGER DEFAULT 3,
                        profile_completeness REAL DEFAULT 0.0,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        FOREIGN KEY (student_id) REFERENCES students(student_id)
                    );
CREATE TABLE student_scholarships (
            student_scholarship_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            scholarship_id INTEGER NOT NULL,
            amount DECIMAL(10,2) NOT NULL,
            status TEXT DEFAULT 'active',
            awarded_date TEXT,
            created_at TEXT,
            FOREIGN KEY (student_id) REFERENCES students (student_id),
            FOREIGN KEY (scholarship_id) REFERENCES scholarships (scholarship_id)
        );
CREATE TABLE student_skills (
            skill_id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            skill_name TEXT NOT NULL,
            skill_category TEXT,
            proficiency_level TEXT,
            verified BOOLEAN DEFAULT 0,
            acquired_date TEXT,
            FOREIGN KEY (student_id) REFERENCES students (student_id)
        );
CREATE TABLE student_supervisions (
                supervision_id INTEGER PRIMARY KEY AUTOINCREMENT,
                supervisor_id TEXT NOT NULL,
                student_id TEXT NOT NULL,
                student_name TEXT,
                program_type TEXT,
                thesis_title TEXT,
                start_date TEXT,
                expected_end_date TEXT,
                actual_end_date TEXT,
                status TEXT DEFAULT 'active',
                supervision_role TEXT DEFAULT 'primary',
                progress_notes TEXT,
                milestones TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE student_textbook_purchases (
                        purchase_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        student_id TEXT NOT NULL,
                        listing_id INTEGER,
                        isbn TEXT NOT NULL,
                        title TEXT NOT NULL,
                        course_code TEXT,
                        purchase_date TEXT NOT NULL,
                        vendor TEXT NOT NULL,
                        purchase_type TEXT CHECK(purchase_type IN ('buy-new', 'buy-used', 'rent', 'digital')),
                        price_paid REAL NOT NULL,
                        condition TEXT,
                        rental_due_date TEXT,
                        resale_value REAL,
                        notes TEXT,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        FOREIGN KEY (student_id) REFERENCES students(student_id),
                        FOREIGN KEY (listing_id) REFERENCES textbook_listings(listing_id)
                    );
CREATE TABLE student_timetables (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            student_id TEXT NOT NULL,
            module_code TEXT NOT NULL,
            day_of_week TEXT NOT NULL,
            time_slot TEXT NOT NULL,
            room TEXT,
            instructor_id INTEGER,
            academic_year TEXT,
            semester TEXT,
            FOREIGN KEY (student_id) REFERENCES students(student_id),
            FOREIGN KEY (module_code) REFERENCES modules(module_code),
            FOREIGN KEY (instructor_id) REFERENCES instructors(id)
        );
CREATE TABLE "students" (
        student_id TEXT PRIMARY KEY,
        email_address TEXT,
        title TEXT,
        first_name TEXT,
        middle_name TEXT,
        last_name TEXT,
        gender TEXT,
        dob TEXT,
        age INTEGER,
        course TEXT,
        registration_datetime TEXT,
        status TEXT DEFAULT 'Active',
        enrollment_date TEXT
    , emergency_contact TEXT DEFAULT '', pronouns TEXT DEFAULT '');
