CREATE TABLE sync_queue (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                queue_name TEXT,        -- optional: 'default','labs','claims'
                entity_type TEXT,       -- e.g., 'student','claim','lab_order'
                entity_id TEXT,
                operation TEXT,         -- upsert/delete/sync
                payload TEXT,
                priority INTEGER DEFAULT 5,
                attempts INTEGER DEFAULT 0,
                next_attempt_at TEXT,
                last_error TEXT,
                status TEXT,            -- pending/locked/failed/done
                locked_by TEXT,
                locked_at TEXT,
                created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                updated_at TEXT
            );
CREATE TABLE system_integration_log (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                source_system TEXT,
                target_system TEXT,
                operation TEXT,
                status TEXT,
                details TEXT,
                timestamp TEXT
            );
CREATE TABLE system_integrations (
            integration_id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            type TEXT NOT NULL,  -- sso, lms, sis, calendar, etc.
            config TEXT NOT NULL,  -- JSON configuration
            is_active BOOLEAN DEFAULT 0,
            last_sync_datetime TEXT,
            sync_status TEXT DEFAULT 'never',
            error_log TEXT
        );
CREATE TABLE system_metrics (
            metric_id INTEGER PRIMARY KEY AUTOINCREMENT,
            metric_name TEXT NOT NULL,
            metric_value REAL NOT NULL,
            category TEXT NOT NULL,
            recorded_datetime TEXT NOT NULL,
            metadata TEXT  -- JSON data
        );
