CREATE TABLE training_courses (
                    course_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL,
                    description TEXT,
                    category TEXT,
                    provider TEXT,
                    duration_hours REAL,
                    passing_score REAL DEFAULT 70,
                    is_mandatory BOOLEAN DEFAULT 0,
                    recertification_months INTEGER,
                    is_active BOOLEAN DEFAULT 1,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE training_enrollments (
                    enrollment_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT NOT NULL,
                    course_id INTEGER NOT NULL,
                    enrolled_date TEXT DEFAULT CURRENT_TIMESTAMP,
                    due_date TEXT,
                    started_date TEXT,
                    completed_date TEXT,
                    status TEXT DEFAULT 'enrolled',
                    score REAL,
                    attempts INTEGER DEFAULT 0,
                    certificate_path TEXT,
                    notes TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (course_id) REFERENCES training_courses(course_id)
                );
CREATE TABLE transportation (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                student_id TEXT,
                route_name TEXT,
                bus_number TEXT,
                pickup_time TEXT,
                dropoff_time TEXT,
                pickup_location TEXT,
                dropoff_location TEXT,
                driver_name TEXT,
                driver_phone TEXT,
                active BOOLEAN DEFAULT 1,
                FOREIGN KEY (student_id) REFERENCES students (student_id)
            );
CREATE TABLE transportation_requests (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL,
                    service_type TEXT,
                    route_preference TEXT,
                    special_needs TEXT,
                    start_date TEXT,
                    request_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    status TEXT DEFAULT 'Pending'
                );
CREATE TABLE travel_approvals (
                    approval_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    request_id INTEGER NOT NULL,
                    approval_level TEXT NOT NULL,
                    approver_id TEXT NOT NULL,
                    status TEXT DEFAULT 'pending',
                    comments TEXT,
                    reviewed_date TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (request_id) REFERENCES travel_requests(request_id)
                );
CREATE TABLE travel_expenses (
                    link_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    request_id INTEGER NOT NULL,
                    claim_id INTEGER NOT NULL,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (request_id) REFERENCES travel_requests(request_id)
                );
CREATE TABLE travel_itinerary (
                    leg_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    request_id INTEGER NOT NULL,
                    leg_order INTEGER NOT NULL DEFAULT 1,
                    transport_type TEXT NOT NULL DEFAULT 'flight',
                    departure_location TEXT,
                    arrival_location TEXT,
                    departure_datetime TEXT,
                    arrival_datetime TEXT,
                    booking_reference TEXT,
                    carrier TEXT,
                    cost REAL DEFAULT 0,
                    notes TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (request_id) REFERENCES travel_requests(request_id)
                );
CREATE TABLE travel_requests (
                    request_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    user_id TEXT NOT NULL,
                    purpose TEXT NOT NULL,
                    destination TEXT NOT NULL,
                    departure_date TEXT NOT NULL,
                    return_date TEXT NOT NULL,
                    estimated_budget REAL DEFAULT 0,
                    budget_breakdown_json TEXT,
                    funding_source TEXT DEFAULT 'department',
                    status TEXT DEFAULT 'draft',
                    justification TEXT,
                    department TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE trip_calendar_events (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    trip_id INTEGER NOT NULL,
                    event_id TEXT NOT NULL,
                    event_type TEXT DEFAULT 'trip_event',
                    created_at TEXT NOT NULL,
                    UNIQUE (trip_id, event_id)
                );
CREATE TABLE trip_expenses (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                trip_id INTEGER NOT NULL,
                category TEXT NOT NULL,
                description TEXT NOT NULL,
                amount REAL NOT NULL,
                date TEXT NOT NULL,
                recorded_by INTEGER,
                FOREIGN KEY (trip_id) REFERENCES trips (id) ON DELETE CASCADE,
                FOREIGN KEY (recorded_by) REFERENCES users (id)
            );
CREATE TABLE trip_itinerary (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                trip_id INTEGER NOT NULL,
                day_number INTEGER NOT NULL,
                activity TEXT NOT NULL,
                location TEXT,
                start_time TEXT,
                end_time TEXT,
                notes TEXT,
                FOREIGN KEY (trip_id) REFERENCES trips (id) ON DELETE CASCADE,
                UNIQUE (trip_id, day_number, start_time)
            );
CREATE TABLE trip_participants (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                trip_id INTEGER NOT NULL,
                student_id TEXT,
                user_id INTEGER,
                registration_date TEXT NOT NULL,
                payment_status TEXT DEFAULT 'pending',
                emergency_contact TEXT,
                medical_info TEXT,
                dietary_requirements TEXT,
                status TEXT DEFAULT 'registered',
                FOREIGN KEY (trip_id) REFERENCES trips (id) ON DELETE CASCADE,
                FOREIGN KEY (student_id) REFERENCES students (student_id),
                FOREIGN KEY (user_id) REFERENCES users (id),
                UNIQUE (trip_id, student_id),
                CHECK (payment_status IN ('pending', 'partial', 'paid', 'refunded')),
                CHECK (status IN ('registered', 'waitlist', 'cancelled', 'attended'))
            );
INSERT INTO "trip_participants" VALUES(1,1,NULL,5,'2026-01-15 21:28:31','pending','devon 07790994856','','','registered');
CREATE TABLE trip_staff (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                trip_id INTEGER NOT NULL,
                staff_user_id INTEGER NOT NULL,
                role TEXT DEFAULT 'supervisor',
                assigned_date TEXT NOT NULL,
                FOREIGN KEY (trip_id) REFERENCES trips (id) ON DELETE CASCADE,
                FOREIGN KEY (staff_user_id) REFERENCES users (id),
                UNIQUE (trip_id, staff_user_id),
                CHECK (role IN ('supervisor', 'coordinator', 'medical', 'transport'))
            );
CREATE TABLE trips (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                trip_name TEXT NOT NULL,
                description TEXT,
                destination TEXT NOT NULL,
                start_date TEXT NOT NULL,
                end_date TEXT NOT NULL,
                max_participants INTEGER DEFAULT 50,
                cost REAL DEFAULT 0.0,
                status TEXT DEFAULT 'planning',
                created_by INTEGER,
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL,
                FOREIGN KEY (created_by) REFERENCES users (id),
                CHECK (status IN ('planning', 'open', 'full', 'cancelled', 'completed'))
            );
