CREATE TABLE user_achievements (
            achievement_id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id TEXT NOT NULL,
            achievement_type TEXT NOT NULL,
            achievement_name TEXT NOT NULL,
            description TEXT,
            earned_date TEXT NOT NULL,
            points INTEGER DEFAULT 0
        );
CREATE TABLE user_activity_log (
            log_id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id TEXT,
            activity_type TEXT,
            activity_description TEXT,
            timestamp TEXT,
            ip_address TEXT,
            user_agent TEXT
        );
CREATE TABLE user_interests (
                interest_id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id TEXT NOT NULL,
                interest_category TEXT NOT NULL,
                interest_name TEXT NOT NULL,
                interest_level INTEGER DEFAULT 5,
                is_public INTEGER DEFAULT 1,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (user_id) REFERENCES users(username),
                UNIQUE(user_id, interest_category, interest_name)
            );
CREATE TABLE user_permissions (
                    user_id TEXT PRIMARY KEY,
                    role TEXT,
                    permissions TEXT,
                    created_date DATETIME DEFAULT CURRENT_TIMESTAMP,
                    updated_date DATETIME DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE user_personality (
                personality_id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id TEXT NOT NULL UNIQUE,
                personality_type TEXT,
                extroversion_score INTEGER,
                openness_score INTEGER,
                social_preference TEXT,
                group_size_preference TEXT,
                activity_level TEXT,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (user_id) REFERENCES users(username)
            );
CREATE TABLE user_preferences (
            user_id TEXT PRIMARY KEY,
            email_notifications BOOLEAN DEFAULT 1,
            in_app_notifications BOOLEAN DEFAULT 1,
            push_notifications BOOLEAN DEFAULT 1,
            digest_frequency TEXT DEFAULT 'daily',  -- immediate, daily, weekly
            theme TEXT DEFAULT 'light',
            language TEXT DEFAULT 'en',
            timezone TEXT DEFAULT 'UTC',
            preferences_json TEXT  -- Additional JSON preferences
        );
