CREATE TABLE user_privacy_settings (
                privacy_id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id TEXT NOT NULL UNIQUE,
                allow_matching INTEGER DEFAULT 1,
                show_profile INTEGER DEFAULT 1,
                allow_messages INTEGER DEFAULT 1,
                show_interests INTEGER DEFAULT 1,
                show_in_search INTEGER DEFAULT 1,
                match_same_major INTEGER DEFAULT 0,
                match_same_year INTEGER DEFAULT 0,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (user_id) REFERENCES users(username)
            );
CREATE TABLE user_resumes (
                    resume_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL,
                    resume_name TEXT NOT NULL,
                    template_id INTEGER,
                    content TEXT NOT NULL,
                    last_generated TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    format TEXT DEFAULT 'pdf' CHECK(format IN ('pdf', 'docx', 'html')),
                    FOREIGN KEY (student_id) REFERENCES students(student_id),
                    FOREIGN KEY (template_id) REFERENCES resume_templates(template_id)
                );
CREATE TABLE user_timezone_preferences (
                    user_id TEXT PRIMARY KEY,
                    timezone_name TEXT NOT NULL,
                    auto_dst BOOLEAN DEFAULT TRUE,
                    created_at TEXT NOT NULL,
                    updated_at TEXT NOT NULL,
                    FOREIGN KEY (user_id) REFERENCES users (id)
                );
CREATE TABLE users (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                username TEXT UNIQUE NOT NULL,
                first_name TEXT NOT NULL,
                last_name TEXT NOT NULL,
                email TEXT UNIQUE NOT NULL,
                role TEXT NOT NULL,
                student_id TEXT,
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL,
                FOREIGN KEY (student_id) REFERENCES students (student_id)
            );
