CREATE TABLE verification_questions (
                    question_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    found_item_id INTEGER NOT NULL,
                    question_text TEXT NOT NULL,
                    expected_answer_type TEXT DEFAULT 'text',
                    created_by TEXT NOT NULL,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (found_item_id) REFERENCES found_items(item_id) ON DELETE CASCADE
                );
CREATE TABLE verification_requests (
    request_id INTEGER PRIMARY KEY AUTOINCREMENT,
    credential_id INTEGER,
    badge_issuance_id INTEGER,
    requester_name TEXT NOT NULL,
    requester_email TEXT,
    requester_organization TEXT,
    status TEXT DEFAULT 'pending',
    requested_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    processed_date TIMESTAMP,
    FOREIGN KEY (credential_id) REFERENCES blockchain_credentials(credential_id),
    FOREIGN KEY (badge_issuance_id) REFERENCES badge_issuances(issuance_id)
);
CREATE TABLE violation_appeals (
    appeal_id INTEGER PRIMARY KEY AUTOINCREMENT,
    violation_id INTEGER NOT NULL,
    reason TEXT NOT NULL,
    supporting_documents TEXT,  -- JSON array
    status TEXT DEFAULT 'pending',
    submitted_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    reviewed_by INTEGER,
    review_date TIMESTAMP,
    decision TEXT,
    FOREIGN KEY (violation_id) REFERENCES parking_violations(violation_id)
);
CREATE TABLE virtual_chat_messages (
    message_id INTEGER PRIMARY KEY AUTOINCREMENT,
    session_id INTEGER NOT NULL,
    user_id INTEGER NOT NULL,
    user_name TEXT NOT NULL,
    message_text TEXT NOT NULL,
    message_type TEXT DEFAULT 'public',  -- public, private, announcement
    recipient_id INTEGER,  -- for private messages
    timestamp TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    is_deleted BOOLEAN DEFAULT 0,
    replied_to INTEGER,  -- message_id of parent message
    reactions TEXT,  -- JSON: {emoji: count}
    FOREIGN KEY (session_id) REFERENCES virtual_sessions(session_id) ON DELETE CASCADE,
    FOREIGN KEY (replied_to) REFERENCES virtual_chat_messages(message_id)
);
CREATE TABLE virtual_classrooms (
    classroom_id INTEGER PRIMARY KEY AUTOINCREMENT,
    session_name TEXT NOT NULL,
    course_id INTEGER,
    instructor_id INTEGER NOT NULL,
    platform TEXT NOT NULL,  -- 'zoom', 'teams', 'meet', 'webrtc'
    meeting_link TEXT,
    meeting_id TEXT,
    passcode TEXT,
    max_participants INTEGER DEFAULT 100,
    features TEXT,  -- JSON: {whiteboard, breakout_rooms, recording, polling}
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    is_active BOOLEAN DEFAULT 1,
    FOREIGN KEY (course_id) REFERENCES courses(course_id),
    FOREIGN KEY (instructor_id) REFERENCES instructors(instructor_id)
);
