                    created_at TEXT,
                    FOREIGN KEY (student_id) REFERENCES students (student_id)
                );
CREATE TABLE volunteer_opportunities (
            opportunity_id INTEGER PRIMARY KEY AUTOINCREMENT,
            organization_name TEXT,
