        );
CREATE TABLE wellness_checkins (
                    checkin_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL,
                    checkin_date TEXT NOT NULL,
                    overall_mood INTEGER CHECK(overall_mood BETWEEN 1 AND 10),
                    stress_level INTEGER CHECK(stress_level BETWEEN 1 AND 10),
                    sleep_quality INTEGER CHECK(sleep_quality BETWEEN 1 AND 10),
                    energy_level INTEGER CHECK(energy_level BETWEEN 1 AND 10),
                    anxiety_level INTEGER CHECK(anxiety_level BETWEEN 1 AND 10),
                    notes TEXT,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (student_id) REFERENCES students(student_id)
                );
CREATE TABLE wellness_goals (
                    goal_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL,
                    goal_type TEXT NOT NULL,
                    goal_description TEXT NOT NULL,
                    target_value REAL,
                    current_value REAL DEFAULT 0,
                    start_date TEXT NOT NULL,
                    end_date TEXT,
                    status TEXT DEFAULT 'Active',
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (student_id) REFERENCES students(student_id)
                );
CREATE TABLE wellness_participation (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT,
                    program_name TEXT,
                    enrollment_date TEXT,
                    completion_date TEXT,
                    status TEXT DEFAULT 'enrolled',
                    progress_score INTEGER DEFAULT 0,
                    goals_met INTEGER DEFAULT 0,
                    created_at TEXT,
                    FOREIGN KEY (student_id) REFERENCES students (student_id)
                );
CREATE TABLE wellness_points (
                    point_id INTEGER PRIMARY KEY AUTOINCREMENT,
                    student_id TEXT NOT NULL,
                    points_earned INTEGER DEFAULT 0,
                    activity_type TEXT NOT NULL,
                    activity_description TEXT,
                    earned_date TEXT NOT NULL,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (student_id) REFERENCES students(student_id)
                );
CREATE TABLE work_hours_log (
                        log_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        employment_id INTEGER NOT NULL,
                        student_id TEXT NOT NULL,
                        work_date TEXT NOT NULL,
                        clock_in_time TEXT NOT NULL,
                        clock_out_time TEXT,
                        break_duration_minutes INTEGER DEFAULT 0,
                        total_hours REAL,
                        hourly_rate REAL NOT NULL,
                        earnings REAL,
                        is_work_study BOOLEAN DEFAULT 0,
                        work_study_deduction REAL DEFAULT 0.0,
                        task_description TEXT,
                        supervisor_id INTEGER,
                        approved_by INTEGER,
                        approved_date TEXT,
                        status TEXT DEFAULT 'pending' CHECK(status IN ('pending', 'approved', 'rejected', 'paid')),
                        notes TEXT,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        FOREIGN KEY (employment_id) REFERENCES student_employment(employment_id),
                        FOREIGN KEY (student_id) REFERENCES students(student_id),
                        FOREIGN KEY (approved_by) REFERENCES users(id)
                    );
CREATE TABLE work_orders (
