CREATE TRIGGER update_document_timestamp 
                AFTER UPDATE ON document_repository
                BEGIN
                    UPDATE document_repository SET updated_at = CURRENT_TIMESTAMP WHERE id = NEW.id;
                END;
CREATE TRIGGER notify_parent_on_grade
        AFTER INSERT ON student_grades
        BEGIN
            INSERT INTO parent_notifications (
                parent_id,
                student_id,
                notification_type,
                notification_content,
                created_date,
                read_status
            )
            SELECT
                psr.parent_id,
                NEW.student_id,
                'grade',
                'New grade recorded: ' || NEW.assessment_name || ' - ' || NEW.grade,
                datetime('now'),
                0
            FROM parent_student_relationships psr
            JOIN parent_preferences pp ON psr.parent_id = pp.parent_id
            WHERE psr.student_id = NEW.student_id AND pp.grade_alerts = 1;
        END;
CREATE TRIGGER notify_parent_on_absence
        AFTER INSERT ON attendance
        WHEN NEW.status != 'present'
        BEGIN
            INSERT INTO parent_notifications (
                parent_id,
                student_id,
                notification_type,
                notification_content,
                created_date,
                read_status
            )
            SELECT
                psr.parent_id,
                NEW.student_id,
                'attendance',
                'Absence recorded: ' || NEW.status || ' on ' || NEW.date,
                datetime('now'),
                0
            FROM parent_student_relationships psr
            JOIN parent_preferences pp ON psr.parent_id = pp.parent_id
            WHERE psr.student_id = NEW.student_id AND pp.attendance_alerts = 1;
        END;
